		1,
		"祈福之书",
		"100005_xiedaiwu_01",
		"新生儿的祈福之书，由数十名祭司共同撰写。纯真、善良、无忧、快乐与健康是她们对小小幻星的期望",
		"第一夜\r\n\r\n月光如轻纱柔和照拂大地，松树的影子婆娑摇曳在小径，再往前便是再熟悉不过的茛苕叶纹拱门。松树相互依偎在洞穴中休憩，毛茸茸的尾巴伴随着呼吸起伏，萤火虫在深林嬉闹捉迷藏，树荫底下藏了一片碧绿的星空。\r\n空气中弥漫的白兰花清香让幻星愣了神，一向轻快的步伐竟开始变得犹豫。这是母亲的召唤吗，终于可以回家了吗？爱玛一定已经将卧室打扫得焕然一新，母亲也一定微笑坐在矮茶桌边上优雅喝着花茶，茶壶边上是司康饼还是枫糖华夫呢？幻星用力摇摇头抛掉了所有犹豫向前蹦跑，如童年玩闹结束回家一样，孩子气的蹦跑。\r\n推开大厅的门，眼前的一切似乎和想象中不太一样。混乱的脚步声打破了夜晚的平静，早该休息的熟悉的面孔在客厅不断徘徊，幻星有些不知所措。\r\n“索菲尔祭司，发生什么事了？”幻星伸手抓住索菲尔的衣角，却扑了个空。\r\n“糟糕，糟糕，糟糕……”索菲尔绕着花瓶不断喃喃自语，仿佛没有看到眼前着急的幻星。\r\n幻星着急转向向墨菲祭司，却依旧没有问到答案。“保佑，保佑平安，保佑一切平安……”墨菲祭司不断低头祈祷，双臂拥着一本幻星有些熟悉的书。\r\n\r\n“生了！生了！殿下生了！”母亲卧室用力的推门声与激动叫喊声把幻星吓了一跳。\r\n“啊……？什么生了？谁生了？”幻星惊慌发问，回答她的只有失序涌进室内的人群。\r\n“爱玛你别推我！”“是您在挤我！索菲尔祭司！”“不要吵，不要吓到小殿下！”“明明是你喊得最大声！”不知道是爆炸的信息还是争吵声作祟，幻星感觉大脑嗡嗡的，根本无法继续转动。身躯被潜意识催促着前进，幻星茫然跟随着人群进入母亲的卧室中。\r\n\r\n在缝隙中，幻星看到了母亲苍白的脸满怀笑意，她温柔的眼神看向臂弯中的婴儿，满怀爱意。身旁的祭司们失态落泪，她们用颤抖的声音不断祷告。\r\n“感谢先祖庇佑，愿殿下平安，愿小殿下健康成长。”\r\n“感谢先祖庇佑，愿殿下平安，愿小殿下快乐成长。”\r\n“感谢先祖庇佑，愿殿下平安，愿小殿下无忧成长。”\r\n……\r\n\r\n幻星在床上缓缓醒来，眼泪不知道什么时候已经将鬓角打湿，枕头全是泪痕。比记忆中小得多的月亮残酷提醒着幻星这里不是家，还没有找到十四行星，母亲还没有召唤幻星回家。\r\n循环的月光在边柜散发着微光，幻星随着光线看到自己放在床边上的祈福之书。\r\n“愿先祖庇佑，盼幻星纯真、善良、无忧、快乐与健康成长。“"
	},
	{
		2000005,
