		1,
		"永生铃兰",
		"100005_xiedaiwu_02",
		"母亲在日出时分采摘下的铃兰，放置于玻璃罩中，蕴含了幸福归来的希冀。只要花朵在幻星怀中，便永远不会枯萎",
		"第五夜\r\n\r\n母亲的后花园种植了一小片铃兰，每当小小风铃盛开时，小幻星都忍不住伸出魔爪的冲动。\r\n“幻星，不可以。”母亲总会默默出现在幻星身后，板着脸制止她的行为。\r\n“为什么呀妈妈，我可以让它一直盛开。”小幻星总是不解发问。\r\n小幻星腮帮子鼓得像偷吃了两颗松果，眉头紧紧皱着形成三个小月亮，看着女儿这滑稽的模样，母亲刻意板起的脸也在瞬间瓦解。\r\n“植物也是生物，它和我们也和所有小动物一样有着自己的感觉。你想把它们的花朵摘下来，就等于跑到松松身边把它的尾巴拔下来，会疼呀。”母亲蹲下来摸了摸小幻星的头，用温柔的语气耐心解释。\r\n“不、不会吧！松松如果感到疼，它会大叫，可是我偷偷摘了这么多花，也没有听到它们的声音呀……”太过着急一不小心竟说漏了嘴，小幻星一顿心虚。\r\n“有声音哦，你闭上眼睛，用心听。”母亲哭笑不得捂住小幻星的眼睛。\r\n黑暗是感知的催化剂，被意识过滤掉的声音重新钻进了小幻星的耳朵。\r\n“听到了吗？”母亲温柔发问。\r\n“听到了，听到了唰唰的声音！”小幻星惊喜回应。\r\n“这是它们快乐时发出的声音，自由的、无忧的声音，就像在你和爱玛在花园里捉迷藏一样快乐。”母亲轻轻放下了遮挡幻星眼睛的双手，起身摘下一片叶子。\r\n“啊，我听到了生气的哗哗声！”小幻星的情绪竟也跟随着晃动的铃兰着急了起来。\r\n“睁开眼睛吧。”母亲把叶子放在掌心，重新蹲到小幻星身前。\r\n“啊，是叶子……原来植物是真的会疼啊……”小幻星慢慢睁开眼睛，被眼前的叶子吓了一跳。\r\n“是的哦，所以以后不要再伤害它们了，好不好？”看到女儿紧张的样子，母亲知道自己的话语已经被记住。\r\n“再也不会了。”幻星认真点点头。\r\n\r\n母亲轻笑着把叶子放回花茎处，掌心涌出淡淡的绿光。片刻后，叶子重新回到了铃兰身上，随着微风愉快摇曳，仿佛在和小幻星母女挥手。小幻星脸上也涌出笑容，松开抱着妈妈大腿的手不断向铃兰挥舞，一人一花竟开始了交流。\r\n……\r\n\r\n窗外麻雀的鸣叫声把幻星从梦中唤醒，幻星不情不愿翻身，映入眼帘的是盛放在玻璃罩中的铃兰。这是离家前母亲放入幻星怀中的花束，寄托了幸福归来的希冀。"
	},
	{
