		1,
		"云朵抱枕",
		"100005_xiedaiwu_03",
		"软绵绵的小狗形抱枕，羊羔绒面料，棉花填充，温顺触感如轻抚小动物。幻星最喜欢的抱枕之一，只要拥抱着便会感到安心",
		"第十夜\r\n\r\n十四岁的深秋，幻星第一次感受到悲伤的滋味。不是森林迷路肚子空空的饥饿，不是爬树没抓稳掉下来的疼痛，也不是被误会却不知掉如何解释的委屈。是暴雨前大片大片乌云将阳光牢牢覆盖，只剩下令人窒息的压抑。\r\n陪伴幻星十四年的松松倒在地毯上四肢僵硬，再也无法摇着尾巴向幻星撒娇。“呜呜呜呜呜呜呜呜呜……”沉寂半天后，幻星的哭喊声响彻城堡。\r\n“殿下，怎么办，小殿下已经一天没吃东西了，我们怎么哄也哄不动……”爱玛着急联络着还在远方的母亲。\r\n“我在回去路上，你们把糕点放她房间里，让她好好宣泄一些吧。”一向沉稳的母亲声音竟也伴着焦虑。\r\n“好的好的，请您快回来……不对，安全第一，请您务必安全回来……”\r\n……\r\n\r\n母亲风尘仆仆推开卧室门，只见幻星蜷缩在地上。睫毛不断颤抖，鼻子又红又肿，泪痕挂在脸颊上泛着白光，可怜的模样让母亲一阵心疼。\r\n“妈妈……你回来了……”母亲的体温让幻星懵懂睁开双眼，发出了嘶哑得连自己都吓了一跳的声音。\r\n“我回来晚了宝贝，对不起。”母亲紧紧把幻星抱在怀中。\r\n“松松……松松再也回不来了……妈妈……”一想起松松，悲伤又伴随着眼泪从眼眶中涌出。\r\n“宝贝，松松的灵魂离开了躯体去了一个软绵绵的的世界，那里有很多它的好朋友，它在那里很快乐……”\r\n“可是……可是我好悲伤……”\r\n“我知道，你和松松是最好的朋友，你的悲伤同样会让松松感到悲伤。松松知道你会难过，所以特意嘱咐妈妈把这个礼物带给你，你看——”母亲变魔术般从身后拿出一个小狗形状的抱枕，幻星惊讶得停下了眼泪。\r\n“这是……松松！”\r\n“是软绵绵松松，松松担心你一个人太过孤独，特意叮嘱妈妈把它带给你。抱着它就和抱着松松一样，它可以陪你吃饭，陪你睡觉，松松依旧和我们在一起。宝贝不要再哭了好不好？你一哭，松松也想哭，松松的眼泪都快在软绵绵世界流成一跳小溪啦。”\r\n“不哭了，我不哭了……谢谢松松的礼物，谢谢……妈妈。”\r\n也许是情绪冲击太大，幻星在抱上小狗抱枕的下一秒沉沉睡了过去。母亲轻轻松了一口气，将幻星和抱枕轻轻抱上床盖好了被子。\r\n……\r\n\r\n月亮挂在西格纳斯的上空，月光透过窗户轻轻洒落在床上。沉睡的幻星紧紧抱着小狗形状的抱枕，嘴巴微张，似乎在说些什么。\r\n“松松，松松……”"
	},
	{
		2000005,
