		1,
		"第十四行星",
		"100005_xiedaiwu_04",
		"幻星一直在寻找的吊坠，据说由一颗蔚蓝的宝石和环状的铂金组成，加以钻石点缀，形成掌上的行星",
		"第十四夜\r\n\r\n睡眼蒙眬的幻星打着哈欠走向议厅，在地毯上留下一串长长的脚印。十分钟前，爱玛急冲冲将她从睡梦中摇醒，说母亲有要事在等她，幻星只能不情不愿离开温暖的被窝，撅嘴披上睡袍往外走去。\r\n不知道是不是因为冬天的缘故，议厅的气氛似乎也变得凝重了起来，和蔼的祭司们撤下了嘴角的微笑，连母亲一向温柔的眼眸也被冰雪附上了凌厉。\r\n议厅冰冷的石制地板让幻星一阵哆嗦，“啊——嚏——”，滑稽的声音如穿破云层的阳光，给大地增添了一份暖意。\r\n“我说了多少次不能不穿鞋到处跑，你怎么还像个孩子一样。”母亲有些哭笑不得。\r\n“对不起妈妈，我没有睡醒，好困呀——”幻星张开双臂习惯性向母亲扑去。\r\n“咳咳，现在不是撒娇的时刻，严肃点，幻星。”母亲没有像以往一样抱着幻星，而是板起了脸。\r\n“怎么了，妈妈？”幻星茫然抬头。\r\n眼神接触瞬间，幻星发现母亲的眼神多了许多复杂的情绪，随即母亲侧头垂下眼眸，用睫毛避开幻星的探究视线。\r\n“索菲尔祭司，你说吧。”\r\n“我、我？好的殿下。小殿下，您先坐下吧。”被点名的索菲尔祭司错愕片刻后接过了自己的使命，严肃地站了起身。\r\n“小殿下，我们宗族有重要的物品被埋藏在了一个遥远的地方，你需要在近日出发去将其寻回来。”\r\n“啊？什么东西？什么地方？为什么是我？”幻星困惑挠头，心里悄悄嘟囔怎么又做了奇怪的梦。\r\n“算了，我来说吧。”母亲叹气接过了话茬。\r\n“幻星，我们宗族有一个非常重要物品，叫第十四行星，它能保护我们的土地不被侵犯。你是我的女儿，更是我们这片土地的继承者，身为继承者，你有责任也有义务去将它寻回来，这是你的成年考验。”\r\n“啊——我不是在做梦吧？”幻星困惑发问。\r\n“不是梦。”母亲无奈摇头，“你已经长大了，不能再像个孩子一样了。”\r\n\r\n“第十四行星……那是什么东西呀？”\r\n“是蔚蓝宝石和环状金属交替形成的吊坠，和天上的行星无比相似，只要走到它附近你便能感受到能量的涌动。”母亲端起茶杯，轻轻抿了一口花茶。\r\n“我一个人去找它吗？”\r\n“是的，你需要一个人踏上远途，这是先祖对你的考验。”\r\n“它在哪里呀？”\r\n“在一个遥远的国度，和我们截然不同的大地。不用担心，我们的记忆力与知识能快速帮你融入到那个社群，但要记住需要隐藏自己的身份，否则可能会带来意外和危险。”\r\n“还要注意安全！”墨菲祭司突兀插了一句话。\r\n“没错，要注意自己的安全，你是我们唯一的继承人，也是我最爱的宝贝。”母亲转头看着幻星，挤出一抹微笑。\r\n“我明白了妈妈，我一定会通过考验，把第十四行星带回来的。明天，明天我就出发，我要早早找到它早早回家”幻星认真点了点头，接下了这场考验。\r\n“乖。”母亲的眼神中流露出浓浓不舍。\r\n“啊，我还有最后一个问题！找到第十四行星后我要怎么回家呀？”\r\n“不用担心，妈妈会在第一时间派人来接你的。时间不早了，先回去睡觉吧，妈妈来帮你收拾行李。”\r\n“妈妈最好了！我一定早去早回，不会让你们担心的。”\r\n幻星一如既往张开双臂拥抱母亲，用温暖结束议厅的对话。\r\n…………\r\n\r\n又是一个酣睡夜，朦胧中，一个温柔又充满爱意的声音隔着帷幔低语：\r\n“晚安，宝贝。”\r\n“晚安，我最爱的女儿。”\r\n“晚安，我们最后的希望。”\r\n幻星无论如何努力都睁不开双眼，也张不开自己的怀抱。"
	},
