		"100007_xiedaiwu_01",
		"某品牌限量化妆品礼盒，曾以一支口红享誉全球",
		"欧几里得回到了自己的公寓，里面的一切都没有变，只是蒙上了一层寂寞的灰尘。明明面对着熟悉的旧物，欧几里得却觉得恍如隔世，那些安逸平静的日子已是许久之前的光景了，如今她自己这副躯壳都变得如此陌生。\r\n她在储物柜中翻找了很久，终于找出了一个尘封已久的化妆品礼盒。礼盒依旧精美，里面的化妆品也几近全新，即便边角印着的保质日期已是两年前。\r\n此时欧几里得才惊讶地发现这竟然是高奢品牌的限量礼盒，当年价格被哄抬得很高。\r\n那是的自己收到这个礼盒时，尚不了解品牌与价格，只是真诚而开心地接受了这份礼物，回家拆封后发现粉底和口红的颜色都不适合自己，只能失望地将它收入储物柜中，还小小抱怨了老师果然是表里如一的质朴，对化妆品领域一无所知。\r\n这是很多年前老师送她的礼物，为了庆祝她康复。\r\n——也是她唯一还能系连老师的存在。\r\n\r\n在“天堂重现”之后，她在诺亚的支持下重塑了身体，使用了案件记录手册，记忆与人格逐渐不属于自己，她偶尔看自己的旧照，甚至会恍惚不明，疑惑上面的人是否是自己。\r\n唯独老师的音容笑貌一直不曾模糊过，她总是不停地、一遍又一遍地告诉自己绝对不能忘记老师。\r\n欧几里得将早已过期的口红取出、打开，对着镜子涂抹在自己的嘴唇上，暗色的红点缀起了苍白肌肤上的血色，它不适合曾经的自己，却特别适合现在的自己。\r\n欧几里得收好礼盒，起身说：“走吧。”\r\n身后的监督者充满了疑惑：“你花那么大力气申请外出，就只带一个这个吗？”\r\n她抱在怀中，宛如珍藏的宝物：“嗯，足够了。”"
	},
