		"100007_xiedaiwu_02",
		"侦探游戏的必备品，一支老派古典手杖。欧几里得从某个拍卖行重金买入，但不知是否值得这个价位",
		"白羽特别州28区近来一家侦探游戏实景店声名鹊起，平台记者特地前往采访。交流期间，店员提起他们吸引来了很多稀奇古怪的客人，其中有一位客人给他留下了深刻的印象。\r\n“随意对人评头论足并不好……但那确实是一位很特别的客人，她的身上装戴着机械臂……这很难不令人注意！更重要的是，她在游戏结束后，向我们的店长购入了一支道具手杖……想必是被我们的游戏深深吸引，要留作纪念吧！”\r\n此时，那支值得纪念的道具手杖正存放在欧几里得的卧室里。\r\n那日她难得假日休憩，路过这家刚开张的侦探游戏实景店，门口装饰的恐怖悬疑元素勾起了她的兴趣，便进去与陌生人组了队，围绕“古堡疑案”的主题进行了侦探游戏。她扮演的角色是一名贵族公爵，在开局不到五分钟她便掌握了所有的信息，并推测出了凶手是谁，甚至还为在场的每个角色都梳理出了一套合情合理的动机心理与作案流程。后续的游戏对她来说变得枯燥无趣，但她仍为照顾玩得投入的队友的心情而努力配合演出。\r\n她无趣地拿着手杖在有限的场景中漫无目的地行走，无意观察到手杖在地毯上留下的浅浅印记的时候，她突然想起了关于“天堂重现”事件中数千万张照片资料中的其中一张，现实与照片的两个印记逐渐重合。\r\n“他拿着手杖？”\r\n这是欧几里得第一次获取到那个人的信息，她激动得有些失控。待调整后，她紧握着手杖匆匆离开主题房间，细心礼貌如她也不无心再理会队友们疑惑的呼喊。向店家付款时，她甚至没有注意支付金额多打了两位数。\r\n当然，这件事也只是道听途说，毕竟白羽特别洲并没有28区。"
	},
	{
		2000007,
		203,
		1,
		"破碎假面",
		"100007_xiedaiwu_03",
		"欧几里得的自画像，一个破碎的面具。她尝试给自身定义，却只有寻找到支离破碎的人格",
		"“多里安，可以教我画画吗？”\r\n多里安看向了欧几里得手上的空白面具:“你想画什么？”\r\n“我想画自画像。”\r\n多里安接过了她手上的照片，照片上的少女那时还不叫“欧几里得”，多里安也不知道她叫什么，因为欧几里得从不曾告诉自己。\r\n少女的皮肤白皙，透着自然的红晕，笑容爽朗明媚。\r\n欧几里得凑得更近了些，双手合十，眉目与照片上相似，笑容温柔，苍白的脸上带着挥之不去的疲倦：“拜托你啦！教我画画吧！”\r\n她开始一次又一次地在面具上练习、描摹自画像。\r\n“多里安！你看，这是不是很像我？”\r\n同行的路上，欧几里得拿出了面具。\r\n多里安点了点头：“最像的一次。”\r\n欧几里得满意地将面具收好，露出了与照片上相同的笑容。\r\n可惜在之后的行动中，欧几里得因案件记录手册的影响而失控，待回过神来的时候，她已经被多里安钳制在地，面具不知何时掉在地上，与她同样破碎污脏。\r\n“抱歉，没接住。”多里安扶着她起身。\r\n欧几里得笑了笑：“没事，还能再画。”\r\n她又画了很多很多个面具。\r\n她愈来愈深陷罪恶的泥沼，伴着脑中的喧嚣，她反反复复落笔，却再拼凑不出一个自己。\r\n照片上的人像随着自我人格的消减而逐渐模糊。\r\n“不像……还是不像……”\r\n她失魂落魄，轻声呢喃着，起身再一次将不属于她的面庞丢弃。"
	},
	{
		2000007,
		204,
		1,
		"侧写工具",
		"100007_xiedaiwu_04",
		"案件记录手册，具有超凡力量的书本类密室原体。欧几里得将获取的所有信息输入，一份清晰的侧写画像将会逐渐生成。时刻铭记，不得侧写自己",
		"“这是中心给你配套的协助型密室原体——案件记录手册。”\r\n欧几里得精神尚有些恍惚，花费了数秒时间她才反应过来面前的研究员正在与自己说话，她看向了摆在她面前玻璃箱。\r\n玻璃箱中摆放着一本装帧精致的笔记本，看上去普通无奇，欧几里得却莫名移不开眼神。\r\n“别碰！”\r\n研究员的呵斥声将欧几里得拉回了现实，她发现自己的手不知何时已经打开了玻璃箱门，此时研究员正死死地扣住了她的手腕，不让她进一步行动。\r\n“记得，一定不能用肉身触碰。”研究员说完这句话之后，为她装上了外置的机械手臂。\r\n案件记录手册上没有记录任何东西，数百张纸张皆是空白，当欧几里得将获取到的密室相关的信息书写上去后，它就会呈显出一份清晰的侧写画像。\r\n刚开始接触密室原体的欧几里得认为这只是一件简单便捷的辅助工具，偶尔她在使用时，似乎能听见陌生人的喃喃自语，但她总听不清，最后总是安慰自己只是身体未愈而产生的耳鸣这般草率收尾。\r\n直到她用自己重塑的肉身直接接触到了案件记录手册。\r\n大量陌生的面容、声音、记忆涌入身体、大脑、血管、骨髓……横冲直撞，无所不入。\r\n她尖叫、大笑、怒骂、嘶吼，身体宛如容器，不断地被各种面目可憎的灵魂侵占、替换，它们拉扯、撕咬着她的灵魂。\r\n她在无尽的混沌中破碎。\r\n……\r\n\r\n再次睁开眼时，她看见了熟悉的天花板与白炽灯，以及陌生的研究员。\r\n“那位带着红框眼镜的研究员呢？”欧几里得问。\r\n陌生的研究员翻阅资料的动作停止片刻，又若无其事地继续。\r\n欧几里得觉得自己的掌心有些紧绷，她抬手看了看，原来是手掌换了新的皮肤。\r\n研究员总算停下了动作，想必是翻到了欧几里得问题的答案。\r\n他冷酷地、公事公办地回答：“工号02358研究员于3月26日在854号实验中，因阻止失控的案件记录手册死亡，死因为窒息。”\r\n欧几里得低头看向了自己的掌心，事件的来龙去脉逐渐清晰。\r\n她看向一旁仍被锁在玻璃箱里的案件记录手册，看起来仍是普通、简单。\r\n她抬手想捂住哭泣的脸庞，却被自己的掌心恶心得吐了出来。\r\n她在无尽的混沌中破碎，再无缝补的可能。"
	},
	{
		2000008,
		201,
		1,
		"高定卡包",
		"100008_xiedaiwu_01",
		"高定纯手工皮革卡包，非常漂亮造型时尚，六分仪的爱用物，里面有她的工资卡、信用卡、各大品牌的VIP会员卡……",
		"“你知道这片区域是禁止入内的吗？”\r\n“……我知道。”\r\n“知道？知道为什么还要靠近，前方空无一物，没有任何——”\r\n被束缚的女性抬眼看过去，只这一眼，工作人员就停止了劝诫。\r\n“你知道红雾地区？”\r\n“那是什么？”\r\n“……不知道？不知道的话，你为什么如此坚信，前方是有东西存在的。”\r\n那是一种，很难用语言描述清楚的感觉。 \r\n她这样想着，开始回忆自己的日常，一个名牌大学的优秀学生，无父无母，通过自己的努力还有政府的帮扶，逐渐开始步入社会，很快就要获得让人艳羡的人生——多完美的剧本。\r\n\r\n如果不是每次从梦中醒来的时候，泪水模糊视线，胸口积郁的痛苦和折磨在提醒她。\r\n这不是她的人生。\r\n她忘记了什么，什么很重要的，本来应该存在脑海中的东西。或者是人，她曾经应该是有家人的，她有证据。\r\n这个卡包，她找不到任何的购买记录，却被自己珍重地保管着，她认为是某个人给她的礼物。\r\n在工作人员的目光中，她取出卡包中泛黄的照片，照片的左侧是她，右侧却空荡荡的，背景甚至都是一片空白——她不信，现实也是虚假的，这张照片就是证据。\r\n“……能够感知到记忆的缺失？这或许是一种天赋吧。”\r\n“普通民众都会自洽缺失的部分，从而继续自己的日常，但她的情况很特殊。”\r\n“要告诉她吗？真相，关于密室、红雾地区——关于她的家乡。”\r\n“女士，我是诺亚集团的科研人员，您或许很想接触未知的世界……我是说，神秘的世界。”\r\n“那里也许有您想要获知的答案。这个地方——曾经的萨摩斯海域，现在的红雾地区，发生过什么。”\r\n“你愿意加入我们吗？”\r\n自称科研人员的人伸出手，脸上带着笑容，她在笑容中看到了温和的恶意，那是一种哄骗。\r\n但她还是握住了那只手。\r\n她现在，别无选择。"
	},
	{
		2000008,
		202,
		1,
		"电子备忘录",
		"100008_xiedaiwu_02",
		"日常消费记录，战斗计划，工作清单，监护对象的生活记录……都会记在这个小小的仪器中，六分仪不太抗拒别人翻阅自己的备忘录，不过善意提醒一下，还是不看为妙",
		"1月1日 天气阴\r\n新的一年，加入这个计划也正好一年了，听说研究进行得很顺利，艾米丽博士主持着研究会让整个流程变得很清晰，用时很短，她明明年纪很小却能做到很多事情……只是，总感觉这项计划的背后还隐藏着什么。\r\n……\r\n\r\n1月15日 天气晴\r\n很突然，我被选中成为第一批战斗女仆，加入诺亚建立心锚还不超过一年，但艾米丽博士亲自会面，并且说对我们100个人很有信心……她说的是真的吗？\r\n即便存疑，但是普通人成为超凡的途径并不多，这或许是最便捷的方式了。\r\n我别无选择。\r\n……\r\n\r\n2月6日 天气阴\r\n任务结束了。\r\n那管试剂确实有用，战斗能力提升到了一种很恐怖的阶层，那是曾经的我不敢想象的。获得的超凡能力也很适合我，只是熟练运用，还需要多加练习。\r\n曾经的同事说我变化很大……也许吧。\r\n时间紧迫，我没有自我怀疑的余力，抓紧做完所有的任务，然后享受假期吧。\r\n……\r\n\r\n3月10日 天气晴\r\n不对劲，一起执行任务的人越来越少了。\r\n那管据说很稳定的试剂，在场的100人全部喝下了，这之后一直听说哪位雇员性情大变，在出任务的时候滥杀无辜。\r\n因为我自己的状况一直是可控的，所以没有把这些传言当真。\r\n如果是真的，那那些消失的同事，都去了哪里？\r\n……\r\n\r\n4月28日 天气雨\r\n艾米丽叛逃了，女仆派对计划被终止，我们被监视着。\r\n因为诺亚害怕我们，害怕我们变成怪物。\r\n奇怪的是，我没什么感觉……这不像我。\r\n说来也很好笑，实验进行至今，我才知道，那不是什么试剂，而是用稳定剂包裹住的异种生物细胞。\r\n……不，我不是才知道，我也许早就察觉到了，只是一直逃避真相，我担心自己害怕后退缩，错失了成为超凡的机会。\r\n只是我虽然记得当时的心情，现在却再也感觉不到害怕了。\r\n我变得越来越不像自己了。\r\n……\r\n\r\n5月16日 天气晴\r\n我答应了诺亚的人员调动，不过诺亚付出了代价。\r\n往我体内注入异种细胞，是我尚可以容忍的范围，但是要因此处决参与计划的所有人……这是不可饶恕的。\r\n除了一早察觉到真相的我，大多数的战斗女仆都是无辜的受害者，艾米丽造成的悲剧，没道理由我们承受。\r\n……和自己曾经的上司们战斗，本该是一种奇怪的感觉，但是他们太弱了啊，弱的就好像是某种更低等的生物一样，异种生物看向人类的时候，是这样的感觉吗？\r\n虽然不清楚自己最终会变成什么，但是力量掌握在手中的感觉并不差。\r\n这一点，我还是要多谢你，艾米丽博士。"
	},
	{
		2000008,
		203,
		1,
		"黑色液体",
		"100008_xiedaiwu_03",
		"装在密封试管里的黑色液体，晃动时看起来质地应该非常粘腻。虽然六分仪会随身携带，但不太喜欢这东西，随手扔在公文包的角落里",
		"在获得力量之前，六分仪憎恶着密室和超凡，她脑内的记忆是完整自洽的，但她又清楚明白自己一定是失去了什么，这样的矛盾让她痛苦，也让她渴求着能够打破现状的力量。\r\n获得力量之后，一切就发生了质变。\r\n“六分仪小姐，这是您的新合同……里面有详细的薪资福利待遇，以及您的工作详情。”\r\n诺亚的人事专员脸上带着甜美的笑容，她是一位很漂亮的女士，如果你忽略她苍白了脸色，微微颤抖的手指，可能对她的专业能力评价会提升很多。\r\n“……哦，应该不是她的专业能力不行，而是因为，她正在面对我。”\r\n\r\n六分仪一边想着，一边抬眼看着这位人事专员，在她紫色瞳孔的注视下，人事专员笑容逐渐变得僵硬，眼神开始四处游移，最后浑身打颤牙齿碰撞发出声音，在盛夏的季节，却似乎因为寒冷而战栗不已。\r\n就在人事专员几乎要晕过去的时候，六分仪移开了目光，在场的所有人都松了一口气。\r\n昨天在诺亚的某个会议室，六分仪也在场，不过当时并不是现在和谐的岗位调剂会面，而是集团管理者们高高在上，在审判艾米丽留下的邪恶遗产。\r\n“她们已经不能被称之为‘人’了！”\r\n管理者大多数人都认为，已经和异种细胞融为一体的特殊个体——这些战斗女仆，已经不属于人类这个种族。\r\n\r\n她们是怪物！\r\n\r\n少数几人在为战斗女仆争取权力，只是他们的声音很快被淹没，六分仪的目光穿过争论不休的人群，看见大厅的屏幕上，正在远程主持会议的董事会成员，坐在首席位置上的那位，轻轻用指节敲击了一下话筒。\r\n会议室就像被按了暂停键一般，一下子安静了下来。\r\n“快点决定吧，我们的时间很宝贵。”\r\n那人的声音和屏幕上的画面都经过特殊处理，听上去没有任何特征，画面的光影正好遮住了脸，只露出了材质相当高级，低调奢华的西装领口。\r\n“如果没有价值，那就处理干净，如果她们有价值，那就应该为我们所用……就这么简单。”\r\n“不用再争论了，做出你们的决定。”\r\n\r\n多么，高高在上啊。\r\n六分仪冷静地环视四周，她不发一言只是站在会议室里，让这些人争论不休讨论决定她的末路——\r\n——他们凭什么决定她的末路？\r\n是以什么身份？什么角度？这些人跟那个高高在上的神秘世界有什么区别？夺走他人的东西就像呼吸一样自然，毫不在意受害者的感受，这些人……\r\n这些人应当受到惩罚。\r\n\r\n“……等等，你不要动，我们的讨论还没有结束。”\r\n“——你在做什么！不要！”\r\n“别过来！““啊啊啊啊怪物！”\r\n一切都发生了质变。\r\n那种不甘、痛苦、茅盾着纠缠的执念，都化为平静冰冷的怒火，烧灼着她的灵魂。\r\n获得力量的人俯视众生，那些曾经高高在上的人，面对绝对力量时，表现的也不过如此。\r\n\r\n“……女士，您冷静下来了吗？”\r\n六分仪抬眼，看着屏幕上如神明般的董事会成员，其中几人放在桌案上的手都在颤抖——他们在害怕。\r\n“现在，我证明了自己的价值。”她听见自己说。\r\n“但我讨厌你们轻易裁决别人的样子，艾米丽没有告知我们实验内容是异种生物的细胞融合，战斗女仆们全部不知情……难道你们也不知情吗？”\r\n“这里没有人能够拦住我，明白我的意思吗？”\r\n“……是的，六分仪小姐，我们明白了。”董事会成员颤抖着嗓音：“我们会提供……一个对大家都好的解决方案。”"
	},
	{
		2000008,
		204,
		1,
		"耳坠",
		"100008_xiedaiwu_04",
		"看似是耳坠，实则是集通讯、追踪、微型扫描仪等为一体的高科技产品，外观设计也不错，很百搭，六分仪表示很满意",
		"“女士……女士？”\r\n工作人员喊了几声，六分仪没动，坐在车的后排紧闭着双眼。\r\n几人见六分仪似乎熟睡，没忍住低声交流起来。\r\n“这就是诺亚的外勤人员……看上去也没有很强啊。”\r\n“妄想用科技打败超凡的人，我还以为他们会带一身的科技产品呢。”\r\n“就像科学怪人一样——你们看她，甚至只带了个公文箱，耳朵上还带着首饰，完全不像战斗人员！”\r\n“要我说——啊！”\r\n车突然剧烈地震颤起来，几个工作人员发出尖叫声，方向盘疯狂转动的时候，特殊材质的坚硬车门被重物撞击，立刻留下了可怖的凹陷。\r\n“是异种！”\r\n“可恶！我们都不是战斗单位——女士！醒醒！”\r\n“救命！我还不想死啊！”\r\n\r\n六分仪深吸一口气，汽车振动带动她的耳坠，发出金属色泽的反光，在巨大的声响中，反光刺痛了其中一人的眼睛，让他一瞬间愰神——然后听到。\r\n“安静。”\r\n几乎是女声话音一落，汽车被撞击的声音、外面异种生物的嘶吼声、引擎破碎的轰鸣、同伴们带着哭腔的哀鸣、他的呼吸心跳——所有一切的声音，都消失在这个世界上了。\r\n在绝对的寂静之下，几个人目瞪口呆地看着，刚刚被他们嘲弄的诺亚外派人员，打开自己的公文包，不慌不忙地投掷出武器。\r\n谁也不知道她怎么从公文包里掏出一把长枪，也不清楚是怎样的可怕的速度，几乎是一瞬间，凶恶嘶吼的异种生物被那把枪切成了均等大小的碎片——是的，均等的大小。\r\n她甚至有闲情逸致把异种像切牛排一样切开。\r\n刚刚自己还说，她不像一个战斗人员？\r\n\r\n那把长枪闪过美丽的光弧，在六分仪的手上转了一圈，像是结束战斗的骑士行了一个花哨的战后礼，在所有人都没看清的情况下，长枪消失在她的手里——应该是回到了公文包内吧。\r\n同时，那让人陷入无尽恐惧的绝对寂静也消失了，人们取回了自己的听力，畏惧地看向六分仪。\r\n我们刚刚说的话，她不会都听到了吧！\r\n“听到了啊。”\r\n？！！\r\n“你们太吵了，影响我休息。”\r\n她就像会读心术一样，对他们心里的想法对答如流，他们面上慌张畏惧的神情取悦了六分仪，她抬脚踢了一下破碎的车门。\r\n“这车不能开了，你们想办法联系后勤，再送一辆过来。”说完她靠在车的残骸旁边，百无聊赖地观察四周的景致。\r\n几人面面相觑了一阵后，终于还是爬起来去进行联络。\r\n\r\n所有人散开各忙各的，六分仪在他们看不到的角度，食指轻轻敲击了一下耳坠。\r\n“……擅自挂断通讯？真是够了，你们哪儿来那么多工作流程？”\r\n“我是外派支援，并不归属于天文台，你没有权力规范我的行为——他的命令？”\r\n“……行了，我知道了。”\r\n“啧，真是麻烦。”"
	},
	{
		2000010,
		201,
		1,
		"阿司匹林",
		"100010_xiedaiwu_01",
		"林鸮需要根据医嘱定期服用阿司匹林，以降低过于敏感的听力对她带来的影响",
		"过度的才能给人带来的不只有恩惠，或许还会有痛苦。\r\n林鸮就是一个很好的例子。\r\n无可否认，超凡带来的异常敏感的听力在多次行动中都将救她和她的队友于水火之中。\r\n但代价就是，她自己其实并不能很好的筛选出自己需要的声音，无论任何声音，包括噪音。\r\n虽然只有将所有注意力集中在听力才能发挥出她的全部能力，但这个状态只能维持50秒，超过50秒身体就会对她发出警告，严重会对耳部产生永久不可逆的损伤。\r\n因此平日里林鸮都会根据医嘱定期服用阿司匹林，以降低过于敏感的听力对她带来的影响。\r\n或许对于一般人来说这已经很不方便了，但对于获取对抗超凡的力量来说，这似乎已经是非常便宜的代价了。\r\n有时遇到难以忍受的噪音的时候她就会选择把身上的降噪耳机戴起来，在这个方面，她和天文台某个情报人员似乎很有共同语言，甚至互相交流过几次。"
	},
	{
		2000010,
		202,
		1,
		"乐器收藏",
		"100010_xiedaiwu_02",
		"林鸮在世界各地执行任务的时候有收集各种乐器的癖好，尤其是吹奏的乐器",
		"林鸮是一个很安静的人，她平常很少和人交流，甚至有些孤僻。\r\n曾经有人问过她，她说她认为队伍中必须有一个人以第三者的视角分析情况，在队伍陷入狂热的时候让其冷静，在队伍迷茫的时候指明道路。\r\n她愿意做那个人，所以她往往宁愿主动和队友拉开距离，只有在队友需要她的时候：比如气氛低迷的时候，小露一手吹奏让大家冷静找到现在客观的位置。 \r\n\r\n林鸮是一个很安静的人，除了遇到跟乐器或者音乐有关的事情以外的时候。\r\n在世界各地执行任务的时候，只要有机会，她一定会去收集各种没见过没玩过的乐器。\r\n谈论跟音乐有关的话题的时候，即便外表看上去没什么变化，但是从比平常稍快的语速，微微向前倾的坐姿，以及那副恨不得跟你说上三六九小时的架势，都可以看出来她正处于十分兴奋的状态。\r\n只有在这种时候，才会让大家有，其实她也是一个有着自己爱好的女生的实感。\r\n另外，虽然大部分时候大部分时候面对噪音她最多也就是自己带上降噪耳机，但万一超过了她的忍耐限度，那就不是普通的生气了。"
	},
	{
		2000010,
		203,
		1,
		"录取通知书",
		"100010_xiedaiwu_03",
		"相当有名的音乐学院的录取通知书",
		"在被卷入超凡的世界之前，林鸮是一个非常普通的音乐科学生。\r\n就是那种，普通的练习吹奏，普通的准备文化课，普通的准备考试。\r\n直到多年的寒窗苦读终于获得了成果，她拿到了梦寐以求的高校的录取通知书；也直到超凡的漩涡将她整个拖入，一去不回头。\r\n加入天文台以后，她变了许多，几乎已经丢失掉所有从前的印记。\r\n唯一还留下的可能就只有从小向父母撒娇一点一点存起来的乐器收藏，以及象征着她的过往以及那段过往的结束的这张录取通知书了吧。\r\n所以她会继续向前走，为的可能就是这个世界的未来能变得稍微更美好一点，更温柔一点，让以后的音乐生可以不用再有像自己这样的经历，喜欢音乐那就可以只玩音乐，而不是被迫面对不知何时会到来的危险与死亡。"
	},
	{
		2000010,
		204,
		1,
		"八音盒",
		"100010_xiedaiwu_04",
		"木质的八音盒，可以通过更换纸条变成演奏不同的乐曲",
		"林鸮的身上有一个八音盒，如果你曾经和她一起行动过，你就会看到这个奇怪的八音盒中飞出来各种各样的鸟型音符。\r\n不得不承认的是，这诡异的画面中却有带着艺术的美感。\r\n林鸮能够分辨以及发出不在正常人音域以内的声音，这是能使用这件物件的前提条件，正常的乐谱根本无法让这件八音盒发出正确的乐声。\r\n那是因为它本身的规则就不一样，只有林鸮才能正确理解并写出常人无法辨识，但是却适合这个八音盒使用的乐谱。\r\n通过切换乐谱，可以放出不同作用的音符，为此林鸮也准备了不少其他乐谱。\r\n意外地，在林鸮用这件八音盒演奏的时候，我们经常能看到她投入，享受自己制作的乐曲的神情，这或许是对这个喜欢音乐，但现在甚至连尽情听音乐都成为奢侈的女生来说，为数不多的救赎吧。"
	},
	{
		2000011,
		201,
		1,
		"求签筒",
		"100011_xiedaiwu_01",
		"一云随身携带的签筒，帮助她度过了很多个难以抉择的时刻。摇一摇，看看下一签会是什么？",
		"执着，敏捷，高效，尽管用专业的词汇来形容一云也不为过。\r\n\r\n当她初次出现在天文台众人面前，身上只一衣一刀，轻盈得如同一阵风。这阵风寡言少语，命运之瞳的员工基本上无法跟她进行有效交流，令人不得不怀疑她只是个迷路的少女。\r\n但一云用她的行动令所有人改观。一云来到泛星海实验室的测验点，只经过简单教学，便独立完成了对异化物的管制和回收；如果不是被及时喊停，一云会试图进行更激进的██行为。逻辑机判断，一云的反应速度超过天文台99.73%的员工，回收准确度超过校时者中▉▉%的正式成员，刷新了标准化回收流程的最高记录。\r\n重行轻言，这就是一云作为剑士的尊严与修养。\r\n\r\n于是，在剑士之外，一云多了守秘人这层身份。在一云胸前工牌的职务一栏，“罪天使实习生”的字样十分醒目，但她并不因此等称号而妄自菲薄，她以严格的标准要求自己。某员工曾目睹一云由于过度疲劳而靠在墙边打盹的罕见模样，而此时的一云仍不忘将剑紧紧抱在胸前，仿佛二者已然为一。\r\n专注与执着也给一云带来困扰，这个词体现在她身上时更近乎“一根筋”。某次，一云负责回收桑泽某市中心出现的密室原体，情报称该原体具有分裂的特性，只有逐个击破子体才能识别出母体进行回收。当一云迅速击破原体的其余伪装后，却在最后关头犯了难：一云眼前只剩下的两个原体往十字路口的左右两侧逃窜开去。而此时，一云的通讯器中传来命运之瞳的通知：往西继续追捕。\r\n不，一云想。它们其中只有一个是真的，而敏锐的洞察力告诉她：原体在右侧，她能嗅到那种气息。一云向来相信决策者的指令，因为他们总能给出最合理的解决方案。但这一次命运之瞳给了她没有根据的指令——这不合理，起码不合一云的理。\r\n一云站在街口，思索了很久。最后，一云从口袋里拿出一个不知何时起便一直携带的求签筒，轻轻摇晃一下，竹片便奇迹般地落在她的右脚。\r\n“签筒一定有其道理。”于是，这位新晋的守秘人将命运交给了直觉，还有一片竹签。幸运的是，一云很快追上了右侧大街的原体，此时的原体因消耗过大而露出真正的模样。就这样，一云再次顺利地完成校时任务。\r\n\r\n展现出过人才能的一云得到了天文台的认可。面对欣赏与赞扬，一云有些无所适从，只会用“嗯”“谢谢”之类的简单词语来回应。接着，她又继续投入练习中，醉心于精进剑艺，不在乎流言，也不关心过往。\r\n她仍然像当时那阵风，能够拔起巨树，卷起砂石，却依旧轻盈脱俗，一心无二。"
	},
	{
