		"乌鸦",
		"100011_xiedaiwu_02",
		"神出鬼没的乌鸦，十分聒噪。它自称来自奉灵院道场，是信使，而不是宠物",
		"大家对一云的了解，大多是从一只乌鸦处得知的。它足以称得上漂亮，有着如缎面一般发亮的黑羽，结构分明的双爪，当它飞过了山间的树林和小溪，轻盈落定在天文台时，它的双翅仍然光洁，没有沾染露水或灰尘。\r\n乌鸦名为豆，是它亲口说的。它飞遍办公室四角，在寻得一条站得舒适的椅背杆子后，开始详细地讲述了它的历程。关于它如何飞出桑泽的大山，逃过密室时间中的重重危险，还收获了一段美妙的情缘——在它讲述时，红绪仍然紧紧绑在它嘴上，人们搞不懂它是用什么方式完成了交流。\r\n“总之，我和一云都来自奉灵院道场，而我此次是作为师父和一云的信使，背负着监督一云的重任。你们必须注意用词，我早就知道人类一族总是将鸦类看作宠物，但那只是最浅薄、傲慢、自大的观点，我是吉祥之物，我是最得力的助手……”\r\n\r\n新事物总是会吸引大家的注意。当夜晚24:00来临，一云早已投身在密室时间中的执勤与任务，豆也准时站在天文台的时钟上开启自己的演讲，吸引着来来往往的员工驻足听讲——毕竟一只口若悬河的乌鸦已经足够稀罕。\r\n“我和一云的关系？这是个很长的故事，也许要从奉灵院道场建立之初说起，相比于道场的历史，我就像是一个见证者，而一云就是……”\r\n“奉灵院道场是最优秀的隐秘组织，不需要解释，因为一云就是证明。如果有人要提出异议的话，是因为你们见识太少了。所以你们不会知道一云的潜力上限，这会超出你们的理解范围。”\r\n“不懂的事情尽管来问我吧，即使是几百年前的事情也清楚地刻在我的脑中，就连我的羽毛都比你们见识过更多……”\r\n\r\n众人发现它是个得意忘形的家伙，与一云的行事风格截然相反。渐渐地，豆的观众越来越少，没人对它的故事感兴趣。\r\n豆的把戏没有停止。“你们有听说过桑泽地区的██事件吗？那全是一云干的好事。”\r\n“她才不懂什么密室守则，她骨子里就是热爱打杀的家伙。”\r\n“一云，你再假装看不到我的话，我就把你的秘密告知天下……”\r\n豆鸦的胡言乱语没有换来关注，只换来了一云的愤怒。当它准备再次飞上时钟开始演讲时，一云一把抓住了它引以为傲的翅膀，就像抓住一只小鸡。大家担心一云会做出过激行为，纷纷建议放它一马，或者让它饿上几天就好了。\r\n“谢谢大家的建议，虽然我没有在询问你们。”说罢，一云将乌鸦扔到天文台的管制室，按照封存原体的流程关上了门，没有多看一眼就离开了。\r\n\r\n路过的某位员工看到豆的落魄模样，不禁好奇地问：“乌鸦，你到底是来干嘛的？”\r\n它慌张梳理好羽毛，昂首挺胸地轻轻飞了一圈，假装一切未发生过。接着它略带怨气地为自己辩解：\r\n“我第一天就说了，我是来监督一云的！是你们将我的话都当做耳边风，我绝对会记住你们的浅薄、傲慢和自大的，要是一云没有完成任务的话，不仅是师父和师门无法得到交代，连我都无法原谅自己……”\r\n\r\n说到这里，它的语气突然低沉严肃起来，“一云此行可不是儿戏，而是为了追杀道场的仇人，师门的叛徒……”\r\n“那人曾是道场最得意的弟子，要细说的话……她还算得上是一云的师姐呢！”"
	},
