		"100011_xiedaiwu_03",
		"别在头发上的小巧发饰，干净、洁白。一个严肃的剑客不应在意身外之物，但既然是他人的礼物，必须好好珍惜",
		"关于奉灵院道场的信息很少。对于外人而言，这只是一家避世的修行馆，但在以讹传讹中变成了鬼屋、凶地，甚至还有传言道场会吸取元气——只因为道场的树木一直都死气沉沉的，仿佛从未活过。\r\n但在隐秘的世界中，道场的地位举足轻重，因为这里有武器中的至宝，还有人类中的天才。\r\n\r\n作为道场最重要的宝物，太刀云一直供奉在深处禁地，无人可以靠近，除了师父最信任的弟子一流。出身自武术世家，一流自小便表现出无人能及的才能，能够准确判断出密室生物的弱点，精准击破。这份天赋让她自豪不已，而师父告诉她，只有实现终极目标，斩杀密室中的异种，才可谓站在人类的顶点。\r\n但一流让师父失望了。人类的上限就像一个隐形的天花板，让她不能再往上走。\r\n于是她按照师父的指引，加入了校时者部门进行磨炼，而天文台也答应会提供专业的设备来保护云刀的安全，这是一份合理的交易。\r\n\r\n加入校时者后的一流并没有学会合作，她拒绝所有小队任务，多次独自闯入红雾地区，寻找当中无人能消灭的密室生物，依旧无功而返。\r\n独行客的困扰无法排解。不善言辞的她，只会在深夜来到存放云刀的房间，将心声倾诉给不解人间苦恼之物。皎洁的月光照在太刀身上，照应出一流的影子。剑影摇晃，宛如它在旁无声陪伴着一流，让孤独的少女有所寄托。\r\n\r\n因此，当云刀失踪的那天，整个道场最为慌张的必然是一流。她无法联系到师父，只能通过琐碎的信息拼凑出云刀的去处。最后，一流在桑泽的██地区发现了云刀的踪迹。那是一场突发的灾难，██的降临让天文台与诺亚的联合调查小队措手不及，在场的守秘人几乎无人生还。\r\n但当一流检查过现场的守秘人尸体后，她发现一个无法相信的事实：他们的死因不是超凡侵袭带来的失控——而是一道道干净利落且不带感情的刀痕。\r\n\r\n没有人知道后来发生了什么。\r\n\r\n据传闻，一流与一个神秘的原体进行了战斗，两者实力不相上下。\r\n但在最后关头，一流放弃了取胜的机会。她只是出神地看着面前的原体，随后便拖着被侵蚀的躯体离开了现场，再无音讯。\r\n\r\n在一流与云刀一同失踪三天后，师父不知从何处带回一名少女，将她收入师门。她手执太刀，眼神透露着不谙世事的茫然。\r\n师傅为少女取名为“一云”，声称以此纪念失踪的云刀。众人感到蹊跷，却不敢多言。\r\n此时正值初春，寒意犹存，道场中枯萎已久的大树竟然重焕光彩，新叶长出，花蕾满枝。当枝头的第一朵花开时，师父轻轻将它摘下，做成精致的发饰，细心别在少女的头上。\r\n师父轻轻抚过这个纯洁的小花发夹，为一云讲述了一个关于背叛与逃兵的故事。\r\n就这样，一云背负着师门的重任离开了道场，懵懂地开始了这趟复仇之旅。"
	},
	{
		2000011,
		204,
		1,
		"ChickenKing炸鸡桶",
		"100011_xiedaiwu_04",
		"世界上最好的炸鸡，来自ChickenKing。自从吃过主管给的炸鸡后，一云在炸鸡品牌这件事上便变得非常、非常偏执",
		"一云是在下山之后遇到主管的。\r\n\r\n刚出发时，一云心中充满了愤怒，誓将仇人抓住严惩，给师门上下一个交代；但是当她走了几天几夜，却发现一个现实：她饿了。当她勉强支撑自己来到城市的边缘，就因体力不支倒下了。\r\n再次恢复意识时，一云旁边多了一个人，对方手中拿着她未曾见过的圆桶，里面装着香喷喷的食物。一云的本能地夺过装满食物的圆桶，在大快朵颐后，她才反应过来：\r\n“你是什么人？”\r\n“路过，看到你晕倒而已。”\r\n“是坏人吗？”\r\n“不是。”\r\n“证明。”\r\n主管没有说话，“你吃了我给的食物，但是没有死掉，反而变精神了。这可以吗？”\r\n一云稍加思考，轻易地被说服了：“你说得有道理。”\r\n\r\n两人就这样聊了起来。聊到最后，一云接受了主管的建议，跟随他回到天文台，作为暂时的下脚点。\r\n路上，两人都没有说话，不紧不慢地走着。一直走到天文台门口，主管推开了大门，而一云却停下了脚步，仿佛在迟疑。\r\n“我有个问题。”\r\n“害怕了吗？”\r\n“不是。”少女顿了一下，继续问，“刚刚你给我的东西，是什么？”\r\n她是认真的。\r\n“那是最好的炸鸡，来自ChickenKing。”主管同样认真地回答了她的问题。\r\n得到答案的一云脸上露出严肃的神情，以剑士的姿态轻轻鞠了一躬，认真道：“谢谢你。谢谢炸鸡。”\r\n\r\n“一个大胆地敢骗，一个出奇地好骗。”烟火曾经这样打趣道。至于为何下定决心要将一云带回来，主管至今没有透露原因。\r\n之后，一云在天文台过上了规律且有序的生活，与主管和罪天使小队的陪伴下，她逐渐开始认识这个世界，了解社会的规则。\r\n至于追杀仇人这件事——一云不是忘了，只是没有再想起来。"
	},
