		"作为海贝集团最大董事的独生女，安妮薇可以毫不夸张的说是含着金钥匙出生的。\r\n从小就接受各种英才教育的她在各个方面都展现出了异于常人的天赋。\r\n绘画，雕塑，演唱，芭蕾，钢琴，她的每一位任课老师都认为自己遇上了百年难见的天才，但每一个兴趣她都只是浅尝辄止，这让老师们个个痛心疾首，甚至有狂热的老年教授密谋要将她绑架走，当然在计划实施之前就已经被制止了。\r\n或许对于平凡人难以越过的山丘，在安妮薇看来连台阶都算不上，没有继续在这条路上走下去，也只是因为已经失去了兴趣而已。\r\n\r\n现在偶尔还会提起的，或许就只有这把一直带在身边的小提琴罢了，也正是在她放弃精进小提琴之后，她就再也没有不加节制的发展自己的“个人爱好”了。\r\n对于这件事的原因外界有过不少猜测，有说她终于遇到了逾越不了的高墙的；也有说是因为能力导致的副作用的。\r\n“其实很简单，只是觉得把时间放在这些东西上面也没什么意思而已...”\r\n她用很站不住脚的理由搪塞了过去，并拒绝了队友的继续提问。"
