		"安妮薇随手买的彩票，从第十次开始她就没有再记自己到底中了多少次奖了，全部通过管家要求彩票公司以个人名义将奖金捐给慈善机构X-CAT",
		"如果说有什么比中彩票更加让人嫉妒的事情的话，那一定是中彩票的那个人本来就很有钱。\r\n\r\n最开始其实真的只是心血来潮，安妮薇从别人那里听说了买卖彩票这种活动的存在。\r\n抱着试一试的心态，她随口报了几个数字，让管家去买了一张彩票算是图个新鲜，虽然很快也就没放在心上了，但隔了一段时间之后管家告知她之前买的彩票中奖了，而且还是中大奖。\r\n中了彩票的安妮薇心里毫无波澜，因为她连彩票该如何去兑奖都不清楚，而且奖金甚至还不如她零花钱的零头，她只留下了中奖的彩票当做纪念，这件事情也就不了了之了。\r\n\r\n过了几年，她在自己的柜子里头翻出了这张彩票，突发奇想的她又报了几个数字让管家去买了一张彩票，结果又中了。\r\n连续的中奖让她怀疑这并不是巧合，她先是调查了彩票公司是否有作弊，得知开奖流程一切公正的前提下，在间隔不规则的时间又买了几次彩票，结果无一例外全部中奖，而且都是大奖。\r\n在管家的建议下，她通过管家要求彩票公司以个人名义将奖金捐给慈善机构X-CAT，就当做是做慈善了。\r\n这件事就当做是一件小小的趣事就这样翻篇了，偶尔还会当笑话跟队友们分享，但唯独没有跟暮雪说，不然大概好一阵子都要承受暮雪带有怨念的眼神了。"
	},
	{
