		1,
		"以太结晶",
		"100013_xiedaiwu_03",
		"普通人难以入手的，高纯度的以太结晶，但对安妮薇来说就只是一颗好看点的石子而已",
		"深空矿业，人类最大的以太结晶开采及精炼企业，原本是一家独立的商业公司，10年前与天文台合并，成为属下一个独立部门，为天文台活动提供大量资金。\r\n而海贝集团则是世界最知名工程车辆制造商，深空矿业旗下子公司。\r\n其生产的工程车甚至可以在月球上运作。拥有极高的磁约束工艺技术，曾经帮助天文台组织制造磁约束类收容器，有良好的合作关系。\r\n而安妮薇，则是这家公司最大的董事的独生女。\r\n作为超凡者，安妮薇无论是能力还是潜力都毋庸置疑，但不可否认，作为天文台的重点拉拢对象，安妮薇自身庞大的财团背景也是天文台的重要考量标准之一。"
