		1,
		"幸运骰子",
		"100013_xiedaiwu_04",
		"安妮薇随身携带的骰子，她总能在关键的时候投出自己想要的点数",
		"安妮薇一直随身携带着一颗特殊的骰子，她似乎永远都能投出自己想要的点数。\r\n很明显，这已经超脱了一般人认知里的强运，属于超凡力量的范畴了。\r\n如果是其他人，或者反而会因为这份能力迷失自我，或者越发看不清能力与责任的边界。\r\n所幸这是安妮薇，从出生开始就注定不是普通人。\r\n生来就拥有太多太多的她，既不会被欲望所迷惑，也不会陷入自我怀疑。\r\n非同一般富裕的家庭出身，常人无法仰望的天生才能，以及这份难以解释的强运，都是安妮薇这个人的一部分。\r\n在你凝望深渊的时候，深渊也在凝望你，但我们应该高兴的是，不论是被深渊凝望也好，甚至是企图将她拖入沼泽也罢，她都能若无其事的，用那份甚至让人觉得牙痒痒的平淡语气宣告：她就是安妮薇。"
