	{
		2000015,
		201,
		1,
		"日记本",
		"100015_xiedaiwu_01",
		"充满秘密的女仆日记，琐事与心情都被记录在里面",
		"七芒星不太记得自己是什么时候开始记日记的。\r\n是从还在诺亚的时候？是从刚到海贝集团的时候？还是更远点，■■■■的时候？\r\n七芒星不记得。\r\n她只知道，当她意识到日记的存在时，记日记的习惯已经养成。而最初的日记本早已丢失。\r\n\r\n■■月■■日\r\n我的记忆出现了混乱。\r\n我再次忘记了今天训练时的事情。\r\n厨艺，插花，礼仪……之后呢？发生了什么？\r\n我不知道。\r\n\r\n■■月■■日\r\n被告知了即将作为商品被出售。\r\n听说客户是深空矿业那边的人，因为保密协议，暂时还不知道具体是谁。\r\n哈，不管是谁，我这样完美的女仆当然有人抢着要，这不是理所当然吗？\r\n\r\n■■月■■日\r\n雇主是海贝集团，服侍的对象是深空矿业的大小姐。\r\n……大小姐，是这样的人设吗？\r\n\r\n■■月■■日\r\n大小姐不会使用手机。\r\n大小姐不清楚自己家的产业。\r\n大小姐不知道街边的小吃的购买需要现金而不是银行卡。\r\n……\r\n我出言嘲讽了大小姐。\r\n身为大小姐，没常识到这种地步还怎么继承家业。\r\n大小姐当时的脸色很奇怪，似乎想说什么，又忍住了。\r\n呵，辞退我这种完美女仆是你的损失。\r\n\r\n■■月■■日\r\n大小姐找我道了谢。\r\n她说，从来没人和她说这些，她一直当做理所当然。\r\n她说，身边的人固然尊敬她，却没有人像我一样直言不讳。\r\n她说，很感谢我帮她改正自己应该改正的错误。\r\n她送了我作为谢礼的发卡。\r\n……\r\n\r\n■■月■■日\r\n今天是作为安妮薇大小姐女仆第一个月的最后一天。\r\n早早地将桌子上的桌布铺好，柜子上的花瓶擦拭干净，又为花束喷上水。屋子里的熏香换成大小姐最喜欢的那一款。\r\n起床的大小姐当然喜欢我的惊喜，甚至给了我一个拥抱。\r\n完美的女仆今天也完美地完成了工作。"
	},
