		"强效杀虫剂",
		"100015_xiedaiwu_02",
		"害虫喷即死的杀虫剂，任何昆虫都无法靠近半径两米的范围",
		"所有人都知道七芒星对虫类的厌憎。\r\n身为家务全能的女仆，七芒星当然也精通打扫，不论是藏在最角落的灰尘还是难以清洁的污垢，只要七芒星认真起来，统统不在话下。\r\n而这样的七芒星，手边却时常放着一瓶强效杀虫剂。\r\n“对所有的洒扫工具进行全方位的运用，这也是完美女仆的必修课。”\r\n本人是这么保持优雅从容不迫地说的。\r\n如果不是有人曾经目睹过七芒星小姐一边失态尖叫一边向角落里的蟑螂喷洒药剂的话，说不定这话的可信度还能更高一点。\r\n“好啦！我就是讨厌虫子！怎样啊！”被当面看见的七芒星大声说，“不管是家里的虫子也好，战场上的虫子也好，所有的虫子都给我消失消失消失！”\r\n语气锐利，仿佛心防破碎后的破罐破摔。\r\n\r\n有着这样言论的七芒星小姐，在战场上的表现也同样在践行着自己的话。\r\n“你说战斗中的七芒星啊。”曾经与七芒星共事过的成员讪讪地挠着脸颊，“呃，倒也不能说是奇怪……她依旧是优雅完美的女仆，只是这次打扫的是战场。而那些敌人就是她最讨厌的虫子。”\r\n战场上的七芒星优雅又强大，面对敌人也是毫不犹豫的灭杀姿态，仿佛捏死家里的虫子。\r\n“你问我为什么这么讨厌虫子？”被这么问到的七芒星翻了个白眼，“这不是显而易见的吗？又弱小又搞不清自己的定位，总喜欢不自量力地挑衅比它更强大的人类，这样的‘东西’就算被碾碎也是活该。”\r\n但是，即使口中说着傲慢的话，七芒星的表情却出乎意料地冷淡。\r\n仿佛她的这些话并不只是在形容虫子。\r\n仿佛她的这些话也在形容她自己。"
