		"100015_xiedaiwu_03",
		"精致闪亮的水晶发卡，被主人妥善保管，只看外表就能看出不是平民能承受得起的价格",
		"女仆七芒星与大小姐安妮薇的初次见面并不算愉快。\r\n高高在上的大小姐彼时还不懂得收敛自己的锐气，自认天下第一的女仆同样不会反思自己的过错，两个坚硬的人碰撞在一起，最终也只能落得个互相伤害的下场。\r\n最开始的那几天，两人是在互相无视与应付中度过的。\r\n毕竟谁都不会想有一个人因为各种轻巧的小事对自己喷射毒液，也不会有人想要整天看到一个缺乏常识的人犯着正常人来说根本毫无深度的错而不自知。\r\n\r\n事情的转机出现在一次外出购物上。\r\n被同学描述中的庶民购物街所吸引，跑到普通人的街道购买东西，却遭到了针对海贝集团大小姐的暗杀。\r\n受过专业训练的女仆提着手提包变化而来的枪，将所有暗杀者清理干净。\r\n“虫子，连弄脏鞋面的价值都没有。”女仆这么说道。浑然不知自己的表现都被安妮薇看在眼里。\r\n刚来到海贝集团的七芒星并不是这样的，她傲慢又强大，言行受过专业的指导，却并不会有这种【大小姐】般的特质。\r\n安妮薇意识到，七芒星在下意识模仿自己。\r\n\r\n回去之后，她开始观察七芒星的小动作。\r\n愈发优雅的言行举止，愈发不加掩饰的明媚张扬，七芒星明明嘴上说着讨厌自己，却从来不会将讨厌的目光对准过来。\r\n又一次被七芒星数落没常识的时候，安妮薇看着她那副想对自己好又别扭的样子欲言又止。并就在第二天，下定了决心带来和解的礼物水晶发卡。\r\n“我不知道你在气愤什么，也不知道你在从我身上汲取什么。”安妮薇将水晶发卡放到七芒星的手心，“那种感情或许是嫉妒吧。我不知道你在嫉妒着我的什么，但如果我能更像个大小姐一点，能让你从我身上看到更多的弥补你的不足的东西，我会更努力一点的。”\r\n“我给你权限，必要的时候，可以模仿成‘我’。”\r\n希望这样能为你指明前进的道路。"
	},
	{
		2000015,
		204,
		1,
		"餐具套装",
		"100015_xiedaiwu_04",
		"餐刀与餐叉。完美的女仆随时考虑着主人的一切突发需求，关键时刻还能作为投掷武器使用",
		"完美女仆最重要的是什么？\r\n\r\n完美的气质？完美的家政？完美的服务态度？\r\n\r\n如果要完美女仆七芒星来解答，她会说：每一件事。\r\n\r\n完美的女仆要设想到所有的场景，为所有的场景预设所有完美的答卷。\r\n\r\n正如，一套随身携带的餐具能在手中发挥什么作用？\r\n\r\n不论场景，随时随地，只要雇主想要进食就可以拿出呈上，为雇主免去用手抓食物或是使用不熟悉的餐具所引发的尴尬，令雇主永远保持那份体面与优雅。\r\n\r\n又或者，在餐厅的餐具恰好用光，而雇主又需要有人帮忙分割配菜时，可以从容不迫地取出，应对尴尬的突发情况。\r\n\r\n如果上述两种情况都因为发生概率过少以至于无法论证七芒星的理论，没关系，还有最后一条论据可以进行论证。\r\n\r\n当敌人到来时，手中没有武器、或是拿不到武器的情况，小巧便携的餐刀与餐叉就能像暗器一样手动发射出去。\r\n\r\n不管是争取时间还是出乎敌人的预料，餐具作为暗器投掷都是一个不错的选择。\r\n\r\n当然，作为暗器沾过肮脏液体的餐具就没办法再给雇主使用了。这种时候，去乔薇尔23号店铺将它们作为废铁卖掉，为接下来置办新的餐具剩下一笔费用，将是不错的选择。\r\n\r\n“七芒星……再说一遍，我不会在奇奇怪怪的地方用餐，也不需要别人帮我切割小牛排……餐具这种东西就好好放在后厨，别再用它们攻击敌人了。”\r\n\r\n“好的大小姐，没问题大小姐。”\r\n\r\n“……你根本没在用心听吧！”"
	},
	{
		2000016,
		201,
		1,
		"旧式打字机",
		"100016_xiedaiwu_01",
		"一款旧式打字机，功能完好，敲击键盘的声音会令烟火沉迷。身为密码破译专家的烟火，平日喜欢捣鼓一些老旧的加密仪器，破译每一个物件背后隐藏的秘密是她最快乐的时刻",
		"烟火个性活跃，相貌甜美，同时有着异乎常人的语言天赋，精通各地区语言文化。\r\n无论在任何地方面对任何人，烟火都能收获相当程度的信任。因此，由她负责的情报收集以及信息调查业务总是出乎意料的顺利。\r\n在很多人看来，她作为情报人员无疑是完美的，甚至完美得过了头。\r\n她仿佛是为情报工作领域量身定制的模板。\r\n\r\n但她却从来没有这种自觉，一直强调自己只是普通寻常的守秘人。\r\n为此，她在加入天文台不久，便购入了一台“旧式打字机”。\r\n打字机是她们这些情报人员的黑话，事实上这台看上去相当有年代感的装置是兼具有加密和解密功能的专用设备——密码机。\r\n她试图利用业余时间自学密码学。\r\n部门内没有一个人认为她能成功。\r\n密码这种学科，是一门基于数学构建的专业学科。\r\n虽然烟火是公认的天才，天生的情报工作者，但这就能够单凭天赋覆盖全部学科吗？\r\n\r\n事实却告诉他们，在天赋的作用下，某些人就理应会成为某些领域的顶部人物。\r\n烟火自学密码学的一个月后，她便成功破译了某个255位的高难度密码难题。\r\n这个难题在过去十年里一直处于悬而未决的状态，如今却被烟火这样一个初学者轻松破解。\r\n就这样，烟火顺理成章作为情报部门主力，担任起信使的职务。"
	},
	{
		2000016,
		202,
		1,
		"万用通讯器",
		"100016_xiedaiwu_02",
		"天文台制式装置，无论信号多弱，必能联络彼此。烟火却知道，它不是万能的",
		"与情报内务相比，信使更加注重与行动调查小队进行情报信息沟通。\r\n异常事件诡异而隐秘，身在一线的小队很多时候无法及时对应瞬息万变的突发情况。\r\n这时则需要情报部门派遣的信使，及时分析整理现场信息，向行动小队提供理性的行动建议。\r\n因此，信使这个职务通常都是由能力顶尖、经验丰富的资深情报人员担任。\r\n虽然烟火是公认的天才，但仍是一名新人，深厚的期待给予了她太多无形压力。\r\n第一次正式外勤任务，她犯了众多新人同样会犯的毛病：过度紧张、焦虑、操作失误。\r\n但这不是最重要的——\r\n作为一个负责维系情报流通的信使，她竟然在行动前忘记检查通讯设备的剩余电量！\r\n当然，这是一次非常罕见的意外，没有人会意料到行动当天设备中心会突发电源闪断，导致通讯设备充电单元遭到损坏。\r\n就结果而言，疏忽并未酿成严重的后果。\r\n天文台作为一个历史足够悠长的组织，拥有严谨到让人感到厌恶的冗余程序，问题很快就得到解决。\r\n但这次事件却令烟火显露出一个过往未曾发现的问题。\r\n在心理建设层面上，守秘人烟火的精神状态并不如她和其他人所想象的坚韧。\r\n当行动过程陷入困窘，她会变得手足无措，行动意识不再理性，并会将过错全归咎于自己。"
	},
	{
