		1,
		"未使用的礼花筒",
		"100016_xiedaiwu_03",
		"购买日为三年前的礼花筒，这代表一个约定，一个不会完成的约定",
		"与许多人的印象相悖，烟火的精神和心理状态评估长期处于低位区间。\r\n守秘人的精神状态是一项非常重要的体征指标，它关系到守秘人在调查行动中的安全问题。\r\n在一次例行体检过后，医疗团队向部门提交了一份报告。\r\n报告显示，烟火在三年前曾参与到一次秘密调查行动，负责该次行动的是一支临时组建的特殊小队。\r\n该行动的目标是前往伊利亚特半岛秘密回收一件受管制的密室原体。\r\n由于保密原因，行动和密室原体的具体详情未知，但可以肯定的是，行动最终以失败告终。\r\n参与该次行动的特殊小队，除烟火以外全部牺牲。\r\n\r\n而烟火本人也罹患严重的心理创伤，不得不在伊利亚特长期休养，直至一年前方重新返回岗位。\r\n“这是我的错，要不是我……他们就不会变成那个模样。”\r\n催眠状态下的烟火一直反复强调这句话。"
	},
	{
		2000016,
		204,
		1,
		"降噪耳机",
		"100016_xiedaiwu_04",
		"只要戴上它，外界的声音就会被完全隔绝。失去队友的那些日子，烟火在这个孤独的世界里找到了一丝慰藉",
		"由于烟火的特殊情况，她比普通守秘人要接受更多高规格的心理质询和理智审查。\r\n但令人惊讶的是，她维持了长时间的精神临界状况，却没有任何恶化的迹象。\r\n有人曾认定烟火戴在头上的耳机是一件特殊的密室原体，是它让烟火的理智维持在恒定的水平线上。\r\n\r\n但事实上，那不过是一副普通的降噪耳机。\r\n无论是明面或暗面的调查，都没有从那耳机上检测出超凡力量。\r\n按烟火的说法，她之所以能坚守住心理防线，是因为一位偶然结识的小姐。\r\n在长期休养的日子里，她深受幻听的影响，所有药物和治疗都无法减缓症状。\r\n直到某天，她与那位优雅的小姐邂逅。\r\n那位小姐经营着一家鲜花店，在聆听烟火所述说的故事后，那优雅的小姐给烟火送上了一支玫瑰。\r\n她的举动如同魔法，一瞬间便让烟火感觉耳边安静了下来，幻听如朝露般消失无踪。\r\n从那往后，除了对特定频率的噪音会产生不适以外，她再也没有听到过那些令人疯狂的呢喃低语。\r\n……\r\n\r\n注意，以上是未经证实的个人论述。\r\n根据守秘人烟火的描述，命运之瞳曾派遣人员前往伊利亚特半岛秘密调查。\r\n并未找到烟火所提及的鲜花店以及那位“优雅的小姐”。\r\n部门最终推论，烟火至今仍受到幻听的影响，但其自我意识接受了痊愈的臆想，发生“代设剂效应”（Placebo Effect）。\r\n在隔绝特定频率噪音的情况下，她能够在臆想构成的安全线内自我过滤幻听的声音，形成维持理性的效果。\r\n为此，除定期精神状态评定以外，守秘人烟火无需接受其他介入措施。"
	},
	{
		2000019,
		201,
		1,
		"内部调查档案",
		"100019_xiedaiwu_01",
		"一份来自天文台π部门的内部调查报告，权限等级2级",
		"多里安作为异常修正局调查科科长，她人格高尚、能力优秀，更难能可贵的是拥有维护公义的决心。\r\n这份令人敬佩的热诚令其在超凡世界拥有众多支持者。\r\n在她加入天文台的十年里，曾多次凭卓越的判断力带领队伍完成行动。\r\n她具备部门最高领导者的必要素质，并保持零违规行为的记录。\r\n她无疑是完美的。\r\n\r\n可就连多里安这种无可挑剔的守秘人，却依然无法躲过流言蜚语的侵害。\r\n那些无聊的“乌鸦”，总是以最大的恶意揣测他人，以最宽容的视线审视自己。\r\n他们捕风抓影，试图对多里安发起打击。\r\n最初的攻势出自一份内部调查记录。\r\n据文档显示，多里安科长在轮值期间，所在地区的失踪案件均有不同程度的异常增高。\r\n当然，两者间并无任何构成因果的条件，但不妨碍乌鸦们继续深挖，搜寻臆想中的内幕。\r\n而这时，一名外勤中心的巡游侦探——零一，出现在他们视线中。"
	},
	{
		2000019,
		202,
		1,
		"弹壳",
		"100019_xiedaiwu_02",
		"多里安随身携带的手枪弹壳，对她而言有重要的纪念意义",
		"多里安与零一的初次接触发生在轮值期间。\r\n\r\n在异常修正局的流程里，非正式的人员接触并不常见。\r\n在此次接触里，侦探向多里安递交了一份解除密级的文档。@[……]@\r\n这是来自外勤中心的事件通报，讲述了当地出现普通市民连续性意外身亡的情况。\r\n——这是一连串巧合的悲剧，不存在人为的元素。@[≈-doubt]@\r\n外勤中心以此终结了事件的调查。\r\n意外是存在的，但疑点同样存在，外勤中心并没有对一连串巧合作出解释。\r\n对此，有人选择沉默，而零一则来到异常修正局。\r\n“你认为这是超凡相关的事件？”\r\n“不知道。”零一如实回答。\r\n他不是守秘人，甚至无法对密室时间产生认知。\r\n他来到这里寻找多里安的目的只有一个，他听到多里安的风闻——多里安绝不放过任何有违公义的事物。\r\n无人知道零一为何会做出这种决定，那也许会成为另一个故事所要探究的内容。当然，此时更令人在意的是多里安的反应。\r\n她从口袋里取出一枚弹壳，刻画着的23条划痕仿佛对应着某些经历。\r\n多里安陷入沉思。"
	},
	{
		2000019,
		203,
		1,
		"古董怀表",
		"100019_xiedaiwu_03",
		"风格老旧的怀表，外壳依然光亮尤新，似乎是某人送给多里安的礼物",
		"事实上，多里安并不是第一次听闻这个事件。\r\n首先是她西格纳斯的损友——欧几里得提供的消息。\r\n在欧几里得的描述中，这个消息就如同众多散落在城市中的传闻一样，遥远而不可信赖。\r\n但多里安明白，欧几里得作为犯罪侧写师，她并不是一个喜欢讲废话的人。\r\n多里安很了解她。\r\n以多里安的判断力，仅从无数段破碎的流言中就能感受到当中蕴含着不义。\r\n但多里安并没有立刻采取行动——这不属于守秘人的工作。\r\n按照流程，这种与超凡毫无瓜葛的普通案件，理应由当地外勤中心处理。\r\n超凡对平凡世界的过多渗透，是对守秘人准则的亵渎。\r\n这也不是她能够容许的事情。\r\n无论从流程或行为上的分析，她都不必要乃至不应该介入。\r\n但奇怪的是，有人从荷鲁斯之眼相关事件的讨论中保存了一段意义不明的匿名交互，其中一个对象，自称是诺亚犯罪研究中心的侧写师。\r\n\r\n交互记录如下：\r\n【为什么要告诉我？】\r\n【你早就有了答案，我只是表达你心里所想的，仅此而已。】"
	},
	{
