		"多里安的驻区轮值最终在平静中结束。\r\n乌鸦未能从过往的历史中挖掘到任何蛛丝马迹。\r\n但可以明确的是，至此以后，对象为普通市民的意外死亡事件再未出现。\r\n有一部分人认为多里安使用了难以容忍的手段解决事件，而这种判断的依据是两个外勤中心高级人员的失踪报告。\r\n更多人则是对此嗤之以鼻。\r\n“在乌鸦眼里，多里安科长连呼吸都散发着阴谋的气息。”\r\n即使以后有形似失踪人员的证件被发现，但除了引起新一轮辩驳，没有引起更多的波澜。\r\n以目前的结果向前推论，案件到此为止。\r\n这种无证据的论调不应成为检验守秘人品质的工具。\r\n至于风暴中心的多里安，则依然维持冷静而克制的态度，未对乌鸦们的言论作出回应。\r\n仿佛一切都不曾发生。"
