		"铁质餐盒",
		"100020_xiedaiwu_03",
		"统一配发的制式餐盒，对比正常的型号容量大了一倍。除了统一配发的营养棒外，塞满了各种真空包装的食品",
		"安布蕾拉总是处于饥饿状态。\r\n\r\n这或许与她常年停不下来的多动有关，也或许与她体内的“T因子”有关。\r\n又或许，她只是单纯的好胃口。\r\n这一点往往在她出任务的时候会表现得更加明显。每次作战过后，安布蕾拉总是需要大量的进食，按标准配备的营养剂根本无法补足她的需求。大多数时候，连队友的食物都要让她吃掉不少。\r\n好在守秘人的要求本就千奇百怪，天文台内部针对不同的队员需求有灵活的标准，这样的事情发生几次后，安布蕾拉携带食物用的餐盒就被换成了比正常容量大一倍的型号。\r\n“薯片可乐大鸡腿，烤翅玉米奶酪棒。哈哈，这下可以尽情装零食啦！”\r\n拿到餐盒的第一天，安布蕾拉就在里面塞满了自己爱吃的零食。\r\n于是也理所当然地被训斥了：“安布蕾拉！餐盒是用来装干粮和营养剂的！不是用来塞填补饱肚子的零食的！下次再因为没有吃饱而饿肚子我可不会管你！”\r\n语气严厉，眼神决绝。\r\n只是，话是这么说，每次吃完食物的安布蕾拉垮下脸来眼泪汪汪地喊饿的时候，也没人能狠心不让少女吃饭。\r\n“下次记得带营养剂……我这里也不是能无度取用的，每次去取物资都要被人询问最近是不是吃胖了。”\r\n“嗯嗯，明白啦明白啦～呼，这个口味的营养剂还不错。”\r\n“好好听我说话啦！”"
	},
	{
		2000020,
		202,
		1,
		"抑制拳套",
		"100020_xiedaiwu_02",
		"大小上极具冲击力的金属拳套，是安布蕾拉使用最顺手的武器，由天文台定制配发。偶尔会让安布蕾拉有种奇怪的束缚感。\r\n——当然，一般都会被当做是错觉",
		"“是武器，也是抑制装置。你说抑制什么？大概是T因子吧。”\r\n安布蕾拉向好奇她的大拳套的人解释的时候，通常都会这么说。\r\n\r\n从她加入天文台起，那只巨大的拳套就一直戴在她的右手上，时至今日，几乎已经成了安布蕾拉的标志之一。\r\n“要我说，那些老书呆子们所谓的抑制也没起到什么作用嘛，该暴走的时候我可是一次也没少过。”安布蕾拉会不屑一顾地这么说。\r\n的确，在罪天使小队任职期间，安布蕾拉曾多次精神失控并造成巨量破坏，其损失之严重让管理小队财务的暮雪痛心不已。\r\n只是拳套也并非是完全牢固的，在某次相当艰难的作战当中，安布蕾拉的拳套就差点完全破碎，当时目击了这一幕的队员坚持说，他在安布蕾拉的身上看到了黑色的火焰。\r\n但是他的话没有人相信，就连安布蕾拉本人都不承认，认为他被污染到出现了幻觉。\r\n“T因子增强的是肉体力量，我可不记得我什么时候把自己的血肉当柴油烧了。”\r\n本人是这么说的。\r\n倒是芬里尔在注意到这一异常后，申请从泛星海实验室调取了安布蕾拉的治疗记录。\r\n没有人知道芬里尔都看了些什么。\r\n只是在那之后，安布蕾拉被下了严格的命令，除了必要的沐浴休息，就连吃饭也不许将拳套取下来。\r\n认为自己失去了自由吃零食权利的安布蕾拉抗议三天，无果。"
	},
	{
		2000020,
		203,
		1,
		"玻璃“糖罐”",
		"100020_xiedaiwu_04",
		"特制玻璃密封的“糖罐”，里面储存着安布蕾拉的“糖果”，只要吃上一颗就能让她迅速安静下来",
		"对于罪天使小队来说，有一项非主要也非必要的开支总是会在记账本上出现。\r\n\r\n▉▉月▉▉日，小队成员安布蕾拉于市区便利店内与社会闲散人士发生争执，在后续的暴走中共砸碎收银机一座，货架若干，共计造成损失190389量子贝，目前已赔付。\r\n▉▉月▉▉日，小队成员安布蕾拉在执行任务时被击昏，后因精神失去管束暴走。破坏深空矿业工程用直升机一架，采矿车一辆，合计需赔偿739734量子贝，目前已赔付。\r\n▉▉月▉▉日，小队成员安布蕾拉精神失控暴走，于格林特街区造成大面积破坏，经协商需赔偿费用合计1034986量子贝，因个人资金不足，目前由特遣队代为垫付，后续由安布蕾拉用工资偿还。\r\n……\r\n\r\n管理小队财务的暮雪时常忧心忡忡地表达自己的担忧，认为再这样下去，安布蕾拉就算把自己卖了也还不起那高额的赔偿费用。每次申报过后，她总会将人拎进会议室，进行至少一个钟头的教育。\r\n“安布蕾拉，你不能这么下去了，你要对自己的精神状态心里有数。”\r\n“哦……”\r\n“频繁地释放自己并不是什么好事，你要清楚这件事。下次任务别再甩开别人单独行动了……至少要跟随一名队员，记住了吗？”\r\n“哦……”\r\n“这次事件中你的精神状态明显不稳定许多，你有按照规定服用‘糖果’吗？”\r\n“哦……啊？糖、糖果，我当然有吃……”\r\n“安布蕾拉，我说的是【按照规定服用】。”\r\n“……”\r\n“……我会提交在下一批‘糖果’中添加不影响药效的苦味素的申请，这能降低制作成本，而你确实该戒糖。”\r\n“我错了！我错了！我再也不敢当甜点一次性吃完了！暮雪——”"
	},
	{
		2000020,
		204,
		1,
		"金属怀表",
		"100020_xiedaiwu_01",
		"未知金属制成的怀表，外壳上的划痕是岁月留下的痕迹，表面上有用神秘学符号写成的代表“月”的图案",
		"如果不是说出来，谁都不会想到看上大大咧咧的安布蕾拉实际出身于天文台高层。\r\n大人物们的家庭往往伴随着严格的家教，连气场都会有所不同，这一点从安妮薇就能看出来。\r\n但安布蕾拉本人身上却从未流露出那种气势。\r\n对此，安布蕾拉本人的解释是：“哈，这不是理所当然的吗？毕竟不管是我还是妹妹，在家里都因为比不上姐姐长期被忽视呢。”\r\n姐妹关系，这是安布蕾拉谈起家庭时总是会提起的话题。\r\n“我讨厌姐姐。”\r\n偶尔，安布蕾拉会对身边的人这么抱怨。\r\n“家里的关注和关爱也好，对我和妹妹的态度也好，种种方面都让人讨厌。”\r\n万众瞩目的地位、傲慢蔑视的态度、以及从言语到行动的冷暴力。\r\n在安布蕾拉的形容中，她的姐姐正是这样的人。\r\n“只要她出现，爸爸的目光就永远都会放在她的身上，他会仔细关注姐姐的一举一动，却从来不会分给我和妹妹半个眼神。”\r\n每当说到这里，安布蕾拉都会像个小孩子一样顾着脸颊，并为了增强说服力从衣兜里拿出她的怀表。\r\n“你看，就连作为身份象征的怀表也是。”少女将铭刻着花纹的外壳展示给聆听的人看，“象征姐姐的是高高在上的‘太阳’，能散发出光与热量。而我就只能得到暗淡的‘月亮’，永远只能在‘太阳’的背后反射不属于自己的光。”\r\n“这太不公平了！”\r\n于是有人问：“那么，你的‘妹妹’呢？”\r\n“妹妹是‘星星’啊。在夜空中不注意看就会被忽视的星星，在家也被所有人忽视。”安布蕾拉理所当然地说，“所以，只有我能保护她了。”\r\n“可是，安布蕾拉……”\r\n“你没有‘妹妹’呀。”"
	},
	{
		2000021,
		201,
		1,
		"游戏机",
		"100021_xiedaiwu_02",
		"限定版游戏掌机，内存空间即将用完了。大家总是猜不到暮雪会从什么地方掏出游戏机，仿佛这是长在她手上的一部分",
		"女孩出生于冬日，在她发出第一声啼哭的同时，空际飘下了洁白的雪花。满怀幸福的父母决定为乘着雪花降临的女儿取名暮雪，然而他们不曾想到，这份幸福既如雪花般美丽，亦如雪花般脆弱——\r\n暮雪被诊断出了▉▉▉，不久她的母亲也因一场事故丧生。\r\n\r\n女孩逐渐长大，她常常生病，无法自由活动。当别的孩子快活地歌唱时，她虚弱得连提高声音讲话都无法做到；当别的孩子们恣意地嬉戏时，她只能窝在漆成奶油色的小床上，缩进厚厚的毛毯里。\r\n“爸爸，我想去森林，野餐、爬树、捉迷藏……”五岁生日的前一天夜里，她对来看望她的父亲许愿。下午的时候，她听见窗外的孩子在谈论学校的森林春游计划，他们的笑声令她心中涨满渴望。\r\n父亲闻言沉默地点点头，替她掖好被子后便走出了房门。\r\n\r\n翌日清晨，她被一阵清脆的鸟鸣唤醒，等睁开双眼，却并非是熟悉的景象——面前延伸开一片葱茏欲滴的绿意，正是她在电视里见过的森林，也正是时常于她梦中浮现的森林。\r\n“暮雪，生日快乐，这是你的礼物。”是父亲的声音，随即有什么东西被递到了暮雪手里，女孩才发觉自己头上还戴着一个头盔模样的东西。\r\n“过来找我吧——虽说你是第一次玩游戏机，可你是科学家的女儿，肯定有摆弄机器的天赋。”\r\n于是暮雪开始按照眼前浮现的简短说明，按动手中的按键，控制自己前进、后退、左拐、右拐……\r\n起初她走得歪歪扭扭，摇摇晃晃，好几次都被半埋进草丛里的树根绊倒；经过反复尝试，她逐渐能够顺利地走过湿滑的苔藓；再接着，她自由地奔跑起来，蹦跳起来，她敏捷地攀上高高的树梢，拽着藤蔓荡来荡去，她尽情地欣赏沿途的一草一木，还采了一大捧鲜花……最后，暮雪沿着清澈的溪流来到终点，拨开眼前的树丛，她的父亲坐在淡蓝格子的野餐垫上，微笑地望着她。\r\n“我的生日愿望……实现了，谢谢爸爸！”暮雪扑进父亲怀里，把那一捧娇艳的鲜花递到他手上。\r\n暮雪迷上了游戏机，开始探索广袤无垠的虚拟世界，展开属于自己的真实冒险。即使此后在游戏里创造过许多奇迹，但她依然认为，这是她人生中的第一个壮举，彼时的自己非常了不起；即使此后发生了太多太多的……变故，但她永不会遗忘五岁生日的清晨，初次把手指放于按键上，控制自己奔向父亲，为他献上花束时，雀跃而不可思议的心情。"
	},
	{
		2000021,
		202,
		1,
		"大容量存钱罐",
		"100021_xiedaiwu_04",
		"用了很久的存钱罐，一旦把钱放进去就很难再取出来。存钱是暮雪的习惯，但她似乎已经忘记了最初这样做的目的……",
		"暮雪觉得父亲好像变了，虽说他原本便是个沉默寡言的人，现在却愈发如此。他一连数月不回家，即使回到家，也常常连茶都没喝上几口，又匆匆离去，好似一个讨水喝的过客。\r\n暮雪忍不住向照顾她的格林太太问起父亲的事，格林太太安慰说，暮先生升为诺亚的高级研究员，所以工作更忙了，但这样他将能赚到更多的钱，给暮雪买巧克力和游戏机……\r\n老太太一边说，一边掰下一块巧克力送进暮雪嘴里。它显然比先前的贵许多，吃上去香醇顺滑。暮雪心里却很不是滋味，她想念同父亲一起分享的，从门口的小商店买来的便宜巧克力球。\r\n\r\n当天深夜，暮雪被一阵响动吵醒。她平日里睡得很沉，可今天由于想着父亲的事，睡得不算踏实。\r\n“先生，我认为你该多陪陪那孩子，不要成天只顾工作，她最近的状况不太好，虽然有我这个老太太陪她，但我没法子取代父亲的角色……她总在念叨你。”是格林太太的声音。\r\n“我知道，只是……”父亲后面说了什么，暮雪没听清。\r\n“先生，等等——”大门被重重地关上，暮雪知道父亲又离开了。她有点儿冷。\r\n\r\n随着天气变暖，暮雪的身体状况好转了些，格林太太推她去庭院晒太阳。\r\n当老妇人回房给女孩端点心时，一个红头发的脑袋从院墙那头探出来，暮雪晓得他是隔壁的汤米，一个疯疯癫癫，满口脏话，总爱欺负人的混蛋。她打算继续玩昨天的游戏，不理这坏家伙。\r\n汤米却用袖子撸了一把鼻涕，笑嘻嘻地说：“网上说诺亚科学家全是贪财鬼，爱钱胜过爱家人，小心你爸像科幻片里那样，把你当成怪物卖掉做实验！”\r\n“小兔崽子，少胡说八道！”格林太太操着扫帚冲向汤米，男孩吐吐舌头，把脑袋缩了回去。\r\n暮雪听过很多关于自身缺陷的非议，她逐渐学会选择忽视，转而享受在游戏里驰骋畅游的快乐，但汤米的话正中她的心事，令她没法再移开视线，把番话这当成清风过耳。\r\n手中的游戏机是父亲两个月前买给她的，价格有点贵，造型很可爱，按键的手感很顺滑……此时此刻，它却提醒着暮雪，她已经整整两个月没见过父亲了。\r\n\r\n又是一周时间过去，父亲依旧没有归来。暮雪的快乐被心底越胀越大的不安盖过，她当然不相信父亲会把她卖掉的鬼话，她担心的只是父亲会因忙于工作和赚钱而忘记她。\r\n这天，在格林太太讲完睡前故事后，暮雪提出了她的请求：“我想要一个存钱罐，不要太贵的……“\r\n拿到存钱罐的女孩开始了她的计划。每当听到罐里钱币叮当碰撞的声音，她就会感到一丝安心：“格林奶奶，下次见到爸爸，我一定要告诉他，我以后不吃贵巧克力，也会少买新游戏机，我还要把这些钱全部给他，让他每个月在家多待几天！”\r\n存钱罐装满的那天，父亲真的回家了。他从一辆印有诺亚标志的汽车走下来，领走了暮雪。\r\n“是诺亚的车，我就说，我就说……暮雪肯定被她爸卖掉了，卖掉了！”汤米一溜烟跑出院子，跟在车屁股后面，发出一阵阵刺耳的尖叫。"
	},
	{
		2000021,
		203,
		1,
		"暮-NO.0原型机",
		"100021_xiedaiwu_03",
		"暮系列机器人的第一台原型机。尽管现在暮-NO.0已经无法投入使用，它仍然是暮雪最珍贵的伙伴之一",
		"初到诺亚的一段时日里，暮雪没有朋友。\r\n\r\n她先前也没多少朋友，对她而言，与陌生人搭话比三十秒解开数学难题要难上数百倍。过去的她一直待在自己的房间里，即使现在她进入了一个崭新的环境，有了更方便的设备供她外出和活动，那个房间依然存在于在她的心里，每当在陌生人面前支支吾吾，词不达意，因紧张汗湿了背脊时，暮雪就会想缩回那里，最好再裹上一条柔软的毛毯，把自己整个人严严实实地遮蔽起来。\r\n躲在房间的暮雪用诺亚的设备鼓捣起了别的事，她开始展现出机械设计和制造方面的杰出能力。\r\n这时暮雪对父亲的感情已渐趋复杂，但她的确继承了这位科学家“摆弄机器的天赋“，不久后她便造出了属于自己的第一台智能机器人。以现在的眼光审视，它大概过于简陋，可这意味着暮雪智能机械事业的开端。女孩将其命名为暮-NO.0，并为此感到欣喜。\r\n到了父亲工作的地方，暮雪本以为自己能每天见到他，然而情况仍和过去一样，埋头工作的父亲很少来看她……倘使暮-NO.0能投入生产且受到欢迎，赚很多钱回来，是否能够让父亲心中的天平稍微向她倾斜一些呢？想到马上就是自己的生日，她决定把机会留给这有意义的日子。\r\n生日前一天，暮雪打通了父亲的视频电话。见到女儿的机器人在镜头前蹦蹦跳跳，父亲的表情微微松动了，只有短短数秒，随即他无视她的央求，挂断了电话……最后的时刻，暮雪的耳朵似乎捕捉到一声轻叹般的“抱歉”，或许并不是说给她听的，而是父亲在自言自语。\r\n\r\n暮雪的九岁生日是暮-NO.0陪伴她度过的，它给暮雪烘焙了一个大蛋糕，上面涂满了巧克力酱。\r\n彼时暮雪的技术尚不成熟。由于数据上的一个小误差，NO.0表现得异常活跃，完全是制造者的反面。它不愿长时间待在房间里，经常在暮雪打游戏时偷偷溜出去玩耍，害得女孩得驾着轮椅出门四处寻找；它还喜欢在庭院里跳舞唱歌，憨态可掬的模样引得人群纷纷围观，女孩不得不被这些陌生人搭话，还要忍受着他们的注目，才能在NO.0表演尽兴后把它领走。\r\n不过在鉴定NO.0不会产生什么危害后，暮雪放弃了为其调整数据的念头。而它之后的一系列机器人，都被女孩赋予了随机且各异的性格：有的是话痨，讲起话来好似机关枪，叫人压根儿接不上话；有的则富于幻想，一丁点苗头就会被它编织出无穷无尽的故事……这些机器人像它们的始祖NO.0那样在暮雪的生活里闹腾着，发挥着普通机器人功能的同时，也给她带来了不少麻烦。\r\n\r\n“我不太明白，暮雪为什么要这么做呢？”阿妮亚刚跟暮雪相熟那会儿，曾这样问过。\r\n“唔……大概是因为，我把它们都当成了朋友吧~”暮雪从床头抱起NO.0的机体轻轻抚摸，现今它已无法投入使用，但外壳光洁，不染一丝灰尘，正如多年前女孩将它组装完成时的模样。"
	},
	{
		2000021,
		204,
		1,
		"复健用护膝",
		"100021_xiedaiwu_01",
		"由复合金属材料制成的护膝，轻便但结实。曾经是支撑暮雪行动的必备品，但如今她不再是那个需要护膝保护的小女孩了",
		"“你好，暮雪小姐，今天我们继续尝试活动身体。”\r\n“我知道这不太舒服……再坚持一下吧，一下就好，它对你的未来与你父亲的研究都很有意义！”\r\n“你付出的努力并没有白费哦，动作比昨天轻快了许多……你自身感觉不到，但我看得一清二楚，总有一天你将在太阳底下尽情奔跑！”\r\n“谢、谢谢你陪我复健……”额头淌下的汗水沾湿了暮雪的视线，朦胧中瞧见对方在对自己微笑，她只得无视眼睛的涩痛，挤出个忸怩的笑容作为回应。\r\n父亲究竟换了几个助手测试新品性能……五个，还是六个？有男有女，相貌各异，神情和话语却仿佛是同一副模具压成的，她实在不知该如何应对这些人。\r\n其实暮雪早就能脱离护膝健步如飞了，就在他们瞧不见的地方。她只是有点好奇，若发觉她的复健计划进行得并不顺利，自打一年前便没再露过面的父亲，会不会抽两分钟见见她。\r\n“……他不会来吧，退一万步说，就算见面又怎么样呢？”暮雪想起上次见面时父亲似石像般僵硬的面容，忽然觉得她的这种行为幼稚且没有意义。\r\n\r\n数年前暮雪开始了在诺亚的治疗，在此期间她听到了许多关于父亲的传言，它们逐渐拼凑出一个让暮雪无比陌生的形象：在诺亚，父亲被称作▉▉，是一个冷酷贪婪，为金钱甘愿出卖一切的恶棍；人们笃定地认为，这个男人把女儿暮雪当成了研究的道具，治疗她仅仅是研究的副产品。\r\n最终父亲亲口给这些传言盖上了章，他承认的确是为了名利才做了这一切……只是他话语的末尾却偏偏带着一丝轻叹，和那年生日他挂断电话前发出的别无二致。\r\n倘使暮雪还是五岁的孩童，她绝对会认定他在说谎，那时她认为爸爸是天底下最好的爸爸；但如今她只能透过玻璃，远远望向父亲工作的研究大楼。那是一栋外壁刷成灰白的建筑，周边没有任何绿色植被，尖锐的屋顶直直刺向辽阔的天穹，让人不安惶恐。\r\n正如多年来父亲刻意的隐瞒和拒绝带给暮雪的感受，她不明白父亲到底在想什么，她甚至不明白自己在想什么，她深恨自己在这方面的驽钝，她可以灵活地拆解组装机器，弄清故障的来源，哪怕它位于最细微之处，却没办法拆解人心，看看她跟父亲之间到底出了哪些问题。\r\n和暮雪料想的那样，父亲最终没有现身，或许是因为关于她的这项研究已经完成，不再需要记录数据了。\r\n\r\n过了数月，暮雪被诺亚调换至天文台工作，据说其中涉及了某些利益交易。当她坐上去往天文台的汽车时，好像瞥见父亲正站在研究室的窗后，深深地凝视着她……也许那仅是一道幻影。\r\n又不知过去多久，暮雪收到父亲失踪的消息，他参加的研究计划失败并引发骚乱，这成为了当年业内最大的新闻。没人知道暮雪对此事作何感想，那似乎是平静的一天，她和天文台的朋友一道通关了《森林大冒险Remake》的双人模式——不过这次她抛弃了往常那澎湃汹涌的胜负欲，放慢脚步，采了满满一大捧鲜花，放在终点的指示牌下。"
	},
	{
		2000022,
		201,
		1,
		"磨损的铭牌",
		"100022_xiedaiwu_01",
		"一枚真理兄弟会成员的铭牌，铭牌表面磨损严重，映证着铭牌主人曾经的功绩。不过名字似乎被人刻意划掉",
		"暴雪过后，阳光比想象中更加耀眼。\r\n“不要直视午后的积雪，会得雪盲症的。”挎着黑色钢枪的大胡子男人将少女带回营帐，拭去落在她头发上的雪花。\r\n“谢谢你，灰熊大叔。”少女露出久违的笑容，“到西边以来，你是第二个对我好的人。”\r\n在灰熊将她带出地下实验室之前，她的世界只有幽暗的隔间。\r\n她只记得自己来自遥远的东方，路途的辗转抹去了她大部分人生记忆，包括名字。\r\n“177”——她在实验室的代号。\r\n\r\n这里是永冬区——尤克特拉希尔的无名荒原。明面上的战争虽然已结束多年，但属于大人们的暗流仍在涌动。\r\n作为一颗微尘，她不可能掌握自己的命运。\r\n监视、体检和孤独是生活的一部分。\r\n如果不是灰熊大叔他们将她从实验室救出来，这样的生活也许将持续到生命终点。\r\n“第二个？那第一个是谁？”少女的话引起灰熊的好奇心。\r\n“我不知道她的名字。她是那里的人，有一头漂亮的金发。”\r\n虽然金发姐姐从来没给过她好脸色，可在那地方，只有她将自己当“人”来看待。\r\n但现在，少女已不再关注这些。\r\n\r\n在灰熊大叔和同僚们的护送下，她正离开尤克特拉希尔，前往希利尔去。\r\n她会在全新的环境开始新生活。\r\n——她的确是这样想的。"
	},
	{
		2000022,
		202,
		1,
		"PHIRIZLE行李箱",
		"100022_xiedaiwu_02",
		"流行于伊利亚特半岛的PHIRIZLE经典款行李箱，该品牌出品的箱包以坚实耐用、款式流行著称",
		"少女之前对希利尔全无印象。\r\n往希利尔行进的路上，灰熊时常会讲述那地方的故事。\r\n从旧时代开始，希利尔不断受到外部的压迫和入侵。\r\n此中又以星空隐修会最为恐怖。\r\n他们驱动将人变成非人的邪恶力量，试图令希利尔屈服。\r\n但那里的人民并没有放弃对自由和真理的向往。\r\n他们联合起来，互相称谓兄弟，以恶劣的地理环境和坚韧的精神，无数次抗击星空隐修会的推进。\r\n最终，他们取得胜利。\r\n邪恶的力量并未能染指这片土地。\r\n\r\n现在的希利尔，依然是自由与真理的乐土。\r\n“自由，多美的词汇啊。”\r\n\r\n少女的心在悸动。她比任何时候都懂得自由的价值。\r\n\r\n在充满期待的新一日醒来之后，她如往日一般整理着营帐的内务，准备继续行程。\r\n\r\n这时，她发现了一个陌生的黑色行李箱。\r\n\r\n行李箱上精美繁复的花纹让她无由联想起不好的回忆。\r\n\r\n她巍巍颤颤打开。\r\n\r\n里面是——一条冻僵的鲤鱼。"
	},
	{
		2000022,
		203,
		1,
		"安瓿",
		"100022_xiedaiwu_03",
		"残留黑色流体的硬质玻璃容器，标签有涂抹痕迹，瓶颈处缠绕着封条，是已经使用过的遗弃物",
		"尖锐的哨子声从周围响起。\r\n少女冲出营帐，只见怪异的黑色影子如同墙壁般立起，将临时搭建的营帐包围起来。\r\n灰熊大叔依托着半截断岩正朝着哨子声的方向射击，而他的同僚们已经倒下了。\r\n他们一动不动，身体上蔓延着如影子般的黑色流质。\r\n邪恶力量——少女突然想起故事中那将人变成非人的东西。\r\n但她来不及细想，一个熟悉的清冷声音将她带回现实。\r\n“白银黎明并不宽容。你们袭击据点的时候，大概应该知道自己的下场吧。”\r\n几个身着黑色制服的人出现在影墙前，为首的是一名金发女性，她的手中的安瓿瓶灌封着与影墙相同质地的黑色流体。\r\n金色的盘发在阳光下十分耀眼。\r\n少女认识这个女性，是她——实验室里唯一对自己好的“金发姐姐”。\r\n“177，你还活着。”金发女性也看见她，但很快就将注意力放回唯一存活的敌人——灰熊，她举起安瓿瓶。\r\n就在这时，少女感觉手腕一阵剧痛，身体毫无抵抗被拉扯住。\r\n少女茫然望向灰熊。未曾想到，灰熊大叔竟会露出如此狰狞的表情。\r\n她被灰熊挡在身前，黝黑的枪口抵住太阳穴。\r\n“别怪我，为了活命，哪顾得上这么多。”\r\n金发女性冷眼看着这出滑稽剧，开口说：\r\n“我不知道你对恶名昭彰的‘白鲸’抱有什么期待，但可以肯定，即使在希利尔，你也不会是他们解放的对象。”\r\n她折断安瓿瓶的封装，黑色流体直射而出。同一时间，灰熊将少女推向黑色流体。\r\n撕心的痛楚在少女的身上和心中蔓延，黑色流体正在摧毁她的一切。\r\n眼睛无法看清，黑色的影子已占据原本眼睛的位置，她能感受到身体逐渐被黑色流体同化。而更大的伤痕来自心里，意识的某处，碎裂了。一切的温存都是浮影，理智在此刻变得不再存在。她不再抗拒，反而在无意识中加速同化——她变成影子。\r\n“启迪？不，这是——”\r\n最初察觉异常的是金发女性，与黑影同化的实验体177并没有想象中的沉寂，反而泛起更诡异的红雾。\r\n她试图离开这失控的现场，却发现身后的影墙正向她逼近。\r\n连惊呼都来不及，影墙掠过她的身体，与少女融合。\r\n金发女性则消失无踪，仿佛不曾存在过。"
	},
	{
