		204,
		1,
		"幽灵的照片",
		"100022_xiedaiwu_04",
		"这是一张数年前流行于尤克特拉希尔的怪奇相片，曾在网络上引发热议",
		"“少女”恢复意识时，夕阳已西斜。\r\n灰熊和金发女性，黑衣人和白鲸，所有人都已不见踪影。\r\n没所谓。\r\n“已经没有什么可期待了。”它如是想。\r\n\r\n拖着模糊的身影，消失在远处。\r\n传闻——一个幽灵在尤克特拉希尔各大城市中游荡。\r\n它惧怕影子，惧怕人群。\r\n它注视着所有来自希利尔地区的旅人和车辆，但一旦被他们发现，却又歇斯底里地逃离。\r\n它从未攻击过人类，也未曾有任何索求。\r\n有人这样描述它：\r\n它曾经对某些事物有所期望，但期望最终破灭了。\r\n它变得敏感而茫然，被困在自己的牢笼里。\r\n就像是笼中的鸟，虽然翅膀犹在，但无法翱翔天际。\r\n除非——有另一个同样遭遇的人，为它打开牢笼。\r\n但这样的人，真的会有吗？"
	},
	{
		2000025,
		201,
		1,
		"护身符",
		"100025_xiedaiwu_01",
		"小时候为了“驱邪”，家人帮忙收集的各种护身符，什么样的款式都有",
		"曾经，磷火是一个很瘦弱的孩子。\r\n可能你觉得和他现在的样子很不匹配，但这是事实，甚至到了如果你翻开他小学时候的同学录，你绝对不会认得他的程度。\r\n因为“体质”原因，他的童年是在各种伤病中度过的。\r\n感冒发烧这种小病已经是家常便饭，光是让他半只脚迈过三途川的病，起码就有三次。\r\n家里人认为一定是邪魔作祟，因此从各个地方为他求来各种护身符，什么款式都有。\r\n小时候的他活脱脱一个护身符百科全书。\r\n误打误撞的，他们找对了原因，可惜他们找错了解决方法。\r\n这些半桶水的护身符并没有解决磷火的问题，万幸的是也没有产生什么副作用。\r\n即便到现在，磷火依然将这些护身符保存的整整齐齐的，对于他来说，这些护身符不仅是他过往的见证，同时也是家人担心他，为了他好不容易收集回来的宝物。"
	},
	{
		2000025,
		202,
		1,
		"哑铃",
		"100025_xiedaiwu_02",
		"锻炼常会用到的哑铃，可以在两边加码的款式，现在也已经渐渐变成了不适合初学者的重量了",
		"年纪稍微大了一点之后，磷火的情况比之前好了不少。\r\n从理论上来说应该是“容器”变得更大了，自然情况也就好转了，但对比同龄人来说他还是很瘦小。\r\n虽然不至于被同龄人欺负，但是作为男生多多少少还是有些负面情绪的，于是他决定锻炼自己。\r\n他人生第一次，向双亲索要的礼物，就是一双哑铃，而且是能在两边加码的款式。\r\n这或许是一个改变了他人生的礼物。\r\n随着哑铃两边不断的加码，身体变得强壮的同时，以前那些病痛或者偶尔能的幻听幻视也离他远去。\r\n不论是他还是家人都认为这是强身健体带来的好处，直到天文台的人来访他才知道，其实“它们”并未远去，只是健全的身体已经可以不知不觉中适应这些不可视的存在了。\r\n现在天文台的健身设施可谓是一应俱全，但是他一样留着这双哑铃，虽然已经不再是刚刚提起它们的重量，但是依然有过了这么久仍旧没变的东西。"
	},
	{
