		"《十万个笑话》",
		"100025_xiedaiwu_03",
		"努力过希望能开朗点，但是不论看了多少个笑话段子，他都理解不了到底有什么好笑的",
		"磷火是一个不怎么会说话的人。\r\n\r\n不是说他不喜欢说话，单纯就是嘴笨，童年的经历让他并没有交到很多朋友。\r\n而且强壮的体格，多多少少削弱了大家向他搭话的勇气。\r\n结果就是，恶性循环。\r\n虽然他是属于在战场中身先士卒，只让大家看到他的背影的男人，但是大家越是佩服他，气氛就变得越怪。\r\n双方都是，其实很想交流，但是却因为错过了最佳的搭话时点变得尴尬了起来。\r\n为此，磷火想出来的办法是：买了一本“十万个笑话”。\r\n在看完整本书后（其实并没有十万个那么多），他终于开始第一次，向自己的队友搭话。\r\n以说笑话的形式。\r\n毫无疑问的是，他的队友几乎没有什么抵抗的笑了出来，不是因为笑话本身很好笑，而是因为他面无表情一脸正经的说笑话的样子太好笑了。\r\n只留下磷火本人一脸疑惑“刚刚我讲的笑话有这么好笑吗为什么我理解不了算了反正只要结果好一切就好。”\r\n不过不管怎么说，总算是踏出了和队友私底下交流的第一步。"
	},
	{
		2000025,
		204,
		1,
		"定制手枪",
		"100025_xiedaiwu_04",
		"只有一颗子弹的手枪，只为了留给自己的手枪",
		"从能力上来看，磷火的超凡能力非常弱。\r\n\r\n他只能隐约的看到死者的残留意志，既不能与类似死灵的生物进行沟通，也不能操控超凡生物。\r\n但从作战报告上看，他的小队已经不止一次的依靠他度过难关，情况也很简单，当磷火接近死亡的时候，他的生机越弱，身体就会越成为吸引周围的“死者”的容器，这些“死者”会强行激发他的身体潜能让他继续坚持战斗。\r\n不论什么时候，只要你能看到他的背影，你就会觉得特别的安心。\r\n从拿到那双哑铃开始到现在，他从来没有懈怠过自己的锻炼，为的就是成为更大的“容器”，他相信健全的肉体和健全的精神是统一的，只有这样才能保证自己在关键时刻不会失去意识。\r\n作为拿着盾和锤冲锋在战场第一线的他，身上只有唯一一把手枪，那是一把只有一颗留给自己的子弹的手枪，虽然他也祈祷这把手枪永远不会有需要用到的一天，但如果那一天真的到来，他会很乐意将自己变成引爆体内所有“死者”的炸药桶。"
	},
	{
		2000028,
		201,
		1,
		"狩魔枪",
		"100028_xiedaiwu_01",
		"外形是马格南双枪，伊甸之树配发的特制强力驱魔器，枪口下丧命的血族不计其数，是创失去吸血鬼的能力后代替其功能的“獠牙”",
		"身为归化伊甸之树的血族，创理所当然地受到了很多管制。\r\n行动上的管制仅仅是一部分，最主要的一点是，不允许吸食人血，连血库的冷冻血浆也不行。\r\n而作为替代品，伊甸之树向组织内的吸血鬼们提供了各种动物身上提取的动物血，以及用科技合成的人造血。\r\n不同的血口味不同，创对此深有研究，但即使是再不同的口味，对于吸血鬼来说永远没有人血来得有营养。\r\n就像人类可以靠吃素维生，却无法靠纯素维持身体所需营养一样。\r\n长期服用动物血与人造血所导致的后果就是，创与生俱来的血族能力和兽性都被迫大幅度退化。仅保留了属于血族的身体优势，以及人类所不具备的敏锐嗅觉和视觉。\r\n针对这一情况，伊甸之树为创配发了特制的狩魔枪，以自身血液作为子弹的狩魔枪威力巨大，甚至足够创抹平能力退化所带来的差距。\r\n\r\n在第一次任务中，创单枪匹马潜入▊▊家族宴会现场，仅凭借两把狩魔枪与配补的一柄驱魔剑，全歼宴会上所有的任务目标。\r\n由于本人干练精简的报告风格，伊甸之树内部并未储存详细的任务记录，后来者仅能通过后勤部的任务报告窥得当日的一鳞半爪。\r\n用作宴会的古堡垮塌一半，经调查原因为西南方向承重柱与承重墙的大面积损毁。剩下的一半则与废墟没有两样，砂砾与鲜血几乎铺满了整块地毯……\r\n那之后，没过多久，从一众普通血族成员中脱颖而出的创就被赋予了“高塔”的席位。"
	},
	{
		2000028,
		202,
		1,
		"提神精油",
		"100028_xiedaiwu_02",
		"看上去平平无奇的精油，拥有只用几滴就让人清醒起来的强大功效",
		"奉命追寻、猎杀同族的血族，隐于暗处的血脉背叛者，这样的创被忌惮他的血族们冠以“弑亲者”的雅号。\r\n但是，高强度猎杀同族并非毫无影响。\r\n来自血脉深处的疲惫感一直消磨着坚韧的意志，持续接触同族的血液勾起已经埋藏在身体深处的兽性。这些都令创的精神状态并不算好。\r\n离开了需要高度集中精力的战场，更多时候伴随着创的，是精神上的枯竭与偶尔出现的头部阵痛。\r\n这也令伊甸之树特制的提神精油成为了创的日常必需品，采购清单上仅次于普通马格南子弹的存在。\r\n\r\n每次踏入猎场前，创总是会先使用提神精油将自己调整至最佳状态，令自己的注意力完全专注到战场。等到一切尘埃落定后，创会找个地方好好地睡上一觉，以缓解发自身体深处的过量疲惫。\r\n不过，创也并非只在上战场之前使用它。\r\n鲜少有人知道一向独来独往的创在工作之余的私人生活状况，但只要生活在同一片区域，偶遇总是不可避免的。\r\n据无责任小道消息称，曾有人在夜晚的超市卖场外见过孤身一人的创。年轻的血族用大拇指以非常干脆利落的手法将精油抹到太阳穴上，而后带着一往无前的气势冲进了半价卖场。\r\n口口相传的无责任小道消息，到了最后也有了几分奇幻的色彩。\r\n“意思是参与半价卖场抢购的顾客堪比猎杀吸血鬼？”\r\n“……大概比猎杀吸血鬼还要可怕一些吧。”"
	},
	{
		2000028,
		203,
		1,
		"《夜莺挽歌》",
		"100028_xiedaiwu_03",
		"曾经流行过的犯罪小说，看得出被保养得很好，但略微磨损的边页仍然暴露了其被翻阅不短时间的事实",
		"阅读是创在执行任务之余为数不多的爱好，尤其是那些诡谲怪诞的犯罪小说。\r\n早在还未加入伊甸之树前，尚且青涩的创就会花上一个小时仔细隐藏自己的气息，趁着一个天气尚好的夜晚跑到人类众多的城市内，从书店中淘取自己中意的犯罪小说。\r\n那之后，就着重新加热的冷冻血浆，创就能在自家的窗前度过一个安静阅读的夜晚。\r\n有时，创也会思考，自己那超越寻常血族的隐匿技巧是否就是那时锻炼出来的。\r\n当然，这些念头在如今也不过是无从考证的陈年旧事罢了。\r\n毕竟不论是书还是回忆，都已经随着那一次意外毁灭殆尽。\r\n唯一残存下来的，只有最后一次外出带回来的最后一本小说。\r\n名为《夜莺挽歌》的书被创放在书架最显眼的位置，并不是为了阅读，仅仅是为了提醒他不要忘记那段过去。\r\n对于现在的创来说，阅读犯罪小说早已从爱好变为了一个习惯。洗去属于同族的血浆后，一个阅读小说的闲暇总是能让他同类相残导致的狂暴心境慢慢平静下来。\r\n年轻的血族总是喜欢在书的最初推演剧情的走向，又在看到与自己的推演完全不同的剧情时，为作者的奇思妙想惊叹不已。\r\n“唔，凶手做下这次的事件的时候已经不加掩饰了，主角大概会在这次事件后发现真相吧。”\r\n“……凶手为了阻碍主角的调查和主角在一起了？哦……”"
	},
	{
		2000028,
		204,
		1,
		"半损家徽",
		"100028_xiedaiwu_04",
		"金属制成的徽章，其中一半已经被损坏，剩下的一半被溅上了黑色的污渍，如同在无言诉说着某段黑暗的往事",
		"偶尔，创会在能够静心思考的深夜想起一些埋葬在过去的往事。\r\n就算哪天突然消失也不奇怪的小家族，仅仅位列血族协会的末尾，却是创的出身之所。\r\n由于自身势力薄弱，他们甚至不曾拥有适用狩猎的土地，仅能从他人的渠道中高价购买维生用的血浆。\r\n但即使是这样弱小的家族，他们也会在每个新月到来时为花瓶里换上新鲜的月光蔷薇，会在每个满月时献上黑夜的赞歌。\r\n这就是家族平静的生活。\r\n也正是因为这样消失都不会有人在意的弱小，当卷入来自高层的阴谋时，他们甚至不曾有反抗的机会。\r\n仅仅一晚，昔日的庄园被焚毁，驱魔的徽记刻印于曾经熟悉的土地，而隐藏在背后的，是将家族推出去作为替罪羊的血族高层的傲慢冷笑。\r\n晚归的创仅从余烬中翻找出被毁坏到只剩一半的家族徽记，以及一些因为及时躲藏而幸免于难的分支成员。\r\n没有人知道在那灾难般的一晚中，孤身一人的创都想了些什么。\r\n只知道在那一晚过后，创带着仅存的族人们，归化了被血族内部视为“叛逆聚集所”的伊甸之树。\r\n半年后，严重违反隐秘守则的▊▊家族于宴会当晚遭遇神秘血族男子的袭击，与会的全部族人无一幸免。\r\n半损的家徽被压入箱底的黑暗，抛弃曾经的家族之名，抛弃曾经连接血脉的荣耀，现在的创仅为伊甸之树的“高塔”。"
	},
	{
		2000029,
		201,
		1,
		"吊坠",
		"100029_xiedaiwu_01",
		"妹妹格蕾特的灵魂栖息在吊坠里，韩赛尔一直在世界各地追寻超凡事件的踪迹，吸取各种以太能量来稳定格蕾特的灵魂",
		"天才格蕾特，拥有强大超凡能力的明日之星；废物韩赛尔，不起眼的弱小人物，惨不忍睹的实战课成绩，更让她成为了学院里的吊车尾。\r\n孩子们很纯粹，所以他们的恶意也通常没有来由，天才与废物的对比犹如云泥，可她们彼此又是最亲密的血亲。韩赛尔今天也收到了小纸条，孩童的字迹稚嫩，恶意却淋漓尽致地传达给了她。\r\n“韩赛尔，你不用管他们。”每当这时，格蕾特都会握住她的手：“你可以和我，还有斯威特共享自己，你让我们成为一体，是很棒的能力。”\r\n“……真的吗？”\r\n“当然是真的，不信你试试看。”\r\n韩赛尔迟疑地开启能力，妹妹与她的感官共享，真挚柔软的情绪随之传来，平息了她胸中翻涌的沮丧。\r\n格蕾特是一个温暖的人。\r\n那天学员们一起执行任务，格蕾特一如既往表现很好，几个教员为了表示鼓励，从魔女夜宴零碎的拍品中选了一条项链，作为奖励送给了格蕾特。\r\n项链可以吸收空间中的以太能量储存在结晶内，持有者可以随时调用来补充能量，不过也有副作用。\r\n“失去意识的时候灵魂会被吸入结晶，需要一定的时间才能回到自己的身体……？”韩赛尔和妹妹躲在被子里，借用台灯的光看着项链的使用说明，皱着眉头嘀咕：“这也太危险了。你一定要带在身上吗？”\r\n“当然，这是我得到的第一个原体。”格蕾特眼睛明亮，带着孩子气的兴奋：“这么点副作用没关系啦，而且我睡着的时候，韩赛尔会一直在我身边吧？”\r\n我会一直在你身边。韩赛尔心想。\r\n\r\n回忆起那年的时光，她眼中晕着温暖的湿气。她端着枪械，匍匐在地上，盯着狙击镜中的景象。\r\n心中被珍贵的回忆填满，可扣动扳机的手，却没有丝毫的犹豫。\r\n对面大厦里，正在饮酒作乐的任务目标应声倒地，韩赛尔在狙击镜里看到华丽的房间里，人们遭遇突变各色的脸，缓缓地收回了枪支。\r\n远处一道蓝色的光弧划过夜空，随后，一只蓝色的小鸟落在她的肩头。\r\n“斯威特先生，这次也辛苦你了。”韩赛尔帮小鸟整理了脖子上的领结：“任务完成了，我们回家吧。”"
	},
	{
		2000029,
		202,
		1,
		"手工领结",
		"100029_xiedaiwu_02",
		"斯威特先生的领结，韩赛尔手工制作，事实上她曾经说过想要做各种颜色各种花样的，但被成熟优雅的绅士斯威特严词拒绝",
		"格蕾特沉默看着姐姐带来的小动物，一只没有竞争过兄弟姐妹、从鸟窝中被挤出来的孱弱小鸟。羽毛都没有长齐，双眼浑浊无光，似乎马上就会死去。\r\n雏鸟的存活率其实很低，尤其她们都没有照顾动物的经验，格蕾特想要劝姐姐放弃，选择一只更强的动物成为伙伴不是更好吗？\r\n雏鸟却因为掌心的温度紧紧依靠着韩赛尔的手，虚弱又亲昵地叫了几声。\r\n韩赛尔第一次对人露出了倔强的神情，她将小鸟捧在心口，动作轻柔又坚定：“我要养它。”\r\n“可是……”\r\n“没有可是，我一定要养它。”\r\n姐妹二人第一次饲养小动物，很用心地为他准备了吃的东西，查了很多鸟类饲养文献，为小鸟取名为斯威特。\r\n照顾动物并不轻松，幸运的是，雏鸟的生命力很强，羽毛逐渐丰满，翅膀逐渐强健，眼睛变得明亮，它很信任韩赛尔和格蕾特，每当她们回到房间，就会从在笼子里亲昵地呼唤她们。\r\n格蕾特很可靠，在学院中深受老师和同学的信赖，但是什么都做不好的韩赛尔，还是第一次被某个小生命依靠。\r\n她的付出得到了汇报，蓝色小鸟亲近她信赖她，对她毫不设防。\r\n在格蕾特的鼓励下，韩赛尔第一次对除妹妹之外的第二个生物，使用自己的能力。\r\n姐妹两个人从此多了一个心意相通的家人。\r\n\r\n韩赛尔的实战成绩还是惨不忍睹，不过她经常利用能力，和斯威特一起辅助格蕾特，那段时间至少没有再吊车尾，赢得了可喜的进步。\r\n“斯威特先生，这次也辛苦你了。”韩赛尔抬手接住飞来的小鸟：“你真厉害，我会给你做新的领结。”\r\n“先生？”格蕾特疑惑地扯了一下鸟脖子上的领结，立刻遭到了小鸟愤怒的反击。\r\n“是他自己要求的。”韩赛尔连忙护住小鸟：“不要这样，他是一个自尊心很重的绅士。”\r\n格蕾特本来以为这是姐姐自己强加设定的小游戏，却没想到韩赛尔话音刚落，小鸟立刻在姐姐肩膀上立正站好，优雅地甩了几下尾羽，用力挺起了胸膛。\r\n这样类人的举动，无疑展现出小鸟超越同类的知性。\r\n格蕾特惊讶地看着，非常确定当时她们捡到斯威特的时候，它还是一只平平无奇的小鸟。\r\n难道是姐姐使用了能力……提高使用对象的智能，这个能力真的只是共享感觉这么简单吗……\r\n“斯威特先生……！”\r\n韩赛尔的惊呼打断了格蕾特的思绪。\r\n只见少女捂住嘴，一脸痛苦地对着小鸟大喊：“请不要在我使用能力的时候吃虫子！”\r\n“……算了。”格蕾特挠挠头：“应该也不是什么大不了的事情……”"
	},
	{
		2000029,
		203,
		1,
		"赠品方糖",
		"100029_xiedaiwu_03",
		"经常光临的咖啡店里会附赠的免费方糖，店家自制的焦糖风味，非卖品，但会作为小礼物送给常客",
		"第一次光临这家咖啡店的时候，店主看到她立刻露出笑容：“好久不见。”\r\n双方都愣在了原地，还是店主先反应过来，饱含歉意地说：“实在不好意思，这位小姐，您长得跟一位熟客太像了。”\r\n在交谈中，韩赛尔才知道，格蕾特经常光顾这家店，每次外派任务结束后给韩赛尔带回来的栗子蛋糕，就是从这家店买的。\r\n店主是个健谈的老妇人，做咖啡的手艺很好。\r\n这次珍贵的巧遇，让韩赛尔知道了很多未曾见过的格蕾特，比如她其实并不擅长喝咖啡，每次都会加很多方糖，比如她更喜欢这家的甜品，所以每次都会给姐姐外带。\r\n韩赛尔喝完了一杯咖啡：“很好喝，我下次还会再来。”\r\n店主却露出了落寞的神情。\r\n“可能没有机会接待您了。”老妇人愁容满面，手指摸索着陪伴她多年的柜台：“最近治安不好，附近似乎有什么团伙在集结，发生了不少事件……我的家人都反对继续开店，明天我就要搬走了。”\r\n“哦……对了。”老妇人从柜台中收拾出几个罐子，然后用纸袋包装好递给韩赛尔：“你的妹妹很喜欢这个方糖，因为是我家店里自制的，外面买不到，请让我送你一些吧。”\r\n韩赛尔没有应声，她站在原地似乎陷入了沉思，时间久到店主快要迟疑地收回手的那一刻，她接过了纸袋。\r\n“我收到了。”韩赛尔点点头：“请您不用太担心，这家店，一定能继续营业的。”\r\n店主一头雾水地目送她离开，没有把这件事放在心上。\r\n晚上回到家中，家人们围坐在餐桌上闲聊，电视里新闻懒洋洋地播报着，突然，一条插播新闻引起了所有人的注意。\r\n“……近日，一直在威廉代尔街道活动的违法份子已被全部拘捕，街道治安恢复正常，值得注意的是，在拘捕现场的时候，犯罪份子大多都已经陷入昏迷，现场似乎发生过激烈的战斗，可能是当地派系斗争，详情仍在调查中……”\r\n老妇人看着新闻，呆愣在当场。\r\n孙女奇道：“这不是奶奶开店的那条街吗？……这下太好了，奶奶不用关店了。”\r\n“是啊……”老妇人不知道在想什么，神情恍惚地又重复了一遍：“是啊。”\r\n\r\n其乐融融的一家人并不知道，在窗外的寒风中，一只蓝色的小鸟在电线杆上，把他们的反应尽收眼底。\r\n“辛苦你了，斯威特先生。”韩赛尔在远处喃喃自语，借用蓝色小鸟的双眼看到了一切：“这次的任务也顺利结束了，没有辜负店主的报酬。”\r\n她说完，抬手从纸袋中取出一颗方糖放入嘴中。\r\n浓郁醇厚的甜味逸散开来，是令人幸福的味道。"
	},
	{
		2000029,
		204,
		1,
		"袖扣",
		"100029_xiedaiwu_04",
		"不可视学院的毕业礼物，本来是教员们送给优秀学员格蕾特的，上面还刻着格蕾特的名字，现在是韩赛尔珍贵的宝物",
		"她在门外。\r\n门内是她唯一的家人格蕾特，她在痛呼、在尖叫——门内有她们无法战胜的原体。\r\n格蕾特把她推出去，为了困住那个原体，格蕾特从里面锁住了门，怪物在嚎叫，有血腥味，红色的液体从门缝里渗透出来。\r\n韩赛尔很弱小。\r\n她只能哭喊，双胞胎之间的莫名联系让她知道，格蕾特的气息越来越弱了。\r\n“逃……”格蕾特虚弱的声音从门内传来：“我撑不了多久，逃啊！逃啊！”\r\n逃。\r\n逃去哪里呢？\r\n她无助地看向漆黑的长廊，又看着自己受伤的小腿，只能拼命运转能力驱动蓝鸲斯威特，希望小鸟飞的快点，尽快把求救的信息传到老师们的手里。\r\n门内，格蕾特的声音消失了。\r\n门开始剧烈地振动——贪食的原体还没有吃饱，它知道外面还有一个美味的食物。\r\n韩赛尔颤抖着手，握住那把单口狙击枪，怅然了片刻，手又松开了。\r\n绝望如同滴入水池的墨，一点点氤氲开来，侵蚀了她的心。\r\n就这样吧，教案中说过死于密室的人会被抹除现实的存在，格蕾特与韩赛尔是彼此的唯一，她们没有更亲密的家人和朋友了，如果妹妹失去现实存在。\r\n那她应该去陪她，她们要永远在一起。\r\n怪物打开了门，露出了丑恶的进食器官，冲她叫喊，向她袭来。\r\n韩赛尔想闭上眼睛。\r\n“……逃。”\r\n熟悉的声音。每天都能听到的熟悉声音，是那个早上叫她起床，总是包含关心的，最重要的人的声音。\r\n韩赛尔睁开眼睛，已经看不出本来样子的格蕾特抓住了原体，用残破的身躯，用最后的力气，将武器捣入了原体的核心。\r\n怪物尖叫着死去了，韩赛尔看着眼前的一切，拖着伤腿颤抖着爬过去，握住了格蕾特的手。\r\n“……笨蛋，韩赛尔。”格蕾特看着她，模糊的面容眼睛依旧亮的惊人：“你不能死。”\r\n学院的教员们赶来的时候，只看见女孩儿捧着空荡荡的衣物，握着一个吊坠，浑身是血地坐在地上。\r\n教员问她是双胞胎中的哪一个，看到那张满是泪痕的脸，那种不属于格蕾特的软弱神态，教员不禁从鼻腔里发出了一声失望又轻蔑的哼声：“活下来的是你啊，韩赛尔。”\r\n所有人都很失望，优秀的格蕾特没有活下来，笨蛋韩赛尔幸存了。\r\n她不在乎这些人的失望。\r\n吊坠发着温柔的光，消耗了大量体力的斯威特落在她的肩膀上，也许是察觉到了韩赛尔的痛苦，它用冰凉的喙，疲惫又轻柔地磨蹭她的脸颊。\r\n韩赛尔也抚摸他，鸟类柔软的羽毛让她平静了许多，疼痛逐渐传来——她也受了不小的伤。\r\n\r\n这件事后过了许久。\r\n韩赛尔至今还能想起，在毕业典礼上，教员把给格蕾特准备的毕业礼物——闪闪发光的袖扣递到韩赛尔的手上。\r\n金属的球面上有手工刻下的、格蕾特的名字，教员不认为韩赛尔能够毕业，所以根本没有准备她的礼物。他们还是选择送出这个袖扣，或许带着安抚、悲伤、劝慰、失望……或者是嘲讽的意味。\r\n但她不在乎这些人的感情。"
	},
	{
		2000030,
		201,
		1,
		"大列巴茶",
		"100030_xiedaiwu_01",
		"最大瓶装的大列巴茶，不会喝的人哪怕只是闻到都有上头的风险",
		"炸裂声响起，因为剧烈反应崩裂的金属外壳，正变成尖锐的碎片在空气中激射，周围的人要么躲藏，要么因为受伤而倒在地上。\r\n唯有波波莎，她感受到金属碎片划破皮肤，破口处流淌的温热液体，却只是用眼睛随意瞥瞥周围的情况，看到战友们并没有咽气，她很放心地——从怀里掏出了不锈钢的水壶。\r\n赶来支援的布狄卡一眼就看到了，随即大怒。\r\n“波——波——莎——！！！”\r\n波波莎手腕顿了一下，她没回头，扛着武器面对着前方的敌人，然后……假装没听到那警告的怒吼，爽快地灌了自己一壶大列巴茶，她用鞋底蹭了蹭飞尘的沙地，兴奋地大喊。\r\n“呀呼！受死吧！小喽啰们！”\r\n她像是看不到严峻的战况，也听不见背后布狄卡的怒吼，她把这一切都抛在脑后，高浓度的饮品麻痹了她的神经……她好像感觉不到武器的重量，就好像下一秒要飞起来了！\r\n开启武器，敌人在尖叫逃窜恶毒地咒骂，她却听不见这些，热风从散热口喷涌而出，面颊伤口上的液体被烤干，变成痂拉扯着伤口的神经。\r\n灼热，疼痛，不是很舒服有点痒好想挠一挠……但真■■痛快！\r\n支援的战友们看到这一幕，都纷纷呐喊着上前，刚刚受伤的人也在布狄卡的治疗下恢复了部分精力，极快地投入战斗中。在所有人的共同努力下，敌方选择了撤退，这次的攻防以己方胜利为结局。\r\n队友们把波波莎从人群里捞出来，举高，抛起来，大声欢呼。\r\n虽然她晕乎乎的样子看上去并不靠谱，但是冲锋战斗的姿态无疑是鼓舞士气的，他们举着波波莎抛来抛去，然后嘴里还大声合唱着。\r\n“让我们的勇气和光荣，融化这片雪地。”\r\n“把野兽驱逐，把家园守护。”\r\n“我的爱人啊，不要害怕敌人的炮火。”\r\n“我们是英雄，会永远战斗在前方。”\r\n……\r\n\r\n布狄卡本来想要说教，但看到这一幕，最终还是不愿意打扰大家的兴致，露出无奈的笑容。\r\n“啊哈……我是英雄！”\r\n被抛来抛去的波波莎兴奋地大喊，脸上的笑容无比灿烂。\r\n她的视线随着被抛起来的落差上起下落，脑袋晕晕乎乎，她的精神高度兴奋，视线模糊地看到了，人群中似乎站着熟悉的身影。\r\n你们来了……看到了吗？我成为英雄了！\r\n你们也很高兴对不对，我们可以一起得到长官的夸奖！\r\n等等我……等等我啊！不要走！\r\n我们一起——\r\n“我们一起——呕呕呕呕……”\r\n……\r\n“布狄卡，这次的作战我们没有人员损失，大家都只是受了轻伤，并且收获颇丰，按理来说应该嘉奖波波莎……”\r\n“嗯……但是为什么大家要联名上书举报波波莎，这孩子又做了什么？这里违反纪律具体指的是什么？”\r\n“布狄卡，你面色怎么这么难看？什么叫我别问了……诶……到底怎么回事？”"
	},
	{
		2000030,
		202,
		1,
		"醒神药",
		"100030_xiedaiwu_02",
		"已经过期的盒装药片，背板的铝箔没有被破坏，显示着主人根本没有吃过它",
		"每个战士都会有部队下发的医药箱，里面会有准备好的应急药品，波波莎也有一个，不过从来没有打开过。\r\n不是因为她不会受伤，而是饮品的麻痹让她感觉不到小病小痛，等到真的受了那些让她能感觉到疼痛的伤害后……再次醒来，她已经躺在医务室的硬木板床上，布狄卡一边在她耳边骂骂咧咧，一边拿着绷带和药水给她治疗。\r\n“谢谢你，布狄卡——呃呃呃！好疼！”\r\n“肯定会疼啊！这么严重的伤口——你这家伙！是闭着眼睛往前冲吗！” \r\n“轻轻轻轻轻点！”\r\n病房内吵吵闹闹了好一阵子才安静下来，布狄卡怒气冲冲地把她教训了一番后，又急急忙忙离开去做别的工作了。\r\n房间里安静了没多久，一个护士推门进来送药，她详细交代了吃药的注意事项，多看了一眼波波莎，似乎是认出了这个因为无数次违反纪律上了黑名单的问题儿童，斟酌了一下用词，温柔地劝说：“伤口恢复的这段时间，不宜饮茶哦。”\r\n波波莎：“……”\r\n护士嘱咐完也离开了，病房陷入安静，波波莎看了一会儿天花板。\r\n哦哦……护士小姐嘱咐我，吃完药要睡一会儿恢复体力。\r\n她尝试闭上眼睛，黑暗淹没了视线，耳边的声音就变得明显了，门外有人来人往的脚步声，有人在痛呼，有人在大笑，有人跟爱的人相拥而泣，有人在角落里紧紧抱着自己的双膝。\r\n她睁开眼睛，发现自己蜷缩在被子里，紧紧抱着双膝。\r\n无法在清醒的状态下入睡。\r\n闭上眼睛，就会回到战场，回到那个她赖以生存，又夺走了她很多东西的地方。\r\n“波波莎卫士！”\r\n是布狄卡的声音，她很暴躁地推开门，波波莎立刻假装闭上眼睛。\r\n“你到底有没有好好听话把药吃完——诶？”布狄卡摸了一把盖得很严实的被子，然后立刻压低了声音：“睡着了？”\r\n传来翻塑料的声音。“唔，看来有把药吃完。”\r\n传来翻起床单，双膝贴在地板上趴下的声音。“我看看……没有藏大列巴茶？这家伙这次这么老实吗？”\r\n波波莎没忍住嘴角勾起，她又听见布狄卡从地上爬起来，听见她打开腰包的扣子，在里面翻找些什么。\r\n然后她轻手轻脚地，把什么东西放在了波波莎的枕头旁边。\r\n等到布狄卡终于做完自己的事情离开病房，波波莎也快要憋不住了，连忙把头从被窝里伸出来呼吸新鲜空气。\r\n她看向自己的枕边，一个纸盒，她捧起来端详了一会儿。\r\n“嗯？……特质强力醒神药？这都什么东西？”\r\n“我是绝对不会吃的——！谁要吃这种怪东西，真是……”\r\n“……哼。”\r\n她把纸盒擦拭干净，四处看看。\r\n最后，妥帖地放进了自己的医药箱。"
	},
	{
		2000030,
		203,
		1,
		"旧照片",
		"100030_xiedaiwu_03",
		"泛黄的旧照片，照片上是波波莎与曾经的战友们的合照，每个人都笑得很开心，但些微的磨损令某些细节模糊不清",
		"什么？合照？\r\n我才不要合照？蠢死了——喂！放手啊啊啊啊啊！\r\n“可是，这个暗房里用特殊液体冲洗的照片，可以保存很久。”\r\n就算是这样——\r\n“据说，就算是死在密室，啊，我是说，就算我们在密室时间牺牲，这张照片里的影像也不会消失！”\r\n“对不起，说了很不吉利的话，可是，万一我们牺牲了。”\r\n喂，不会牺牲啦。\r\n“哈哈，你说的也是……那就算了吧，我回去准备——”\r\n——你们几个！过来合照了！\r\n“……波波莎，谢谢你。”\r\n……\r\n今天阳光很好，难得会在冬日遇到这么好的阳光。\r\n也不是有作战任务的一天，几个战士结束训练，就在天台上坐着，大家带了饮料和零食，在天台玩一些挺无聊的纸牌游戏。\r\n这其实是违规的，但是长官大多都选择睁一只眼闭一只眼，默许大家偶尔的闲暇时光。\r\n波波莎手里拿着照片。\r\n那个孩子说的对，特殊液体能够保存很久的照片，虽然纸的边缘，已经有点老化泛黄了，但是影像却十分清晰，上面的人带着的笑脸，曾经生机勃勃的样子，就映在这个上面。\r\n她很珍惜地拿塑料薄膜把照片保护起来，阳光洒在上面，反光正好掩盖住了大家的面孔。\r\n露出的嘴角却因此更加有活力了起来，好像下一秒就会开口说话——\r\n——“波波莎！”\r\n“啊？啊？”波波莎回头，几个战友正盘腿坐在地上，饮料和零食都准备好了，纸牌游戏也打了一半。\r\n“你在发什么呆，快来快来。”有人招呼她：“别一个人在那里，一副大家不带你玩的样子。”\r\n“就是说啊，难得休假，快过来！”\r\n“波波莎，你得帮我赢下这一局！太可气了泰尔！别动我的零食！”\r\n……\r\n大家吵吵闹闹的样子，让波波沙有一瞬间的恍惚，她好像回到了曾经，还没有正式参加过战斗的他们也像这样。\r\n她又看了一眼手中的照片，珍惜地擦拭了一下，然后收回怀中。\r\n“来了来了。”"
	},
	{
