		"陈旧的乌山卡帽",
		"100030_xiedaiwu_04",
		"曾经属于某人的帽子，如今被波波莎妥善地收在箱底，再也没有回到曾经的主人身边的机会",
		"灌木掩盖下，地面上躺倒了一片战士，他们灰头土脸地呼呼大睡，没有人敢点篝火，害怕暴露己方的方位，所以波波莎只能借助森冷的月光看东西。\r\n今晚是她执勤，在作战计划没有结束的时候，睡觉是一件极其危险的事情，因此总会留两个人守夜执勤。\r\n这晚跟她一起守夜的，是刚刚加入的新人，这让她想起几年前的一个夜晚。\r\n那天晚上也是她执勤，跟她一起守夜的是一位老兵。\r\n队伍中那么多人，并不是每个人她都叫得上名字，这个人带着一个很破旧的乌山卡帽，遮住了大部分的脸，波波莎一边无聊拨弄着武器，一边疑惑现在有这么冷吗？他怎么把头裹的这么严实？\r\n那天的月亮在云层后面，投下来的光灰蒙蒙的一片，让人看不清东西，波波莎和这位不熟悉的战友小声的聊天，以此来打起精神守夜。\r\n“嘿，给你喝点好东西。”战友从怀中掏出一个，带有体温的铝制水壶，神秘兮兮左顾右盼一番后，才把盖子拧开，递到了波波莎的手中。\r\n刚刚结果水壶，颇有冲击力的味道把波波莎熏得目眩神迷，好一会儿才反应过来这是违纪饮品，立刻把水壶还给战友。\r\n“你怎么带这种东西！”\r\n“什么……你不会喝大列巴茶？果然还是小孩子啊。”\r\n“这是违反纪律的！”\r\n“不要这么无聊啊，”战友将水壶举起，咕嘟咕嘟喝着里面的液体，最后发出畅快的笑声：“哈——！果然还是要有这个！”\r\n他声音其实不算大，但是波波莎还是警觉地提醒他放低声音，两个人有一搭没一搭地围着篝火聊天，聊得大多是战友自己辉煌的战斗史，不过详细的内容，波波莎已经记不清了。\r\n……\r\n“那之后呢？”新人睁大眼睛：“你和那位——战友前辈，之后怎么样了？”\r\n之后吗？\r\n密室时间的战场比一般的战场更危险，与那些没有感情与血肉的怪物战斗时，人很容易团结在一起，把彼此当做最重要的兄弟。\r\n“喂！你——”\r\n“我们需要救援，通讯设备全部损坏了……应该需要你跑腿去叫增援。”\r\n“哈哈哈哈，当然是因为你跑的最快，再说了，现在又不是多一个人参与战斗就能解决的战局。”\r\n“——虽然还不知道你叫什么，能拜托你吗？”\r\n他取下头顶破旧的乌山卡帽，强行摁在波波莎的头上。\r\n那人的头上有一整块烧灼留下的秃斑，很难看，和他另外一边茂密的头发形成鲜明对比，这就是他要整天带着帽子的原因。\r\n但他此刻好像什么也不在乎了，举着武器对着前方大喊。\r\n“冲我来吧！该死的怪物们！”\r\n……\r\n“他后来啊——哎呀，我记不清楚啦！”波波莎挠着头嘿嘿笑着：“肯定还是在哪个队伍里偷偷喝违禁品，每天浑水摸鱼做梦有一天能拿到功勋吧——哈哈哈哈哈哈！”\r\n说着说着，她想起那顶被妥善放在箱底的乌山卡帽，想起帽子的内壁缝着的功勋奖章，想起那个夜晚燃烧的篝火明灭，想起那个人头上丑陋的秃斑——\r\n——她从怀里掏出带着体温的铝制水壶。 \r\n笑着对新人说。\r\n“嘿，给你喝点好东西。”"
	},
	{
		2000031,
		201,
		1,
		"七星瓢虫",
		"100031_xiedaiwu_01",
		"指甲盖大小的圆滚滚虫子，花园中随处可见的七星瓢虫，有着夺目的鲜艳色彩",
		"“吱呀——”，金属摩擦的声音从巷子传来，惊飞了树上歇息的鸟。\r\n扭腰在露台上拍打着被子的主妇看到扑腾的鸟花容失色，甩下木棍匆匆跑回室内，紧接着是上锁的声音。\r\n“流浪汉们又从下水道里钻出来了。”压低的声音从室内里传出来。\r\n流浪汉又从下水道里钻出来了，巷口出现了一个穿着灰色棉衣，带着帽子的小小身影。\r\n\r\n白羽特别州第三十州是公认的堕落之城，错综复杂的地下水道构成了城市的心脏，这里藏着数万无家可归的人。领土、食物、物资的争夺是地下大陆每天的战争，冬天的每一件棉衣都是暗无天日王国的战勋。\r\n只见穿着棉衣的小小身影走向了垃圾站，开始了熟悉的倒腾。\r\n大袋的垃圾全部丢到一旁，这里面只有报纸、空盒和用过的纸巾一类毫无意义的东西，再翻也只是无用功。中袋的垃圾先掂量一下重量，运气好的时候能在里面找到刚开始腐坏的苹果和生菜。小袋垃圾则有种赌博的感觉，也许里面装的是刚过期的面包和沙拉，也许里面装的是一些污秽的体液。\r\n小小的身影直起身拍了拍身上的尘土，提着一个牛皮纸袋跳出了垃圾站，看来今天是好运的一天。她把牛皮纸袋小心翼翼放近棉衣里，假装若无其事吹着口哨走到路边，再恶作剧踢了踢流浪猫的屁股，看着咧牙警惕状的猫哈哈大笑。在阵阵喇叭的鸣笛声中，小小身影跃过了马路，走进了公园。\r\n\r\n清晨的公园还没有人，小小身影环顾一圈后将视线锁定在花丛侧的水龙头，直径走过去。洁净的水是地下最为稀缺的资源，方便引水的地方都被几位“君主”牢牢占据。\r\n小小的身影卷起衣袖，试探性伸手触摸了一下水后龇牙缩回到袖中，不知是因为疼痛还是寒冷。犹豫片刻，她再次鼓气勇气靠近水流，咬着牙洗刷身上的污秽。灰色的，暗红的，不知是洗刷第几遍后水才回归透明。\r\n还有一个红色的点没刷干净，是昨天打架留下的伤口吗？小小身影睁开一丝眼睛，疑惑看着腿上的红点。\r\n不对，不会这么凸起，这不会是伤口发炎吧，还是感染上了什么恶心的病？小小身影把头发拨到脑后，顾不得水浸湿棉衣，用力瞪大眼睛。\r\n只见红色的点，不，是红黑交错的点安静停留在她的小腿上纹丝不动，两侧的翅膀随着呼吸微微颤动。小小身影从未见过如此绚丽的虫子，一时竟看入迷了。\r\n灰霾的天，枯黄的植物，褪色的公园中出现了唯一的亮色，在暗无天日的下水道中不曾出现的颜色。\r\n小小声影伸出食指，小心翼翼接近这抹红点，红点抖了抖翅膀飞上她的指尖。她好奇把脸凑近去看，红点竟飞到了她的鼻尖，空荡的公园里一人一虫玩得不亦乐乎。\r\n\r\n随着卖报童的吆喝声响起，城市也逐渐苏醒，热气腾腾的香味唤醒了沉迷红点的小小身影。游戏该结束了，她遗憾将小红点放到花朵上，看着红点展开翅膀飞入花丛中，逐渐消失。\r\n甩头，像流浪犬般猛甩头，甩了一地水渍后她拉下袖子和裤腿，把满是伤痕的四肢捂得严严实实，再认真整理贝雷帽，确定不会再次花落。\r\n该去寻找下一个栖息地了，她想。"
	},
	{
		2000031,
		202,
		1,
		"自制糖果",
		"100031_xiedaiwu_02",
		"啡色箔紙包裹的太妃糖，奶味浓厚，放进口中有一丝甜蜜的暖意",
		"结束了每日觅食后，小小身影又晃悠进了公园里。这是她这周第四次在花丛里翻找，但始终没有再见到过红色的虫子。\r\n早知道应该抓起来的，她懊恼蹲在地上发出哀鸣。但是即使抓起来，也不知道小不点吃什么呀。小不点是吃什么的呢，虫子吗？这玩意在下水道倒是一抓一大把……\r\n“你在找什么吗？”一个和蔼的声音打断了小小身影的胡思乱想。\r\n“糖，一块甜甜的糖。”她有气无力瞎诌到，旁边传来一身轻笑。\r\n有什么似乎出现在自己的面前，小小身影睁开了眼睛，只见到一个布满皱纹的手在自己身前摊开，掌心中躺着一颗金属锡纸包裹的糖。\r\n\r\n“这是给我的吗？”她好奇瞪大眼睛，卖乖这件事对所有小流浪汉来说轻而易举。\r\n“你是狼人亚种吧，孩子。”摊开手的老奶奶眯着眼睛和蔼问到。\r\n“我听不懂你在说什么。”她眼神变得尖锐，灰色棉衣下的手做出了准备进攻的姿势。\r\n“放松，不要紧张，我在你身上闻到了熟悉的气味，孩子。”老奶奶拍了拍她的肩膀，微笑着摘下帽子，露出了毛茸茸的耳朵。\r\n小小身影有些吃惊，熟悉的气味后知后觉钻入她的鼻腔中，这是她在这个世界上第一次闻到的气味，毛茸茸的同族的气味。不，也不是第一次，当她还在母亲襁褓中的时候应该也闻到过，但她已经记不清了，连带母亲的样子一起记不清了。\r\n这是什么样的气味呢，小小身影不会描述，她只知道这与下水道的冰冷不同，与垃圾站的恶臭不同，与小巷的灰霾不同。这是是温暖的气味，像冬日午间的阳光，像隔着橱窗看到的炉火。\r\n“别哭，孩子，吃糖。”老奶奶温柔轻拍着她的后背，一阵又一阵，如母亲的手掌般温柔。\r\n小小身影抓着糖狼狈撕开吞下，鼻子红红的。\r\n\r\n“孩子，你叫什么名字？”老奶奶温柔问道。\r\n“我没有名字。”她摇头。\r\n“你和家人生活在哪里？”老奶奶关怀问道。\r\n“我没有家人，我一个人生活在下水道。”她指了指地下，老奶奶眉头紧锁。\r\n\r\n“我们是骄傲的种群，阳光、月光和自然才能给我们温暖，你不能一直生活在地下。”老奶奶摇摇头，开始重新审视眼前的孩子。\r\n脏兮兮的孩子耷拉着眼眸，额头上有一道浅浅的伤口，耳后也是。她双手不自在捏着衣角，灰色的棉衣全是补丁，发丝还夹着不知道哪里来的纸片，像是一只可怜的小狗。\r\n“孩子，你愿意和我一起生活吗？”老奶奶问道。\r\n“我……可以吗？”她第一次感到不知所措。"
	},
	{
		2000031,
		203,
		1,
		"可爱骨头挂件",
		"100031_xiedaiwu_03",
		"挂在卡布奇诺包包上，走路会发出声响的骨头挂件。据说是全世界独一份，由自称大师的提拉米苏制作",
		"小小身影跟随纸条上的字走到了一个大房子，她站在门前开始犹豫。准切点说，遇到同族的感动劲过去后她便开始感到不安，在阳光下生活的不安。\r\n她在地下王国学会了如何当一个卓越的小偷、当一个聪明的拾荒者、当一个狠毒的战士、当一个游手好闲的混混，唯独没有学到如何做一个正常人、一个充满善意的人。\r\n她抬起想要按门铃的手又缓缓落下，装在棉衣帽兜里的刚从野外采回来的鲜花有些棘手，也许转身走回黑暗里才是一个正确的选择吧，她想。\r\n\r\n“吱呀——”和井盖被撬开的尖锐声不同，木质大门拉开的声音竟是悦耳的。\r\n“进来吧孩子，来了好一会儿了吧？我闻到了你的气息。”老奶奶微笑着而朝她招了招手，看她没反应后拉起了她小小的手，将她带入门后的世界。这是一双充满皱褶却又无比温暖的手，和门后的院子一样，设施陈旧，却能容纳所有的阳光。\r\n“这花是送给我的礼物吗？老太婆太久没收到花了，你真是个贴心的孩子。”老奶奶注意到小小身影的怀里有鲜花湿漉漉的气味。\r\n“是的……给您……！”小小身影慌张从怀里掏出鲜花，引得老奶奶一顿轻笑。\r\n\r\n温暖的屋子，合脚的毛绒拖鞋，碎花点缀的桌布，冒着烟的热茶。小小身影拘谨坐在椅子上，生怕自己脏脏的衣袖碰脏眼前美好得一切。\r\n“来吧，孩子，这是为你特意准备的糕点，尝尝看。”老奶奶转身将鲜花束插入花瓶中，看到她拘束坐在餐桌前的样子有些好笑。“不用拘谨，家里还有另外一位……”\r\n“奶奶！这个脏兮兮的人是谁啊？为什么给她吃我的蛋糕！”一个甜甜的声音带着抱怨从楼上传来。\r\n女孩顺着声音往上看，看到楼梯里站着一个穿着蓬蓬裙、像洋娃娃一样的女孩。她的身上没有一丝灰尘，连耳朵的毛发都顺滑而光亮，小小身影再看看灰扑扑的自己，一心只想钻到地缝里。\r\n\r\n“这是我说的家里的新成员，她在外面历经苦难，当然和我们不一样。提拉米苏，你刚刚说的话很伤人，奶奶很生气，你应该向她道歉。”老奶奶收起了笑脸，严肃道。\r\n“对不起，我不是故意的。我把蛋糕分你一半好不好？我把漂亮的裙子给你穿好不好？”洋娃娃意识到自己的失礼，绕在小小身影边扑闪着大眼睛不断道歉。\r\n“不，不用，我没有生气。”她避开洋娃娃诚恳的视线，陌生人的亲近让她感到不太自在。\r\n“啊，我还给你准备了见面礼，是我自己亲手做的挂件哦！漂亮吧！”洋娃娃变魔术板般从口袋里掏出了一个钥匙扣，塞到了她的手中。\r\n这是一个串着可爱吊坠的钥匙扣，吊坠表层涂的亮片在阳光下闪闪发光，小小身影看着竟又红了鼻头，这是她第一次收的礼物。\r\n\r\n这是小小身影在阳光下的第一天，她在今天学会了很多东西。学会了开热水，学会了如何正确洗澡，学会了用刀叉吃东西，学会了用水杯喝水。\r\n学会了有一种带有苦味的蛋糕叫做提拉米苏，这是家里漂亮洋娃娃的名字。学会了有一种带着奶味的热饮叫做卡布奇诺，这是她自己的名字。"
	},
	{
		2000031,
