		"草莓奶油蛋糕",
		"100031_xiedaiwu_04",
		"果酱、鲜草莓、甜美奶油与柔软的戚风蛋糕，所有甜品爱好者都无法拒绝的美味。",
		"不知不觉间，卡布奇诺已经在大房子度过了五个春夏秋冬。\r\n有厚厚的被子和床可以睡个好觉，有干净且暖和的衣服可以穿在身上，每天都有新鲜的食物，不需要饿一顿饱一顿，对卡布奇诺来说已经像是做梦般幸福了。虽然屋子里的讨厌鬼每天调皮惹事还爱眨着无辜的眼睛瞎告状，虽然奶奶会苛刻要求自己读一些晦涩难懂的书本，但更多的是快乐的时刻。\r\n一丝香甜的气味钻入卡布奇诺的鼻尖，打断了她在太阳底下的胡思乱想。\r\n“吃蛋糕啦。”屋里传来慈祥的声音。\r\n“来啦！”卡布奇诺撒脚往屋子里跑去。\r\n\r\n“奶奶，今天是什么日子呀，居然有这么丰盛的晚餐！”讨厌鬼提拉米苏眨着亮闪闪的大眼睛问。\r\n“坐下，小馋猫，先让老太婆把话说完。”奶奶好笑拍开提拉米苏的魔爪，把蛋糕从纸盒里小心翼翼拿出来。\r\n“哇！”提拉米苏和卡布奇诺都惊喜长大了嘴巴，这是她们最喜欢的草莓蛋糕。\r\n“我不知道我是什么时候生日的，卡布奇诺你也是，提拉米苏也是。但我记得12月21日是我收养你们的日子。卡布奇诺是五年前，提拉米苏是六年前，时间过得可真快，完全不等老太太啊。”奶奶说着自顾自笑了起来。\r\n“孩子们，明天我要离开了，要去个很远很远的地方，我们不能相见了。不用担心，我给你们买了去第五州的车票，我不会让你们回到过去的生活，老太太只希望你们安全健康成长。”老奶奶在蛋糕上插上五颜六色的蜡烛，卡布奇诺和提拉米苏被突如其来的消息惊得有些不知所措。\r\n\r\n“奶奶，我不想去，我想陪在你身边。”卡布奇诺站起来大声说。\r\n“你们要去一个叫诺亚的地方，那是一栋很壮观的高楼啊，像模像样的……”奶奶没有理会卡布奇诺，自顾自说道，“你们要去找另外一个老太婆，不，也不一定是老太婆，也许只有我是这样的一副疲态吧，她叫曼森，她会为你们做接下来的安排的。虽然这女人有些做作，但对同族也总是有庇护的。”\r\n提拉米苏用眼神向卡布奇诺求助，卡布奇诺摇了摇头表示自己也不知道发生了什么。\r\n\r\n“来吧，孩子们，就把这天定做我们的生日吧，我们一起过一个生日吧。”奶奶微笑点燃了蜡烛，向卡布奇诺和提拉米苏招招手，示意他们吹蜡烛。\r\n“老太婆就先许愿了，祝我的两个孩子平平安安，健康成长。”奶奶双手合十，诚恳许愿。\r\n“呼——”提拉米苏犹豫吹灭了蜡烛。\r\n“啪啪啪……”卡布奇诺觉得这个时候她应该鼓掌。\r\n\r\n明明是最爱吃的鲜奶油蛋糕，但提拉米苏和卡布奇诺不知道为什么无法提起精神。或许是奶奶告别的决心不容置疑，她们在不舍，又或许是奶奶身上散发的灰败的气味有些浓厚，这气味无论对卡布奇诺或提拉米苏而言都并不陌生。\r\n这是最后的一顿晚餐，卡布奇诺深知。她的心里有好多好多的苦涩，草莓蛋糕带来的苦涩。"
	},
	{
		2000036,
		201,
		1,
		"没有邮戳的信函",
		"100036_xiedaiwu_01",
		"寄到多萝西家中的神秘信函。上等的牛皮纸，淡淡的玫瑰花香，精致的火漆印，体现出寄信者的优雅。但为什么对方那么粗心，忘记贴邮票了呢？",
		"自从九岁生日之后，快乐的小女孩多萝西有点郁闷。\r\n\r\n生日当晚，九岁的多萝西独自呆在被窝里，紧紧地抱着兔子玩偶，那是爸爸妈妈为她定制的礼物，由著名玩偶艺术家手作而成。爸爸妈妈煞费苦心定制了这份生日礼物，只是希望这个玩偶能让多萝西开始学习独立——多萝西每天晚上都缠着爸爸妈妈给她念睡前故事，但一个九岁的孩子必须懂得爸爸妈妈不能永远哄她入睡，而她也不能永远依赖他们。\r\n多萝西一边嘟囔地爸爸妈妈的狠心，一边在兔子玩偶的陪伴下睡着了，甚至做起了独特的梦：在梦里，她来到了一个奇幻的王国，道路上流淌着红色和紫色交叠的色彩，路灯和邮筒都在向她招手，掉在地上的星星发出清脆的响声。更奇怪的是，王国里所有人都在沉睡，就连爸爸妈妈都在梦游，多萝西试图跟他们打招呼却无法得到回应。多萝西继续在梦里行走，当筋疲力尽的她快要失去意识的时候，王国的信使狐狸先生为她指明了出口，带她离开了王国。\r\n多萝西从梦中醒来，兴奋地想要把这个梦告诉爸爸妈妈时，却发现他们神不守舍，甚至忘记了要做早餐。他们十分慌张地检查多萝西，嘴上一直说着“火焰、怪物”等字眼，尽管多萝西身上并没有异常，他们的怀疑仍然没有消除。\r\n\r\n尽管如此，多萝西的生活却比以往更为生动，她经常去拜访那个奇妙的王国，招呼新朋友来到家中做客。有时候，多萝西想把跟新认识的朋友介绍给爸爸妈妈，但是他们只会惊讶甚至惊恐地盯着她，仿佛眼前的人早已不是他们的最爱的女儿一般。\r\n就这样，爸爸妈妈逐渐疏远了多萝西。他们的时间不再用来陪伴多萝西，而是用来埋怨、争吵，频繁地外出，然后从再带回许多奇怪的精神类药物。多萝西有点摸不着头脑，但她坚信这只是大人的周期性烦恼。\r\n\r\n某一天，她看到爸爸妈妈一反常态地呆在客厅里，带着无法形容的奇怪笑容在低语。当多萝西小心翼翼地靠近他们时，她看到了爸爸妈妈手里拿着一封奇怪的信件。整洁的牛皮纸信封散发着清香，旁边还附赠了一朵玫瑰，看起来像是早晨新鲜剪下的。\r\n“爸爸妈妈.......你们在看什么？”\r\n多萝西的爸爸妈妈显然吓了一跳。但他们很快整理好桌上的信纸和脸上的表情，认真地对多萝西说：\r\n“多萝西，我们去旅行吧。”说完，他们脸上露出了消失很久的笑容。\r\n\r\n多萝西想，也许她那些快乐的日子终于要回来了。"
	},
	{
		2000036,
		202,
		1,
		"游乐园门票",
		"100036_xiedaiwu_02",
		"藏在多萝西衣服内侧口袋的一张旧门票，已经过期很久了。原本是家庭套票，另外两张成人票已经遗失",
		"多萝西的家庭旅行有着一个愉快的开始。爸爸开的车又快又稳，风从车窗里吹进来，多萝西就这样在妈妈怀里睡着了。在迷糊中，多萝西隐约感受到车子停下了，她睁开双眼，眼前正是她梦寐以求的乐境游乐园！\r\n多萝西不能更高兴了，她拉着爸爸妈妈向游乐园检票口跑去，而检票员是个不太上心的年轻人，他慢悠悠地撕下游乐园门票的副票，急得多萝西直跺脚。好不容易进了游乐园，多萝西又犯了难：这里可太多有趣的东西了，该从哪里开始玩起呢？\r\n爸爸妈妈看出了多萝西天真的烦恼，轻轻拍她的头安慰着说：\r\n“不用急，我们还有一整天时间呢。”\r\n\r\n柔声细语让多萝西完全忘掉了曾经不愉快的事情，她又变成了快乐的小女孩，一会儿要去坐摩天轮，一会儿要去，一会儿还要爸爸妈妈给她买四种口味的冰激凌球。\r\n当然，所有让小孩子眼花缭乱的把戏里，最能吸引多萝西的还是旋转木马。斑斓的彩灯和轻扬的音乐构成了梦幻的画面，多萝西坐上了彩虹色的木马，她感觉自己像是飞在天上的独角兽。\r\n“爸爸妈妈，再玩一次吧！”多萝西意犹未尽，而爸爸妈妈当然架不住她的撒娇。\r\n“再来一次！”多萝西就像是中了女巫的迷惑，完全沉浸在这个游戏中。\r\n“还想玩！”\r\n“最后一次！”\r\n…………\r\n\r\n在一次又一次地游玩后，多萝西已经忘记了时间，也忘记了地点，因为她眼前不再是那个人造的游乐园，而是一个真实存在的梦幻王国，巧克力的河流上飘着七色的糖果，岸边的狐狸和兔子在友好地喝着红茶，还有一个由黑色烟雾构成的大块头，带着两个小伙伴兴高采烈地向多萝西跑来，像是要跟她说些什么。\r\n直到这时候，多萝西才反应过来天已经黑了。她跳下旋转木马，打算叫上爸爸妈妈一起回家。可是爸爸妈妈不在她身旁，也不在她背后。\r\n\r\n多萝西有一种不好的预感：爸爸妈妈走丢了。于是她走啊走啊，四处寻找爸爸妈妈的身影，却毫无发现。多萝西孤零零地走在空旷的游乐园里，脚上的小皮鞋只剩下一只，而凉飕飕的晚风把沙子吹进她的眼睛，让她越揉越难受，泪水忍不住流出来。\r\n就这样，多萝西最后的一丝意志也崩溃了。正当她无力地蹲坐在地上放声大哭时，突然传来一阵不紧不慢的脚步声。\r\n“多萝西小姐，我来接你了。”\r\n\r\n多萝西最想听到的这番话来自来自一个陌生的男子。他两鬓有些不易察觉的白发，穿着工整的西服，将礼帽取下放在胸前，展现出对这个九岁小女孩的礼貌和尊重。\r\n“不，我要等爸爸妈妈，他们……会来接我的。”\r\n“多萝西小姐，你还不知道吗？”他清了清嗓子，尽量用温和的语调来修饰接下来要说的话。\r\n“游乐园之旅结束了。你的爸爸妈妈，已经不会再回来找你了。”"
	},
	{
		2000036,
		203,
		1,
		"绅士与开花先生",
		"100036_xiedaiwu_03",
		"多萝西的玩偶……正确来说是朋友。而作为朋友，不仅要做一个合格的倾听者，更要在她危急之时挺身而出",
		"刚来到不可视学校的第一天，多萝西就成为了最受欢迎的孩子。她会主动跟每个老师和同学打招呼，也会热情地向同学介绍自己见过的好东西，让不可视学校里那些没出过远门的同学们羡慕不已。\r\n但是，可别把多萝西想象成安分的小孩。她白天跟学校里的小伙伴们打探情况，晚上探索每一个隐蔽的角落，以规划自己的逃跑路线。虽然这里的门卫和那个名为“黑鸦”的管家对多萝西严加看管，但多萝西总是把他们绕得团团转，甚至还撞得鼻青脸肿，像是被某人打了一顿似的。\r\n\r\n热闹的校庆日到来了，多萝西决定在今晚实行逃跑计划。她悄悄从聚会中溜出来，沿着树林旁的小路来到一个隐蔽的侧门，这里没有灯光点缀，所以门卫总是早早就开始打瞌睡了。多萝西屏住呼吸，轻轻地推开门。侧门顺利地打开了，多萝西侧身从门缝中挤出去，拔腿就跑。\r\n多萝西的动静惊扰了枝头上的乌鸦，它就像个待宰的公鸡一样嘶哑地喊叫起来，惊扰了门卫。在听到门卫的摇铃声后，更多的守卫从各方向赶过来，像是一早就预料到今晚会有一场儿戏。虽然掌握了学校的信息，但是多萝西对于校外环境可是一概不知。她只能拼命地往前跑，听着身后的脚步声越来越重，越来越多。说到底，她也只是个小孩子，在跑了不知道多久之后，她终于体力不支，被小石块绊倒，狠狠地摔在地上。多萝西没有办法站起来了，她只能闭上眼睛，听着背后的脚步声和喧闹声逐渐靠近，然后停下。一种无法抵挡的力量一把抓住了多萝西，把她吊到空中。多萝西害怕得浑身发抖，等待接下来的审判。\r\n然而，多萝西没有遭到惩罚和责骂，反而她被轻轻放下，柔软的草地让她的脸有点痒痒的。\r\n\r\n“多萝西，我们来救你啦。”\r\n“多萝西，喂，快醒醒啊。”\r\n两个声音几乎同时响起，多萝西睁开眼睛，看到一个穿着整齐西装的稻草人玩偶和一个拥有狮子、山羊和蛇头作为脑袋的布娃娃；在它们的身后，一个由黑色烟雾构成的大个子不知所措地挠着头，正在为自己刚刚下手太重而感到抱歉。\r\n多萝西反应过来了：它们的长相，跟乐境游乐园的虚幻王国里的生物一模一样！\r\n接着，地上的两个小家伙叽叽喳喳地说起多萝西是如何把它们从游乐园里救了出来，而它们又是如何跟随多萝西来到学校，帮助多萝西在校园里探险，又帮助她在逃跑路上清理了碍事的家伙，追赶她的守卫早已经被大个子打得东倒西歪。看到这情景，多萝西忍不住笑了出来。\r\n大个子高兴地拍起了手，它的力气太大了，震得周围的树叶都掉了下来。接着，他叽里咕噜地嘟囔起来：“啊唔唔……啊啊啊……”\r\n“小黑，你的意思是……？”多萝西自然而然地接过大个子的话题，还给新朋友取了个名字。\r\n“多萝西，你能听懂吗？”\r\n“多萝西，这家伙这几天一直在重复这句话。”\r\n多萝西这时候才知道，虽然它们三个家伙一直一起行动，但是稻草人玩偶和三头布娃娃完全听不懂小黑的语言。接着，她决定称呼另外两个朋友为“绅士”和“开花先生”。这让三个家伙高兴不已，因为有了名字，就意味着成为特别的存在。\r\n“我能听懂哦……小黑说，它知道我的爸爸妈妈在哪里，它要带我去见他们。”\r\n\r\n另一边，黑鸦管家正在向奥罗拉大小姐报告这起小小的骚乱。\r\n听完汇报的奥罗拉小姐并没有表现出生气或慌乱，她细致地为花园里的每一朵玫瑰浇水，微笑着说：\r\n“由她去吧。她会回来的。”"
	},
	{
		2000036,
		204,
		1,
		"儿童教育丛书·卷一",
		"100036_xiedaiwu_04",
		"儿童教育丛书之《关于如何治疗刺激性精神创伤的50种方法》，精装重制版。对于其他孩子来说也许有点晦涩难懂，但多萝西总是对这类书籍兴趣盎然",
		"多萝西回到白银黎明的消息传遍了整个学校，过了几天，“父亲”宣布赐予多萝西“幺女”的头衔。虽然如此，多萝西还是以前的多萝西，依然以友善的微笑回应着大家的目光，温暖地对待每个奇怪的“朋友”。\r\n但大家们却能感受到她发生了一些微小的变化。她再也不会想出怪招数来捉弄老师，再也不会吵闹着要出去玩；最重要的是，多萝西再也不读童话冒险故事了。她手中的书本变成了一系列的儿童教育丛书，在以往的多萝西看来，这种书本晦涩又乏味。\r\n\r\n这一天的下午茶时间，多萝西像往常一样来到图书馆的角落，刚坐下就被人打断了。\r\n“今天看的是什么书？”温柔的女声在询问多萝西，她听出了来人是奥罗拉。\r\n“《关于如何治疗刺激性精神创伤的50种方法》”\r\n“你去过白银黎明疗养院了吧？”\r\n“嗯，在那里见到我的父母啦。”多萝西的语调没有变化，仿佛在诉说一件无关自己的事情。\r\n“貌似你一直没有说起这件事呢。”\r\n\r\n其实多萝西有很多话想说。前几天，小黑带她去了那个隶属于白银黎明的疗养院。这里住着一群奇怪的病人，有人不断地重复着招手的动作，有人喝的水太多以至于肚子鼓得像气球，有人头顶上一直有乌云跟随，而乌云滴落的沙子让他痛哭不已。\r\n而多萝西见到父母时，他们正在接受治疗：按照医生的说法，他们的██和██神经受到影响，因此经常产生██行为，所以手臂和██上布满新旧交叠的伤痕。听着护士的议论，多萝西终于了解到那些她不曾知道的事情：当多萝西第一次在兔子玩偶的作用下意外进入密室时间后，她便产生了与超凡沟通的能力。最开始父母努力假装一切正常，寻找各种办法来将多萝西的行为合理化——走投无路之下，他们遵循那封信的指引来到那个美丽的游乐园，当父母眼睁睁看着乘坐旋转木马的多萝西身边出现越来越多的“怪物”，他们再也没办法说服自己了：如果多萝西不是“怪物”，那成为“怪物”的一定是他们——\r\n当然，多萝西的父母更宁愿相信后者。\r\n在理智崩溃前，父母拨出了最后一个电话，让寄信人帮他们完成最后的心愿。\r\n\r\n“最后心愿是什么意思？”“那是什么心愿？”绅士和开花先生不理解，疑惑地用自己的语言问多萝西。\r\n“每一年，爸爸妈妈给我的生日贺卡留言都是：所有的美好都会降临在多萝西身上，祝你永远健康，永远快乐。”\r\n在离开之前，多萝西很想去拥抱父母，让他们说完那个没有讲完的睡前故事。她在窗前站了很久，最终还是没有这样做。\r\n\r\n多萝西不打算将这些事情告诉别人。于是，她抬头看着奥罗拉的眼睛，微笑着说：“就算是小孩子，也可以有小秘密哦。”\r\n奥罗拉听了之后没有笑，反而叹了口气，“真残酷啊。”\r\n“嗯？”\r\n“一切意外交织在一起，让世界上又少了一个可以随意撒娇的孩子……这件事本身就很残酷。”奥罗拉怜爱地抚摸着手中枯萎的玫瑰花蕾，仿佛在感叹一件遥远的事情。\r\n\r\n但是多萝西觉得这不算大问题。对她来说，也许一切都没有变化：身边有有趣的朋友，学校里仍然有读不完的书本，父母也依旧在遥远的地方陪伴着她——\r\n只是，她以后再也不喜欢做梦了。"
	},
