	{
		2000041,
		201,
		1,
		"烧烤调料",
		"100041_xiedaiwu_01",
		"混合了黑胡椒、肉桂、辣椒等香料调配成的烧烤调料，气味有点刺鼻。世界上最美味的烧烤，来自精准的火候掌握，和辛德瑞拉的特制调料",
		"没人能将辛德瑞拉与等级分明、秩序森严的白银黎明联想到一起。对于白银黎明来说，辛德瑞拉是一个“例外”——她不需要时刻保持得体的穿着，不需要出席大小会议，也不需要定时汇报行程。即使她的名字赫然列于白银黎明的亲属序列名单上，她本人却不需要为这个头衔负上任何责任。\r\n\r\n这种例外，来自“父亲”的宠爱。当“父亲”不顾路途亲自来到伊利亚特的偏远小镇，发现唯一有血缘关系的女儿是一个只会在农场里乱跑、在稻草堆旁烧烤的假小子时，这位组织的大家长并没有表现特别强烈的厌恶。与之相反，“父亲”不顾弄脏整洁的西装的风险，走进了散发着腥味的农田，谦卑地上前介绍了自己的身份及来意，表示了将辛德瑞拉接回白银黎明总部的意愿。\r\n此时的辛德瑞拉正在跟村里的青年一起享受烧烤晚餐，她从未想过在这个和谐的傍晚会有如此荒唐的事情发生。她假装平静地吃完了手中的两串烤羊肉串，然后拿起放在手边的烧烤调料，向这个自称为自己“父亲”的陌生人脸上狠狠撒了一把。在辛德瑞拉试图用烧烤叉进行下一次攻击时，她及时地被这个不速之客的保镖制止了。\r\n“父亲”的谈判失败了。也许是领略到亲生女的脾性，“父亲”放弃了将辛德瑞拉带回白银黎明的打算。翌日，“父亲”向超凡世界宣布了辛德瑞拉的存在，以白银黎明的名义担保她的一切行为。就这样，辛德瑞拉在非自愿的情况下，成为了亲属序列中最受宠的“次女”。\r\n\r\n总之，这个小镇女孩以反抗获得了自由行动的权力，得以依旧保持自己的“爱好”。例如在河边钓一天的狗鱼，或者在树荫下跟同龄人打上一天的扑克牌，甚至直接坐上不知终点的火车，漫无目的地远行，这些都是她最喜欢做的事。\r\n只有在那种时候，当一些身着西装、戴着白手套的人会为辛德瑞拉送来一堆堆高档牛肉和烧烤调料，用银质的托盘装着滋滋作响的烤肉端到她面前时，她才会真切感知到自己的生活已经发生了变化。\r\n也许，“自由”二字并不代表着自由。"
	},
	{
		2000041,
		202,
		1,
		"宠物貂粮",
		"100041_xiedaiwu_02",
		"开封之后却很久没有食用过的宠物貂粮。汉弗莱阿普比爵士每天会摄入新鲜鱼类，时而还会捕捉一些野兔或麻雀作为自己的营养补充",
		"辛德瑞拉时常怀疑汉弗莱阿普比爵士的身体里住了一个人的灵魂。当行人看到躺在辛德瑞拉肩膀上的貂时，总会出于好意地夸赞一句：“嗨，你的宠物真漂亮！”，而听到“宠物”二字的汉弗莱阿普比爵士会表现得异常愤怒，跳下来追着路人直咬一顿。与辛德瑞拉相熟的邻居尝过苦头，学会毕恭毕敬地称呼它为“爵士”，而这也免不了引来血肉之灾。最后，大家明白了一个定律：汉弗莱阿普比爵士，必须以全名称呼它。一个字也不能少。这是对待动物基本的尊重与礼仪。\r\n\r\n当然，也会有人——通常是辛德瑞拉大胆地直呼它“爵士”，这是他们之间的乐趣。\r\n\r\n这只有点脾气的貂是白银黎明的赠礼。最初，他们送来名贵的白猫，威武的猎犬，还有珍稀的██。辛德瑞拉看着这些被驯化过的动物装在笼子里，温顺得就像橱窗中的商品。所以当装在铁制笼子里的汉弗莱阿普比爵士出现在辛德瑞拉家中时，它的行为是如此地与众不同。尽管这只貂身上的毛发已经乱成结，四爪沾满泥土，它仍然坚持不懈地试图咬开捆在脚上的锁链。这一幕，让辛德瑞拉决心收下了汉弗莱阿普比爵士。\r\n辛德瑞拉并不打算将汉弗莱阿普比爵士收为宠物。任何生物都不应该从属于什么人，她一直是这样想的。因此她将白银黎明送来的宠物貂粮藏在家中最高的柜子里，转而在每个白天和夜里将汉弗莱阿普比爵士带到池塘和野地里，尝试教它捕猎的技巧。长期的驯化让汉弗莱阿普比爵士失去了野性，它没有捕杀一只老鼠的勇气，却敢在深夜爬到最高处的柜子里偷吃貂粮。\r\n最后，辛德瑞拉选择将汉弗莱阿普比爵士留在田野里，紧闭了家中的所有大门。\r\n\r\n第五天清晨，辛德瑞拉发现自己的枕头边多了一条湿漉漉的鱼。而此时的汉弗莱阿普比爵士正乖乖地躺在她的手臂旁，等待着主人醒来。辛德瑞拉将那条鱼熬成一份白汤，这两位新结成的朋友就用这种方法，将他们的友谊纪念品“永久封存”。\r\n\r\n从那之后，那袋宠物貂粮再也没有被偷吃过的迹象。\r\n一直对辛德瑞拉的放肆行为颇有微词的家族成员们怎么也不会想到，当年他们故意将一只蛮横凶狠的宠物交给辛德瑞拉，希望这只宠物能给她带来足够大的麻烦，结果她却因此收获了生命中最真诚的伙伴。\r\n如果要深究汉弗莱阿普比爵士到底是什么，也许“物随主人形”这句谚语就能解释一切了。"
	},
	{
		2000041,
		203,
		1,
		"琥珀挂坠",
		"100041_xiedaiwu_03",
		"小巧但精致的琥珀项链。辛德瑞拉通常不会对装饰品感兴趣，唯独会将这个挂坠放在外套内口袋中",
		"不要翻开石头的背面，这是伊利亚特流行的老话。而辛德瑞拉显然是一块立着的石板，明暗两面的个性都丝毫不加隐藏。最开始，她从不掩饰自己是个有天赋的“学习者”这件事：从少女旅者那里学来治愈的方法，便在大街小巷宣扬自己是起死回生的神医；从马戏团少女处学会了与动物沟通的能力，便指挥苍蝇往讨厌的流氓身上钻。\r\n\r\n与白银黎明的接触，让她真实认识到超凡的存在和自身能力的本质。这位骄傲的少女立志要成为最强，获得征服世界的力量。脑袋里装不下三个单词的辛德瑞拉，居然也学会盘算一套缜密大计。\r\n\r\n行动的第一步，获得强有力的武器。因此，她暴力闯入伊甸之树的圆桌会议现场，对████进行了复写，从此拥有转换形态的能力和坚韧的大剑。\r\n行动的第二步，获得自由行动的身手。因此，她混入水滴的仪式现场，以神不知鬼不觉的方式盗取了███的███能力，因而能够以瞬间移动的方式来往自如。\r\n行动的最后一步失败了。辛德瑞拉堂而皇之地来到天文台的██总部，绕过层层严密的安保系统，击败了前来阻挠的校时者，顺利进入了蜂巢议会的会议厅。在她因为即将接触到███而沾沾自喜时，审判日成员将她抓住。辛德瑞拉在管制室中接受了长达一周的审问和调查，失去的不仅是自由，还有她的骄傲。最后，在████的介入交涉与赔偿后，天文台解除了辛德瑞拉的管制。\r\n要说辛德瑞拉从失败中学会了什么？不，她只是明白了一个道理：当你还没有做好百分百的准备时，不要冲动行事——至少不要让敌人知道你是谁。\r\n\r\n离开天文台的那天，她将获得的两种能力存放在随身携带的琥珀挂坠中，只有必要时才会生效。这串反射着褐色光彩的首饰，是外婆送给她的礼物。轻薄的雾气和锋利的银针分别融进了左右两侧琥珀中，封存了辛德瑞拉的莽撞与张扬。\r\n直到今天，位于挂坠中央的最大一颗琥珀还透明如初。放在阳光下，仿佛能看到它内部的胶质仍在流动，似乎在等待一只蚂蚁或倒霉的蜘蛛，将其吸引过来，随后一口吞尽。"
	},
	{
