		"「父亲」的认可",
		"100041_xiedaiwu_04",
		"父亲赠与的白银黎明家族徽章，是尊贵的次女象征。显而易见的是，辛德瑞拉不喜欢这个东西",
		"辛德瑞拉不喜欢白银黎明的原因有很多，她自己能说出来的有以下三点：一是这个府邸总散发出古旧陈腐的气味，二是辛德瑞拉光是看到这些人系的领带便喘不过气，三是每个跟她打招呼的人，总要虚情假意地在她的名字后加上“小姐”的称谓。\r\n因此她总是与白银黎明对着干，以此获得对自己人生的掌握权。只在对抗超凡这一点上，她与白银黎明达成了共识：辛德瑞拉砍断过一些伪装成竹节虫的电线杆，压制过从地底冒出来的黏糊肉团，甚至还帮助███回收了几只逃逸的管制原体——要说原因，无他，只是辛德瑞拉单纯看不爽那些肮脏又丑陋的物体罢了。\r\n\r\n直到那天，当███入侵了她出生和成长的小镇时，她意识到这个世界上还存在着太多她无法掌握的情况。面对这次突如其来的大规模██降临事件，镇上不明就里的男女老少躲在家中，看着窗外的枝条在疯狂生长，往四面八方不断蔓延，路过之处，植物与生物无一幸免。尽管各大隐秘组织第一时间出动了装备精良的小队，辛德瑞拉也用尽所有方式制止灾难扩散，却无法阻止██生成的红雾覆盖住整个小镇，让所有人都陷入了密室的牢笼中。\r\n天亮的时候，风终于停了，植物也不再蔓延。辛德瑞拉最后从邻居家中救出了一个小女孩，而她的生命体征此时正随着超凡的侵蚀而消退。当她死去时，正好是辛德瑞拉认识她第五年零三个月。\r\n她突然明白：当无形的威胁没有消除时，任何形式的自由都是虚假的。\r\n\r\n因此辛德瑞拉来到了白银黎明。她第一次向大家长提出了要求，希望能够了解更多关于白银黎明、关于超凡世界的信息。\r\n“父亲”没有多问，只是掏出了一枚银制的玫瑰勋章，细心地扣在辛德瑞拉的衣领上，欢迎她回家，并表扬她“终于长大了”。\r\n辛德瑞拉没有接受这次“授勋”。她扯下家族勋章，用力地用小刀在上面划了两道痕。她举着勋章，用严肃的语气对“父亲”说道：\r\n“别自作多情了，我可不是一片破铁可以收买的。”\r\n\r\n辛德瑞拉享受现在的生活。她仍然在满世界乱逛，也依旧喜欢路见不平拔刀相助。只不过，她逐渐不那么排斥对于“次女”这个身份了。在每个月的28号，辛德瑞拉会回到白银黎明，跟家中的姐妹喝点热茶，聊聊最近发生的事。\r\n自由从不取决于身处何处，或是身份为何，而取决于心之所在。而此刻的辛德瑞拉，对自己的内心有着前所未有的坚定与自信。\r\n世界上没有一条法律规定丑小鸭变身之后，就必须穿上华丽的高跟鞋，苦心等待南瓜车把自己载向终点。既然水晶鞋不合脚，就尽管打破它，赤脚奔向属于自己的未来吧。"
	},
	{
		2000043,
		201,
		1,
		"破碎存钱罐",
		"100043_xiedaiwu_01",
		"被摔碎的小猪存钱罐，散落着大大小小的硬币",
		"前不久，这座小城市引来了它最热闹的一天。\r\n来来往往的手握武器的神秘人，不知名的怪兽战争，在漫画书上见到的特效一般的火焰，四分五裂的小屋。这场灾难来得快，居民还没反应换上外出的衣服已经降临，去得也快，两天的时间便将充满烟火气的小城变成一片狼藉的废墟。若有讨水的旅客凭着地图走到沥青公路上定会大吃一惊，哪里有什么童话之城，只有残垣断壁组成的坟墓罢了。\r\n随着最后一辆汽车点燃发动机引擎离去后，小城只剩下瘆人的死寂。“哗啦——，吱——，哐——”的诡异声音从街角残垣中窸窸窣窣钻出来，平时只有流浪猫的垃圾站中竟冒出了一大一小两个头。\r\n“阿呸呸呸呸——好臭！”一个女孩夸张捏着鼻子，眯着眼睛。\r\n“本大爷救了你一条小命，不感恩戴德还嫌臭？”奇怪的嗡嗡声从一个可爱的卷发小男孩身体里传出。\r\n“谢谢你啊，斯耐由。”女孩满心欢喜扑向男孩。\r\n“塞任，本大爷叫塞任！”\r\n“明明差不多嘛……蜗牛（斯耐由）这个名字和你形象更般配呢。”\r\n“差很多！”虽然嘴上骂骂咧咧，但男孩还是贴心伸出了手，把女孩从瓦块中拽出来。\r\n\r\n视野开阔起来，脚下的狼籍也一览无余。这狼藉对女孩来说再熟悉不过，五岁那年女孩见到过一个屋子大小的废墟，此后再也没有见过爸爸和妈妈。板着脸的胖阿姨心疼拥抱着她，开车将她带来这座城市，把她当女儿一样抚养，想必狼藉之后又是无止尽的告别了吧。想到这里，女孩无法自控红了眼眶。\r\n“哭什么？有什么好哭的？你还活着，活着就有希望！”男孩注意到女孩失落的情绪，落回地面叉着手认真说话。\r\n“嗯，好……我不哭。”女孩抹了抹眼睛，懂事憋回自己的眼泪。\r\n\r\n…………\r\n\r\n面包店、甜品店和24小时便利店的工资结算了，雅惬意躺在天台的瓦砾上数着手里的钱。\r\n“蜗牛，你还记得吗，我那个破碎的小猪存钱罐。”\r\n“应该记得的吧，你说你拼死拼活救我出来本以为可以饱餐一顿，结果只有0.83分量子贝！哈哈哈哈哈哈！太好笑了！”\r\n“没办法，小时候没有钱，那已经是我的所有家当了。现在你可以放心，我能让你吃金币吃到饱！”雅爽朗大笑，把金币抛向空中，身旁的乌龟毫不犹豫飞起来吞下肚子里。"
	},
	{
		2000043,
		202,
		1,
		"临期面包",
		"100022_xiedaiwu_02",
		"便利店临期货架上摆置的面包，距离过期还有两天，一般以原价三折出售",
		"男孩和女孩在无人的城市中行走，沿途全是废墟。\r\n雅凭记忆穿过游玩的街道，路过市场，越过学校，最后停留在一块破碎的黄色招牌前。\r\n“阿雅面包屋，没错，这里是我的家！”雅兴奋转身告诉男孩。\r\n“阿雅面包是什么？”男孩疑惑发问\r\n“阿雅是阿姨的名字，也是我的名字，我们名字里都有个雅。”\r\n“那面包呢？”\r\n“面包是个软乎乎的食物，弥漫着大麦的香气，我们家的面包可是这里的一流哦！”提到面包，雅脸上不自觉泛起微笑。\r\n男孩吸了吸鼻子，敏锐的嗅觉识别到了空气里弥漫着陌生的温暖香气。\r\n“给本大爷尝尝这个软乎乎的……面包！”男孩叉着手\r\n“没问题，阿雅面包——马上就到！”雅露出灿烂的笑容，向男孩比了个大拇指。\r\n雅跑进厨房，幸好这里的一切都没有被破坏，冰箱、烤箱都还在可以正常工作。雅取出冰箱里躺着发酵好的面团，熟练在案板上撒上高精面粉，揉搓面团。轻拍，卷起来，再轻拍，再卷起来，最后放到烘焙纸上放入烤箱。\r\n烘焙的香气随着面团的膨胀逐渐从小小的烤箱里弥漫出来，占满整个面包屋，再飘香街道，城市似乎再度活了起来。烤炉温暖的橙色光线驱散了夜幕的寒冷，仿佛间，雅似乎回到了过去每天在面包屋里帮忙的日子。\r\n\r\n“蜗牛，你的面包来啦！”雅带着厚重的手套捧出一盘金灿灿的面包，骄傲递给男孩。男孩也兴致勃勃拎起面包，一口咬下。\r\n“啊——唔！***！烫死本大爷了！”不知道是雅的目光太过炽热还是面包太烫，男孩的脸以肉眼可见的速度红了起来。\r\n又忘记提醒客人了呀，雅不好意思挠了挠头，正如过去每天做错事一般。男孩假装生气背身不理她，朝手上的面包大力吹气，他想认真尝尝这个新玩意的味道。虽然舌头还有些疼，但停留在口腔香甜的麦子味直接转进了男孩的记忆里，这是男孩从未品尝过的温暖味道，如家乡母亲燃点的火炉般温暖。在雅惊愕的目光下，男孩哼哧哼哧吃完了一盘面包，心满意足打起了嗝，雅也跟着傻笑。\r\n\r\n“傻笑什么傻笑，你可是还欠了本大爷很多钱呢！”男孩听到雅的笑声后恶狠狠回头瞪着雅。\r\n“好，好！我会努力打工还钱的！”雅懂事点头。\r\n“还有，本大爷每天都要吃到面包，这是利息，没错，是利息！”男孩一本正经叉着腰，说着不合理的诉求。\r\n“好，好！但是……你不会吃腻吧？”雅小心翼翼发问。\r\n“开哪门子玩笑！本大爷可是吃人肉吃了上千年都没腻，再废话我就把你吃掉！”\r\n……\r\n\r\n广场十二点的钟声响起，雅跑进员工室换下了一身工作服。\r\n“老板，谢谢你今天的照顾！我下班啦！啊……！差点忘记了，还有临期面包吗？”雅元气满满向柜台呼喊。\r\n“当然有，拿走吧，免费。”年轻的老板也总是笑着回应。\r\n“这这这……这怎么行！但看到老板这么坚持，我只能恭敬不如从命啦！谢谢老板的面包！”雅嬉笑着把面包装进双肩包里，挥挥手往家里跑去。"
	},
	{
		2000043,
		203,
		1,
		"双肩包",
		"100022_xiedaiwu_04",
		"些许陈旧的登山包，高密度牛津尼龙布密实耐磨，没有过多的破损。雅的登山包里衣服、洗漱用品、应急物品一应俱全，想必她做好了随时出发的准备",
		"乎苏玛河边围绕着砖红色的小洋楼，车站往右数第二栋的阁楼是雅的新家。房东玛丽是一位善良的单身老妇人，四年前散步遇到相互依偎在公园长椅上的两个孩子心生怜爱，以极低的价格将阁楼租给孩子们。玛丽奶奶厨房传出来的黄油香气，阁楼露台的微风，渔民的欢笑声，船上少年少女的歌唱声构成了乎苏玛的一年四季。\r\n“幸运的孩子有饭吃，幸福的孩子不怕苦，啦啦啦啦啦——”雅哼着不成调歌谣在咖啡店里刷洗着杯子，水龙头蜂拥而出的水流迫不及待回归大海，却被手套的阻挡飞跃到岩板四处溅起水花。换做平日，雅必然会注意到开得过大的水龙头，但今天她感到莫名烦躁。\r\n一定是没睡好吧？雅拍了拍自己的头，把疑神疑鬼的念头全部拍出脑子里。只要换下员工服，提上双肩包，再锁上咖啡店的门，糟糕的一天就会过去了！露台的向日葵开花了吗？蜗牛又在倒头大睡了吗？玛丽奶奶今天准备了热牛奶吗？\r\n“洪水，发洪水了！”街道上闹哄哄的声音打断了雅的思绪，雅放下杯子，走出了咖啡厅。\r\n不知道什么时候开始，乌云笼罩了乎苏玛的天空，飓风掀起了一道又一道波浪，击碎窗户、墙壁、房屋，街道上是哭喊的人群。\r\n“玛丽奶奶……蜗牛！”雅拼了命挤过人群，朝家的方向奔跑。\r\n\r\n天空上的巨大的影子，穿越云层的注视。\r\n雅的步伐越来越僵硬，眼前的一切与记忆开始重合，一片混乱的大脑里乱序放映着坍塌与震荡，尖叫与哭泣，残骸与废墟。她的呼吸逐渐急促了起来，但空气中的氧气似乎被残忍夺走，只剩下混杂与黑暗。\r\n混乱中似乎刮起了龙卷风，又似乎是天空伸出了一只手，雅离开了地面，濒死的窒息感让雅陷入了绝境。似乎出现了一道光，又似乎是一道熟悉的声影出现在了雅的面前，从死神手中将雅夺回地面，开始奔跑，不要命的奔跑，直到陨落。下个瞬间，似乎有道无名火焰钻进了雅的体内，撕碎了雅身体中的每一个细胞，给与了新生的力量。不知道是谁控制了雅疲惫的身躯，让她奇迹般站了起来，一步、一步、又一步背负着沉重的包裹往前走，又不知道是谁在星空中注视着渺小而脆弱的身躯行走、奔跑、倒下、又再次站立起来。\r\n“小朋友，作为乎苏玛坍塌的唯一幸存者，你还记得些什么吗？”一道温和的声音穿透了时间与思绪，把雅从混乱中唤醒。\r\n“洪水……大洪水……蜗牛、蜗牛！”雅挣扎着从雪白色的床上起来，脸色一片苍白。\r\n\r\n……\r\n“120、300、570、600……耶！到现在为止，我已经攒下了76504元了！”雅盘腿坐在床上，兴奋数着存折上的数字。\r\n“再过不久你就能恢复了吧？蜗牛”雅高兴举起身旁的乌龟，乌龟不配合地挣扎，似乎正在控诉雅打断了它的进食。\r\n“虽然每天打三份工的日子有些辛苦，但这让我的生活变得非常充实，也认识了很多很好的朋友。你说，如果有天我不用去打工赚钱了，我们的生活会变成什么样子呢？啊——根本难以想象！”"
	},
	{
		2000043,
		204,
		1,
		"火车票",
		"100022_xiedaiwu_03",
		"由西格纳斯出发，前往尤克特拉希尔的火车票。车程共92小时，沿途停靠12个站台",
		"西格纳斯西边小城市的书店里弥漫着咖啡的香气，只要推开大门，你便能听到铃铛晃动的声音，紧接着便是中气十足的呐喊声。\r\n“欢迎光临！请问您需要找书还是喝一杯咖啡呢？”收银台的雅向你露出了灿烂的微笑。\r\n两年过去了，雅似乎什么也没变。她还是会在早上起晚，然后匆匆奔跑在大街小道。她总是带着灿烂的笑容和店铺一起营业，活力十足。她在回家前总会买两袋临期面包，如果能免费送就更好了。显而易见，两年前的灾难并没有把她摧毁。\r\n但仔细观察，却发现雅的变化也不少。总是跟着她身边的，叫“蜗牛”的男孩不见了，但她似乎养了一只同名的乌龟，邻居说每个晚上都能听到雅和乌龟在说话。她不再长时间停留在一个城市，而是选择将足迹遍布了西格纳斯的每个角落。她最喜欢打工的地方从便利店变成了书店，一旦没有顾客，她就开始埋头看书，似乎变成了一个书呆子。\r\n但可以肯定的是雅依然乐观，她对生活始终抱有一份热爱。\r\n\r\n“今天也很有精神嘛，雅。”推开门的男人开怀大笑，把西装挂在门边的衣帽架上。\r\n“是老板啊，我还以为来客人了呢！”雅一脸遗憾，用可怜的眼神看着门口的男子。\r\n“不去演戏剧真是可惜了，知道你想去看书了，去吧，接下来我来看店就好。”男子围上围裙，对雅挥了挥手。\r\n“老板的要求，我就恭敬不如从命啦！”雅俏皮做了个鬼脸，往书架跑去。\r\n能保持对生活的热爱，也许是因为总能遇到带着善意的人吧，无论是小姨、蜗牛、玛丽奶奶，还是打工的每一个店主。雅总说命运是个混蛋，但生活不是。\r\n\r\n“啊！”书架传来了惊呼，正在做咖啡的店主好奇转身，还没提出疑问雅已经抱着书冲到了身前。\r\n“老板，我找到了，找到了可以治愈蜗牛的方法！我申请离职，谢谢你的照顾！”雅兴奋地展示着手中的书，瞳孔里全是星光。\r\n“蜗牛是你总是提起的那个好朋友吧？你在书里找到了方法？”店主有些意外。\r\n“是的，尤克特拉希尔，希望在尤克特拉希尔！”雅快速点头。\r\n“恭喜你，这太好了。尤克特拉希尔……真是个很远的地方啊。”店主看着雅手里的书，若有所思。\r\n“远点没有关系，只要能治好蜗牛，跑遍整个世界我也愿意！”雅声音里满是喜悦。\r\n\r\n“离职请求通过，不过有个附带的小要求。”老板换了个严肃的声音。\r\n“什……什么？”雅警惕后退了一步。\r\n“带一些店里的面包和食物吧，坐火车去尤克特拉希尔要四天时间，伙能省一点是一点。”店主开怀大笑，拍了拍雅的肩膀。\r\n“啊……谢谢老板的照顾！老板真的太好了，我都快舍不得走了！”雅感动打开玻璃柜门，将八个的面包夹进牛皮纸袋里仔细封好，再带着灿烂的笑容与店主告别。\r\n\r\n雅买好由西格纳斯出发，前往尤可特希拉里的火车票，登上月台。衣服、洗漱品、应急物和存折都在登山包里，蜗牛趴在登山包上，怀里是装着面包的牛皮纸袋，和一本封面古朴的书。\r\n “蜗牛，书里写着尤可特希拉里有一个叫做伊甸之树的神秘组织，他们掌握着世界最前沿的制药技术。组织里的人隐藏在深山中，没有人知道伊甸之树的入口在哪，但最后一次的行踪是在四十五年前，那就说明这个组织还在，对不对，蜗牛？”雅兴致冲冲转头和背包上的乌龟说话，但乌龟只是打了个瞌睡，并没有理睬她。\r\n“呼呼——”汽笛声鸣起，火车缓缓驶入站台。\r\n雅合上手中的书，跳上前往尤可特希拉里的奇迹列车。"
	},
	{
		2000046,
		201,
		1,
		"婴儿摇篮",
		"100046_xiedaiwu_01",
		"北海特种设备制造局研制孤品，电动婴儿摇篮。模拟母亲的臂弯温度及摇晃频率，给婴儿营造最舒适的睡眠环境",
		"希利尔狄瓦娜伯格最北部有一个庞然大物，严肃的棱角，灰白色的城墙，秩序的人群，让本就寒冷的天气似乎又降下几度。这里是北海特种设备制造局，是集研发与制造于一体的真理军工厂。\r\n大雪天，会议室一如既往传来不和谐的争执声，但细听，便能发现这次争执的情绪和以往都不一样。 \r\n“奥列格在战地捡回了个婴儿，要放我们这里养，我们哪有时间养啊？”肚子圆鼓鼓的研究员竖着他的胡子，桌子被他拍得哐哐响。\r\n“维塔利，我没有任何办法。我是干侦查的，侦查！我的朋友里只有你这儿适合养孩子了。再说，那孩子很可爱，也很乖巧，你们会喜欢的。”强壮的军装男子无奈抹掉脸上的口水。\r\n“你以为是小猫小狗，放些食物就够的事情吗？这是婴儿，是人类，是会成长如你我般的生命！养孩子要教育，教育！你知道有多费神吗？”维塔利拍案而起，指着奥列格痛骂。\r\n“是，我知道。所以我没有把她留在原地被冰雪覆盖冷死，我抱回来了。”奥列塔将大列巴茶倒入维塔利的杯中，递了过去。\r\n“……哎，你每次来找我都没安好心，下次别再整什么幺蛾子了，老头我消受不起。”维塔利沉默许久后叹气接过杯子，摆手示意奥列塔离去。\r\n\r\n“导师，我们真的要养孩子啊？”顶着浓厚黑眼圈的研究员跟在维塔利后好奇提问。\r\n“我能怎么办？难不成扔了吗？”维塔利吹着自己胡子，加快脚步走向前台。\r\n不知道什么时候，前台已经聚起了一圈人，一群连女孩子手都没牵过的研究员好奇打量着襁褓中的小小生命，啧啧称奇。\r\n“散开，都散开，孩子的氧气都被你们抢光了！”维塔利大声呵斥，研究员们点头哈腰后一拥而散。\r\n维塔利带着些无奈走到摇篮边上时，孩子有感应版睁开眼睛，圆圆的清澈的眼睛，随后眼睛弯成月牙，她在笑，手舞足蹈地笑。这究竟是一个什么生命体，白白的、柔软的，像阳光般温暖，又像瓷器般易碎，如果世上存在天使的话，那一定是怀中女孩的样子吧。\r\n不知道什么时候维塔利脸上的愁容消失了，他紧皱的眉心被女孩小小的手掌抚平，下弯的嘴角被女孩的笑容拉高。\r\n\r\n“哟哟哟……”黑眼圈研究员看着这和谐的画面，忍不住啧啧称奇。\r\n“咳咳……罗曼，我给你布置一个任务维塔利用咳嗽掩饰自己的尴尬，再次板起自己的脸。\r\n“啥任务？”罗曼瞪大自己的眼睛，企图用浓厚的黑眼圈暗示导师不要再折腾自己。\r\n“这么简陋的摇篮小孩睡着不舒服，做一个电动的，能模拟母亲怀抱的摇篮吧。”维塔利无视徒弟的暗示，下完命令后自顾自抱着孩子走向大门。\r\n雪停了，阳光穿过厚重的云层照在维塔利和女孩身上，久违的暖意让维塔利舒服得眯起了眼睛。"
	},
	{
		2000046,
		202,
		1,
		"儿童成长牛奶",
		"100046_xiedaiwu_02",
		"真理牧场出品儿童成长奶，伊万睡前饮品。健康的土地生产优质奶，儿童成长奶关爱每名儿童健康成长",
		"“重量是物品重力作用在物体上的力，一般用斜着大写的W表示。这样写……伊万，伊万？”罗曼在转身写字的瞬间，女孩如断线木偶般进入了睡眠，只剩他在白板前无奈挠头。\r\n罗曼从没想过，自己有天会站在讲台上教基础物理，也没想到过自己的生活中会出现一个孩子，毕竟这和他进入学术届的初心完全不同。比五年前更暗的黑眼圈证明他从未放弃科研，比五年前更缓和的面容证实他对早上带娃熬夜研究的生活乐此不疲。\r\n只见罗曼把台灯往原处挪了挪，再轻手轻脚走到门边调暗了灯光，在伊万均匀的呼吸声中开始了自己的科研工作。\r\n\r\n“咔——”门被轻轻推开了，只见维塔利悄悄伸了个头出来，再蹑手蹑脚走进这个临时教室。\r\n维塔利精壮许多，比五年前更加年轻也更精神，想必已经没有人能把眼前一脸笑意的大叔和五年前严肃的胖子关联到一起了。\r\n“小伊万又睡着啦？”维塔利和蔼看着睡着的伊万。\r\n“是啊，从打开书本到睡着就用了十分钟吧，导师。”罗曼摇了摇头。\r\n“那看书多枯燥啊，孩子睡着也是正常的。”维塔利交叉着手，用他聪慧的大脑得出了以上结论，“不行啊罗曼，你当老师太糟糕了，我建议你下次带她做一些趣味实验吧，好玩又能长知识那种。”\r\n“……导师，你忘了，上次伊万差点把实验室拆了。”罗曼摇了摇头。\r\n“……一些简单的实验应该还好吧？”维塔利吹了吹胡子，掩饰着忘事儿的尴尬。\r\n“……上次，我带她做的是观察实验。”罗曼用无奈的眼神看向导师。\r\n“啊……啊！我又睡着了吗？抱歉，罗曼妈妈……啊！抱歉，维塔利爷爷也来啦。”伊万在梦中突然惊醒，看着眼前的场景想起了自己正在上课。\r\n“没事，是罗曼教的不好，下次我让他教你一些好玩的。”维塔利抱起伊万转了个圈，把伊万逗得咯咯直笑，“走吧，我们出去玩吧。”\r\n\r\n“出去玩吗？那维塔利爷爷，请等一下。”伊万落地后迈着小腿跑向了罗曼。\r\n“对不起，罗曼妈妈，我以后一定不会再打瞌睡了。伊万会努力学习物理学，成为一个好孩子的。”伊万认真看着罗曼，眼神里全是坚毅。\r\n“那我就当真了，下次再打瞌睡我就把你揪起来。”罗曼笑着摸了摸伊万的头。\r\n“让我站着上课也是没问题的，罗曼妈妈。”伊万将小手握成拳头，展示自己的决心。\r\n“知道了，知道了……不对，你又喊妈妈？说了好多次，妈妈是对女性的称呼，我是男性，你应该叫称呼我先生、老师，爸爸……爸爸好像也行。”罗曼嘟嘟喃喃。\r\n“好的罗曼妈妈，那我就跟维塔利爷爷出去玩啦！”伊万挥着小手和罗曼告别，匆匆跑到了维塔利的身边。\r\n\r\n“小伊万要去哪里呀？”维塔利牵着伊万的小手走在雪地上。\r\n“要去买成长牛奶，再不去超市就要关门啦！”伊万指着前面的超市，十分开心。\r\n“我们家小伊万真爱喝牛奶，真棒。”维塔利比了个大拇指。\r\n“因为电视里都说，喝成长牛奶，就可以快快长大呀！”伊万举起双手，模仿广告里的姿势。\r\n“长大后小伊万想做什么呢？想当宇宙员，还是当侦探？”\r\n“唔——都不想，伊万只想留在实验室，想成为无所不能的大人！”\r\n“这么希望长大吗？长大会有很多烦恼哦。”\r\n“伊万不怕，因为长大后就可以帮上妈妈们的忙啦！”"
	},
	{
		2000046,
		203,
		1,
		"小浣熊定位器",
		"100046_xiedaiwu_03",
		"北海特种设备制造局研制孤品，小浣熊定位器。超长待机、精准定位、远程对话，小浣熊定位器能在所有复杂环境中确保佩戴者的平安",
		"“小伊万，爷爷来啦。”维塔利抱着机场买的巧克力，敲着伊万的门。\r\n咚咚，咚咚，没有回应，“是睡着了吗？”维塔利摸着自己的胡子，思索半分钟后把巧克力挂在门把手后离开了。\r\n\r\n今天有些过于安静，大家都觉得似乎少了些什么，整个实验室都好像少了些什么，气氛凝重又压抑。\r\n“导师，小伊万呢？”经过数小时的沉默后，罗曼忍不住开了口。\r\n“我中午去的时候似乎在睡觉，现在应该醒来了吧？”维塔利纳闷吹了吹胡子。\r\n“可是房间里没有人啊……”罗曼扶了扶眼镜。\r\n“什么？！”维塔利猛拍了一下桌子，把研究员们吓了一跳。\r\n“房间里没有人，门口倒是有一盒巧克力……”罗曼挠了挠头。\r\n“监控，去查监控！”维塔利打断罗曼的言语快步离去，实验室陷入了混乱。\r\n\r\n根据监控来看，小伊万是在早上九点离开房间，随后在食堂吃了两杯牛奶，两个鸡蛋，一些面包和一些水果，食量如常。九点半后离开食堂，在实验室转了一圈后走进制造间再转了一圈，帮忙搬运了一箱武器，无意破坏了两台机器……行动如常。十点半，走出制造局，和门卫挥手道别后蹦蹦跳跳消失在小径上，情绪如常。\r\n“问题出现在小伊万独自外出只会去超市买牛奶，买牛奶用了七个小时……她不会是被人贩子抓走了吧？”带着墨镜的研究员说出了自己的推理。\r\n“警报，设备局启动三级警报！所有人拿起自己的武器，武装车间集合！”维塔利毫不犹豫按下通讯机，红色警铃在制造局逐个亮起。\r\n“伊万，你千万不能有事啊……”罗曼扛起突击炮，迈着沉重的步伐走向车间。\r\n“集合完毕，代号：千刀万剐人贩子，拯救伊万行动，启动！”阀门缓缓开启，一辆又一辆铁皮车蜂拥而出，维塔利失神站在门口，听着武装车队在狄瓦娜伯格冰冷的雪地上发出悲鸣。\r\n\r\n“哇——好热闹啊，维塔利爷爷，今天是有什么活动吗？”不知道什么时候出现的小伊万抓着维塔利的衣角，瞪大了好奇的眼睛。\r\n“小伊万不见了……伊万！小伊万！”维塔利回过神来，发现伊万正在用疑惑的眼神看着自己。\r\n“糟糕……行动结束，行动结束！伊万回来了！行动结束！所有车掉头回来！”维塔利按下通讯机，中气十足的喊声响彻制造局。\r\n\r\n伊万确实有不如常的地方，比如说绑的辫子变得乱乱的，再比如说脸上和衣服都灰扑扑的，像一只小脏猫，但她亮闪闪的大眼睛表明了她的心情非常好。\r\n听伊万说，她并不是淘气出去玩了，而是真的遇到坏人了。坏人骗她说她的家里人正在找她，于是她懵懵懂懂跟着上了一辆面包车，直到车朝着制造局的反方向越开越远，伊万才意识到不对劲。虽然车里的两个人对她无法构成任何威胁，但动画片里都说坏人有一个老巢，里面是各种被拐回来的孩子，伊万简单思索了一会儿，决定要去救下这些可怜的孩子。\r\n坏人的老巢里果然有两个孩子，他们都是来自狄瓦娜伯格小镇的，为了不惊动坏人，伊万空手砸穿了工厂的墙，扛起两个小孩往外跑。不料行动还是被坏人发现了，伊万只能硬着头皮把两个坏人都打趴下，再带着两个小孩从郊外走了回来。如此一来一回，大半天就过去了。\r\n\r\n“对不起，维塔利爷爷，对不起，妈妈们，伊万让大家担心了。”伊万对众人深深鞠了个躬，表达自己的歉意。\r\n“没事的，能够安全回来真是太好了，可怜的小伊万受到惊吓了吧。”维塔利泪流满面抱着伊万，心疼无比。周围的研究员们也忍不住传出了阵阵啜泣声，他们差一些就失去了制造局的至宝。\r\n“导师，我先走了，我要给伊万做个卫星定位器。”罗曼扶了扶眼镜，反光的镜片遮盖了他复杂的悲痛情绪。\r\n“去吧，把警报系统也做进去。”维塔利挥了挥手。"
	},
	{
