		"自动驾驶卡车",
		"100046_xiedaiwu_04",
		"北海特种设备制造局运输部专车，采用现代通信手段，实现车地间双向数据实时传输，精准、安全、可靠自动化驾驶者的工作。驾驶者……只用负责搬运就行了！",
		"凌晨一点，伊万抱着小浣熊玩偶从梦中惊醒，她梦到有怪物闯进制造局，将一切弄得一塌糊涂。幸好只是在做梦，她揉了揉眼睛看向窗外。月光安静挂在天空，实验楼……实验楼的灯光怎么是亮的呢？\r\n不太对劲，实验楼的灯不应该是亮的，不会是有怪物入侵吧？伊万思索片刻后，果断套上厚厚的羽绒外套，走向实验楼。\r\n\r\n“导师，您保重。”罗曼的声音有点闷闷的。\r\n“我早就告诉过奥列格，这把年纪别跑前线了，他不听，早晚会有这么一天的。”维塔利的声音无比沉重。\r\n“他是伟大的真理战士。”罗曼有些许犹豫。\r\n“狗屁战士，他是就个*脏话**脏话**脏话*。”维塔利破口大骂。\r\n伊万静静在门口听着，没有推开实验室的门。她听到了一些低沉的啜泣声，罗曼妈妈说男人的悲伤是不希望被别人看到的，于是她只能站在寒冷的走廊里，隔着窗户默默担心。\r\n\r\n“导师，伤亡数量越来越多了，密室里的怪物……进化了。”\r\n“留给我们的时间不多了，我们要尽快取得突破。”\r\n怪物……战士……牺牲……伊万复述着听到的生词，不知不觉间语气也倍感沉重。她从对话中拼凑出有糟糕的事情在伊万看不见的地方发生，一次又一次，就像电视剧里的怪物入侵一样。\r\n难道做的梦也会变成现实吗，伊万吓了一个激灵。不会的，不会的……她自言自语，在恍惚中回到了自己的房间。\r\n\r\n伊万失眠了，这是她第一次在床上翻来覆去，努力抱着小浣熊闭上眼睛却睡不着觉。明明房间里的暖气很充足，她却觉得异常寒冷，北风好像穿过了狄瓦娜伯格山脉全数灌入了制造局，否则今晚怎么会如此冰冷呢？\r\n为什么每天都在喝牛奶，却成长得这么慢？\r\n为什么这么努力学习，却到现在都没有办法看懂妈妈们的实验呢？\r\n到底怎么才能够帮上忙呢？怎么样才能和大家一起分担沉重的压力呢？\r\n伊万左思右想，小脑袋却转不出一个结论。\r\n\r\n睡不着，没办法睡着。伊万钻出被子，抱着小浣熊呆呆看向窗外。实验楼的灯不知道什么时候关上了，外面黑黑的，只有月光和货车微弱的灯光。\r\n货车……货车！伊万瞪大了眼睛，困扰了她一晚上的问题似乎有答案。虽然没有很聪明，但我有着很大很大的力气，能去车间搬运东西！她眼睛亮了起来，笑容重新回到了她的脸上。\r\n“小浣熊，我想到能帮上妈妈们忙的方法啦！我要去当搬运工，力大无穷的搬运工！我好聪明呀，像维塔利爷爷说的一样，伊万是世界上最聪明的孩子！小浣熊，你说对不对？”伊万在月光的照耀下抱着小浣熊高兴得转了一圈又一圈。"
	},
	{
		2000047,
		201,
		1,
		"干花束",
		"100047_xiedaiwu_01",
		"久置花瓶中的干花束，不知道被放置了多久。也许只需要轻轻一揉，花瓣便会化成粉末",
		"16岁。\r\n白色窗帘、白色天花板、白色床单，空气中刺鼻的次氯酸钠气味让床上的少女眉头紧皱，走廊里奔走的脚步声把少女从沉寂的梦中唤醒。\r\n少女睁开双眼，太阳穴刺痛，大脑一片空白。记忆的高楼仿佛经历了无数次爆破，轰然倒塌，最后被移成平地。但少女没有任何慌乱与不知所措，她抬了抬手指，接着握拳，紧接着试探性伸了一下手臂，确认肢体功能无碍后握着扶手让自己坐了起来。\r\n身上穿的是薄长衫，屋内没有暖气，气温微凉，应该是初秋。适应身体用了五分钟，肌肉有些变化，应该昏迷了接近七天。记忆……想不起来任何东西，但潜意识并没有任何负面情绪，应该不是件坏事。\r\n“咚、咚”，少女右侧传来了规律的敲门声，还未等少女回应，便传来了扭动把手的声音。少女缓慢扭头，看见一个顶着绅士礼帽、带着面具的怪人捧着一束鲜花走进病房。虽然看不清他的长相，但少女从他愣了一下的脚步中读出了吃惊。\r\n“你醒来了，比预期早了两天。”绅士礼帽在片刻沉默后用这句话作为开场白。\r\n少女点了点头。\r\n“对了，你刚清掉记忆，需要一定的适应时间。”绅士礼帽犹豫片刻后恍然大悟。\r\n少女摇了摇头，伸出手指了指床边柜的水杯。\r\n绅士礼帽拿起水壶笨拙试探，却无法扭开盖子，少女见状也伸出手臂加入队伍，奋战片刻后终于将水壶扭开。\r\n“呼……”少女喝下了一杯又一杯的水，没有什么能比干燥的喉咙被水滋润更令人感到满足。\r\n绅士礼帽低头笑了两声，将手中的鲜花插入病房内的花瓶。\r\n“失去了记忆，你有疑惑吗？我还有五分钟的时间可以给你解答。”绅士礼帽看了看墙上的钟表。\r\n“这束花是送给我的吗？”少女抬起头直视他的眼睛。\r\n“是的。”绅士礼帽把花瓶放到了床边柜上。\r\n“谢谢你，我没有疑问了。”少女伸手从花瓶中取出一支蓝雪花。\r\n少女把蓝雪花放到鼻尖，让植物的清香冲散次氯酸钠环绕在鼻腔的气味，大脑也逐渐运转过来。\r\n“不想知道你的过去吗？”等待片刻后，绅士礼帽发问。\r\n“没有必要，过去已经过去了。”少女答。\r\n“名字也不需要吗？”\r\n少女放下蓝雪花转身下床，拉开惨白的窗帘，看向窗外，似乎在思索又似在放空。绅士礼帽也跟随走到窗边，耐心等待着她的回复。\r\n“没有名字是件麻烦事，请给我一个名字吧。”许久后，少女回答。\r\n“池塘里有天鹅，你的名字就叫奥杰塔吧。”绅士礼帽回答。\r\n“白天鹅奥杰塔……不换成奥吉莉亚吗？”听到这个名字后，少女不禁笑了出来。她不知道自己为何而笑，只是看着池塘里无忧无虑的天鹅，她的心里有些难受。\r\n“你的优雅和清高铭刻在骨子里，无需自嘲。从今以后，你的名字就叫奥杰塔吧。”绅士礼帽的回答不容置疑。"
	},
	{
		2000047,
		202,
		1,
		"天鹅绒高跟鞋",
		"100047_xiedaiwu_03",
		"贵气的天鹅绒细跟高跟鞋，佐以碎砖点缀扣环，简约不失大气。盛装出席晚宴的女人不能没有高跟鞋，高跟鞋不知何时变成了奥杰塔身体的一部分",
		"17岁。\r\n古典装饰的宴会厅散发着恬静的雪松味，短绒地毯上放置着数十个独立的小隔间。宴会厅舞台上挂着酒红色的绒面幕帘，昏暗的聚光灯下放置着胡桃木打造的方桌。\r\n奥杰塔跟随一个顶着绅士礼帽、带着面具的怪人走进宴会厅，这个怪人和曾经医院里的出现的绅士礼帽不太一样，背部没有这么挺拔，行走迈出的步伐也有明显差异。\r\n“到了，你的工作场合。”面具停留在舞台下方。\r\n“我的工作不是管家吗？”奥杰塔有些疑问。\r\n“管家是你的身份，这里才是你的舞台。”面具伸手指向方桌。\r\n虽然失去了所有的记忆，但在看到聚光灯下法槌的瞬间，奥杰塔心底涌出了复杂的情绪，激动、热血、骄傲、不甘、怨恨。奥杰塔不动声色把所有情绪揉成一团，压入意识海中，再抬头重新打量起宴会厅。\r\n“这里是拍卖厅。”奥杰塔用陈述句发问。\r\n“没错，你曾经是个拍卖官，杰出的拍卖官。”面具点头道。\r\n奥杰塔的意识海再次涌起了波澜，海底似乎有着什么生物正准备跳跃而出，她咬了咬牙，再次抚平情绪的波澜，跟着面具走上了舞台。\r\n“你的记忆被删除了，可能会受到一些影响。我们决定你的工作从下个月开始进行，这个月，你可以先坐在拍卖台下观察。”面具指了指后排的隔间。\r\n“不用。”奥杰塔有些突兀拒绝了面具的好意。\r\n“这是刻入基因的本能，只要站到拍卖台前，我就能制造让你满意的结果。”意识到失态后奥杰塔补充道。\r\n面具沉默片刻后，发出了爽朗的笑声。\r\n“我欣赏你的自信，今晚有个拍卖会就交给你主持吧，拍卖品和图录我让人在下午四点送到你的卧室，我很期待你的表现。”面具转身与奥杰塔对视。\r\n“我会证明自己的。”奥杰塔俯身鞠躬。\r\n“对了，如果有什么需要的可以联系油画，他们会为你准备的。”面具伸出右手，示意奥杰塔起身。\r\n“明白，但现在时间紧迫，外出购置必需品也许会比较合适。”奥杰塔看了看腕表，距离下午四点还有三个小时四十分。\r\n“缺什么可以直接提。”面具的笑声戛然停止。\r\n“缺一双合脚的晚宴鞋。”奥杰塔不动声色承受着令人窒息的威圧感。\r\n面具愕然片刻后，再次发出一连串大笑，低气压氛围随之烟消云散。\r\n“购物是工作的动力，是这样理解吗？”面具笑得前仰后合。\r\n“不，高跟鞋是拍卖擂台上的武器。”奥杰塔悄悄松了一口气，再次行了一个无可挑剔的礼。\r\n“去吧，不要错过时间。”面具摆手道。"
	},
	{
		2000047,
		203,
		1,
		"锋利的匕首",
		"100047_xiedaiwu_04",
		"不知名材质打造的匕首，轻巧便携，刀刃锋利。白银黎明有传闻匕首是“父亲”赐予的珍藏品，在危急关头可以发挥独特作用",
		"23岁。\r\n猫的叫声把奥杰塔从睡梦中唤醒，奥杰塔不情不愿离开舒适的被窝，从衣帽架上取下晨袍，边盘着头发边走进浴室。\r\n这是奥杰塔进入白银黎明的第五年，她早已习惯突然降临的指示。已经购置了三年的家和刚装修没有什么差异，厨房没有一丝油烟。放置玄关登机箱中整整齐齐放置着衣物和化妆品，证件和通讯装置则装在挂在门后的单肩包中。\r\n洗漱结束后奥杰塔换上便服走出阳台，只见一只带着领结的黑猫优雅盘在躺椅上。\r\n“抱歉，久等了。”奥杰塔轻微弯腰，向黑猫行了一个致歉礼。\r\n“喵，喵喵。”黑猫摇头示意没关系。\r\n“喵喵喵，喵喵。”黑猫说请在下午三点回“家”，父亲有事情要宣布。\r\n“是。”奥杰塔点头示意信息已经收到，黑猫慵懒伸了个懒腰后跃出阳台，在花园中消失不见。\r\n\r\n两点半，奥杰塔撑开太阳伞迈步下车，管家贴心为她关上了车门。许久没有回“家”，奥杰塔有一丝忐忑，但“家”里的孩子们如常在花园里中嬉闹，动物们匍匐在树荫下歇息，一切如常。与孩子们亲切打过招呼后，奥杰塔深吸一口气后，走进了“家”。\r\n“奥杰塔，你还是一如既往的准时。”浑厚的声音从原处传来，奥杰塔闭上眼睛跟随声音推开了书房的门。\r\n书房的窗帘被完全拉上，把光线全部隔绝。昏暗中只能辨识出满壁书架、书桌、台灯和背着书桌摆放的油蜡皮沙发。奥杰塔朝声音方向毕恭毕敬行了个礼，等待着下一步旨意。\r\n“不必多礼，起来吧奥杰塔，可以睁开眼睛了。”和蔼的声音从沙发处传来。\r\n“好的，父亲。”奥杰塔优雅起身，却依然垂着眼眸。\r\n“奥杰塔，这五年，你为白银付出了不少的贡献。管家的职责，你履行得很好。”沙发后传出了鼓掌的声音。\r\n“奥杰塔不辱使命。”奥杰塔低言。\r\n“基于你优秀的表现，我将魔女夜宴的主导权托付给你，以后你在魔女夜宴会有一席话语权。”\r\n“谢谢父亲，这是我的荣幸。”奥杰塔再次行礼。\r\n“我很期待你未来的表现，就如当初在拍卖厅时一样。”沙发后的声音中似乎夹杂了一丝怀念，奥杰塔相信这只是她的错觉。\r\n“起来吧孩子，我还为你准备了一份礼物。不必再行礼了，拆开看看吧。”\r\n奥杰塔伸出手，从虚空中接过刻有古朴纹路的木质盒子。翻开木质盒子，指间能触摸到顺滑的天鹅绒布，再掀开绒布，一把匕首安静躺在盒子中。\r\n“这是我珍藏的匕首，它很适合你。” \r\n“谢谢父亲……”书房开门的声音突兀打断了奥杰塔的致谢。\r\n奥杰塔转身，再闭上双眼，一步接一步凭记忆走出书房，离开“家”。\r\n“迫不得己，不要将刀尖对着自己。”奥杰塔身后传来了温和的声音。"
	},
