		"寂静之音邀请函",
		"100047_xiedaiwu_02",
		"超凡者们梦寐以求的邀请函，散发着淡淡的冷杉香气。封面是花体英文写的Witches' Feast——魔女夜宴",
		"28岁。\r\n西伯利亚东部的海岸边停着一座豪华的巨轮，带着面具的奇怪客人从五湖四海赶到此，凭借圆形的邀请函登上甲板。\r\n船锚缓缓升起，客人陆续落座，呜呜的鸣笛声是晚宴开启的讯号。水晶灯一盏一盏熄灭，只剩幽暗的灯条提供光明。\r\n哒、哒、哒、哒……高跟鞋踩在木地板上的声音在视觉被半剥夺后尤为瞩目。\r\n碎钻点缀的高跟鞋如星空版闪闪发亮，端面晚礼服勾勒出性感的曲线，酒红色长卷发优雅盘在后脑勺，装饰着黑羽毛的金色面具为主人添加了不少神秘色彩。\r\n奥杰塔在众人目光的迎接中不紧不慢走向拍卖台，止步的瞬间，聚光灯只为她而绽放。\r\n“尊贵的客人们，欢迎来到寂静之音。我知道有客人远赴而来，有客人放下了忙碌的事务，谢谢各位客人一直以来的支持，请接收寂静之音由衷的感谢。”奥杰塔向台下观众附身行礼。\r\n“本场拍卖会，我以奥杰塔之名保证绝不会让各位失望。”奥杰塔优雅转身的刹那，宴会厅再次陷入了黑暗。\r\n窸窸窣窣的声音透过木地板传到每位客人的心中，首位登场的原体唤起了他们心底的好奇。\r\n灯光再起，被羽扇掀开的幕布也应声落地，只见舞台中央出现了一个硕大的玻璃柜，玻璃柜中放置了一个晶莹剔透的天使雕像。垂着翅膀的少女跪坐在高台上双手合十放置在胸口，侧头看向台下双唇微张，似乎是在祈祷，又似乎是在悲伤。前排客人似乎看到有泪珠从天使眼角落滑，但又似乎是光照产生的错觉。\r\n“红雾地区诞生的原体，琉璃之光。天使用歌声与眼泪献上祝福，能治愈物主内心的伤痕，为物主唤来心中所念之人。”\r\n奥杰塔走到雕像前动情演说，声音似乎也随着天使的落泪变得逐渐空灵。来宾屏息看着玻璃柜中的原体，眼底涌出贪婪的欲望。\r\n“起拍价，五百万量子贝！”奥杰塔抬高了音调，宣布竞价环节的开始。\r\n“加十，加三十，加五十，好，现在是五百九十万。”\r\n“加一百，九号先生加一百！五十，三号女士再加五十！看来竞争有些激烈呀。”\r\n“两百！九号先生再加两百，现在价格是一千三百万，我们提前祝贺九号先生……”\r\n“五十！两百！五十！三十，啊，十一号女士看来也心仪此物。”\r\n“五十！九号先生，您要再加点吗？再加五十？当然没问题，那现在是到两千三百万了。”\r\n“两千三百万一次，两千三百万两次，三次。落锤，成交！”\r\n“两千三的心愿，我相信一定物有所值。”\r\n…………\r\n\r\n西伯利亚东南部，巨轮缓缓靠岸，摇弋海面上响起的鸣笛声宣告寂静之音的结束。\r\n带着面具的游客陆续走下巨轮，有人步伐轻快，想必今夜有良好的收获，也有人垂头丧气，或许离心仪之物只隔寸步。\r\n奥杰塔靠着落地窗看着游客若有所思，一旁的女孩看着账单早已乐开了花。\r\n“奥杰塔大人，今晚又赚大发啦！您是不是偷偷动用了一些能力？嘿嘿。”女孩挑眉凑向奥杰塔，引得奥杰塔失笑。\r\n“你啊你，尽想些有的没的。”奥杰塔用食指点了点女孩的鼻尖。\r\n“那你教教我嘛，奥杰塔大人，我也想当一个优秀的拍卖官。”女孩撒娇摇着奥杰塔的手臂。\r\n“拍卖师可不能借助外力，你要学会利用的，是人心。”奥杰塔轻言。"
	},
	{
		2000051,
		201,
		1,
		"红围巾",
		"100051_xiedaiwu_01",
		"一条来自往昔的围巾，仿佛落日般鲜红夺目——关于这条围巾的人和事，也统统散发着余晖似的温暖",
		"阳光灿烂的冬日午后，姑娘们在公园草地上快活地奔跑。\r\n鲜红夺目的围巾衬托着她们青春洋溢的面庞，那是最年长的奥丽加亲手织就的。柔软的羊毛，细密的针脚，每一条内侧都绣上了她们几人的名字，奥丽加，尤利娅，安杰莉卡，卡琳娜，连在一起就像一串悦动的美丽音符。\r\n“安杰莉卡，你跑太快了，咱们都要追不上你了！”\r\n“明明是你们太慢了！哎呀，多好的阳光啊，草皮都被晒得暖烘烘香喷喷的……“\r\n“肯定是老天知道我们今天要出来拍照，特意出了太阳吧！”\r\n“怎么还是一脸严肃呀，卡琳娜，难得有这么好的太阳！”个子娇小的尤利娅像只兔子那样蹦到卡琳娜面前，用带了马海毛手套的手掌轻轻搓了搓朋友的脸颊。\r\n望着对方可爱的笑脸，卡琳娜的神情也不禁变得柔和起来。\r\n\r\n她出生在普通的希利尔钢铁工人家庭，她的父母没有熔炉般的热情，都是铁一般又冷又硬的脾性，他们几乎不用言语和笑容表达爱意，充满欢声笑语的家庭对他们的女儿来说，仅仅出现在画报和电视里。\r\n在这样压抑的氛围里，卡琳娜度过了童年，长成了一个孤僻寡言的“古怪姑娘”，和他的父母仿佛是同个模子里刻出来的，从不主动和人打交道，不爱笑，即使想要向谁表达温柔，也会选择先将它严严实实地包裹在一层石头般的壳里，再状似漫不经心地抛向对方。\r\n自己会孤身一人走下去。卡琳娜一直如此相信，不管自己是否打心眼里习惯了孤独，这都将是她的命运……直到有一天午休时分，奥丽加她们带着友善的笑容，来到她的身边。\r\n她从没想过，有一天竟然能够拥有这样一群朋友，既能够像现在这样和她们说说笑笑，嬉戏打闹，脸挨着脸地坐在太阳底下，也能够肩并着肩一同战斗，把信任交托给彼此。\r\n“对对对，就是这个表情，抓拍到了非常自然的笑容，简直漂亮极啦！”咔嚓一声轻响，把卡琳娜的思绪拉了回来，只见安杰莉卡正乐呵呵地望着她。\r\n“你刚才在想什么，到底是什么事儿让你露出这样的表情？”尤利娅和奥丽加也都好奇地望向嘴角噙着微笑的卡琳娜，她极少这般笑，笑容让姑娘们想起了花圃中盛放的铃兰花。\r\n卡琳娜轻轻掖了掖围巾，凝睇着伙伴们在太阳底下闪闪发亮的瞳仁和秀发。\r\n“肯定是因为，今天的阳光实在太好了。”她说。"
	},
	{
		2000051,
		202,
		1,
		"卫士身份牌",
		"100051_xiedaiwu_02",
		"代表真理卫士身份的金属牌，上面的字早已经被过于浓郁的红雾腐蚀，但那一串名字已经深深镌刻在卡琳娜心里",
		"接到命令后，小队第一时间赶到了现场。\r\n这是一处位于红雾区边缘的塌陷带，为了防止超凡吞噬更广的土地，真理派出了白桦小队，人们相信这支曾出色完成过无数次任务的队伍，这次同样能顺利归来。\r\n然而情况比想象得严重许多，连惯常面带笑容的奥丽加队长，也不由抿紧了嘴唇。\r\n“但是，总有人要去做。”卡琳娜听见她轻声说。虽然大伙认为卡琳娜是小队中最勇敢的卫士，沉稳坚硬得宛如磐石，但在卡琳娜心中，奥丽加才是最勇敢的那一个，她是一泓不会轻易被吹皱的湖面，总能以柔和平静的态度去面对风暴，卡琳娜从她身上汲取了许多力量。\r\n\r\n她们走进了红雾，随之而来的是一场接一场的硬仗——原体源源不断地从四面八方袭来，每一秒都必须集中全部精力应对，而眼前的红雾本身就是一种可怖的威胁，这比往常还要更加浓郁的雾气在恣肆流淌、扩散，淤泥般黏稠地附着在皮肤上，卡琳娜感觉仿佛在被这淤泥淹没，渐渐窒息脱力，就连抬一下手都得费上半天工夫。\r\n大伙的情况同样不容观，尤其是年纪最小的安杰莉卡，像风箱一样喘着粗气。\r\n但她们知道，自己不能畏缩，否则，否则，卡琳娜想起今天早晨出城时看见的景象，今天是休息日，波光粼粼的人工湖畔，人们正在沐浴着朝阳，享受他们的闲暇。她们怎么能让这红雾污染灿烂的天光，怎么能让这红雾扰乱这平和的景象。\r\n卡琳娜咬着牙，用早已麻木的手指，扣动着扳机，直至最后一个敌人倒下……她不知自己是何时失去意识的，也不知那之后过了多久。当她再度苏醒时，周围死一般地寂静，卡琳娜第一次品尝到恐惧的滋味。\r\n“奥丽加，尤利娅，安杰莉卡！”她急切地呼唤着队友的名字。\r\n“卡……琳娜……卡琳娜……”有人回应了她。听起来有些像奥丽加队长，但却夹杂着一阵阵可怖的、令人不安的气音。简直不像人类发出来的声音。卡琳娜被自己的想法吓了一跳。\r\n她循着声音发出的方向，小心摸索着。\r\n手电筒微弱的光中浮现出数个漆黑的人形……身为真理卫士，卡琳娜遇到过许多失控的超凡者，也处决过许多。失控者或许还活着，但身体和意识都在不断腐烂，她亲眼见过身为父亲的失控者杀死自己的妻儿，也见过身为长官的失控者杀死自己的下属，他们失去了作为人类的尊严与骄傲，化为仅凭着胸中不断膨胀的破坏本能而行动的怪物……\r\n而现在，她的战友们，奥丽加，尤利娅，安洁莉卡也成为了这样的“怪物”。\r\n“处决我们吧，卡琳娜……”只有奥丽加队长似乎还残存着一丝作为人类的意识，她一面勉力阻挡着另外两名队友，一面再度呼唤卡琳娜，语气里带着恳求，“尤利娅和安洁莉卡……已经失控了……而我也马上要……趁现在处决我们，保住我们属于人类的尊严吧！”\r\n\r\n卡琳娜颤抖着举起武器，对着她的战友，她最亲密的伙伴。\r\n紧咬嘴唇，直到舌尖品尝到一丝甜腥。卡琳娜已经不记得当时自己到底在想什么了，又或者什么都没有想，什么都不愿意再想，伴随着一阵痛苦的呼喊，她朝她们射出了子弹——\r\n在此之后，她又是孤身一人了。"
	},
	{
		2000051,
		203,
		1,
		"《真理诗集》",
		"100051_xiedaiwu_03",
		"一本厚厚的诗集，记录了卫士们在战场上写下的诗句，边角有些微微毛了，显然是有人时常翻阅",
		"阳光灿烂的冬日午后，卡琳娜独自倚着病房的窗牖发呆。\r\n似乎在很多年以前，也曾有过这样好的阳光，那到底是什么时候呢？她的呼吸变得急促起来，被红雾侵蚀的身体也不由隐隐作痛。\r\n“卡琳娜卫士，您还好吗？”\r\n“没事，能帮我拿本书来吗？”\r\n卡琳娜一言不发地翻阅护士拿给她的书，在疗养院里，这是她除了治疗外最常做的事。\r\n在卫士们为她的名字齐声欢呼，感谢和歌颂白桦小队的英雄事迹时，卡琳娜的内心正受着无法诉说的煎熬。她明白，人们的热情确确实实出于最为质朴的情愫，她亦被这份情愫所触动，但她没法安然地享受围绕在身畔的掌声与鲜花。\r\n奥丽加的母亲——这位端庄温和的女性同样是一名守秘人——也曾来看望过卡琳娜，久久地坐在少女的病床前，安慰女儿般轻抚她的肩膀，微笑着说了许多贴心的话，就连亲生母亲也从未这样待过她。可对方眼下的青黑暴露出其内心的悲伤，这悲伤深深刺痛了卡琳娜，她没法心安理得地接受这份体贴。\r\n身边的人们都体谅她，身边的人们都原宥她，可少女无法宽恕自己，安然享受荣誉，也无法安然接受安慰……在亲手夺去伙伴的生命，幸存下来后。\r\n况且在经历了得到与失去的落差，她已不再是过去那个可以保持冷漠，孤身走进黑暗中的卡琳娜了，她正在如作家们说的那样，用阅读构建属于她的避难所，倘使不试着把心灵托付给铅字和纸张，她大概会逐渐溺毙于那充斥着红雾的深海里。\r\n今天读的是一本诗集。书里的诗句都是真理的卫士们写下的，大多没什么特别华丽的辞藻，也没什么特别深刻的哲理，但它们是真挚而鲜活的，透过诗句甚至能触到体温与脉搏。\r\n当翻到第112页时，卡琳娜的手指顿住了，她愣怔地盯着印在这一页上的诗行——\r\n《某个冬日午后，和伙伴们》，署名是奥丽加·尼古拉耶娃。\r\n卡琳娜用颤抖的手指，细细抚摸着那行熟悉的名字。她知道这位挚友一直把写诗当成爱好，大伙每每鼓励其投稿，奥丽加都不太好意思，但最后还是挑了“最满意”的一首寄了出去。\r\n当被姑娘们问到寄了哪一首时，奥丽加并没有直接回答，而是冲大伙顽皮地挤了挤眼睛，露出一个颇为神秘的笑容：“这首诗，代表着一段珍贵的回忆。”\r\n现在，这份珍贵的回忆于卡琳娜面前缓缓展开了。\r\n\r\n“卡琳娜卫士，您真的没有哪儿不适吗？”护士再度关切地问询。卡琳娜这才意识到自己正在哭泣，止不住的温暖泪水从面颊汩汩淌下，这是她记事起第一次这般哭泣。\r\n“不，没事，真的……没事。”卡琳娜拭去眼泪。金色的阳光倾泻在她身上，她一边默念着奥丽加的诗句，一边把那本诗集紧紧地抱在怀里，她的脑海中浮现出这样一幅画面，多年前的某个冬日午后，和伙伴们相拥在一起的时刻——\r\n姑娘们坐在被晒得热烘烘的草坪上，兴高采烈地描摹着和未来和理想，似乎这世上没有任何东西，可以减损她们眼中晶亮的光芒。"
	},
