		"100051_xiedaiwu_04",
		"卡琳娜使用过的第一台充电装置，性能不怎么稳定。她操纵原体的代价，就是要定时“充电”——字面意义上的充电",
		"卡琳娜静静坐在房间的角落，左臂密密匝匝缠满了电线。\r\n第三次向队伍递出申请后，她终于得到了这架名为“钢铁落雷”的改造原体。作为操纵该原体的代价，每隔一段时间，她就得进行这样的“充电”……灼热、疼痛、痉挛、晕眩，原体过去的使用者曾如此形容自己的经历，但卡琳娜一声不吭，只是垂首坐在那里。\r\n充电完成不久，她就奔赴战场，以一种无所顾忌的姿态，冲在队伍的最前面。所有人的耳朵都能听到那震撼的雷鸣，所有人的双眼都能看到那刺目的电光，而她的敌人往往还来不及躲避、求饶或是诅咒自己的命运，就已经倒在爆炸掀起的滚滚烟尘里。\r\n待到战斗结束，她又坐回到房间的角落，随意用绷带裹好冲锋时所受的创伤，接着熟练将电线缠回左手，为下一次行动做准备——\r\n她仿佛一台冰冷的机器，耗费电力运作，高效地执行着战斗指令，摒弃一切纷乱的情感，人们几乎不会从那张脸上读到任何多余的神色。\r\n但有那么一次，一名刚入伍的小卫士妮娜说她看见了不一样的卡琳娜。\r\n某日，妮娜在庭院里打扫卫生，忽然感受到一道视线，一位银发的、戴眼镜的女性无言地注视着自己，又或者，她注视着的是自己脖颈上的红色围巾。\r\n妮娜立刻认出她是卡琳娜，正犹豫要不要上前搭话，对方便转身一阵风似的走开了。\r\n后来，小卫士在和布狄卡谈天时提起了此事：“那时她眼里在融化……好像春日开冻的溪流，有什么流淌了出来……不，那并不是眼泪——假如看到她流泪，我大概会失声惊叫吧，我、我只是想用比喻来表达某种感情，卡琳娜卫士或许并不像人们说的那样……那样……”\r\n“小妮娜，别着急，我明白你的意思。”布狄卡轻轻点了点头，“你说得对。没有人能全然剔除内心的情感，抛却所有的喜怒哀乐，化为一台冰冷的机器。”\r\n而这才是最令人担心的事。妮娜离开后，布狄卡怀着一丝忧虑地瞥向窗外，卡琳娜缄默地待在那里，与平时别无二致。\r\n恐怕一直以来，她都在自我压抑着，真实的情感与想法如同电流那般被存储堆积，也许总有一天它们将猛烈地爆发，化为震撼的雷鸣和刺目的电光——"
	},
	{
		2000053,
		201,
		1,
		"诊疗日志",
		"100053_xiedaiwu_01",
		"尤克特拉希尔一所郊区医院的病历。格式不太适用于天文台的救援需要，只是出于阿妮亚的个人习惯而仍在使用",
		"没有超凡的迹象。校时者雷雨小队队长霁根据命运之瞳的指示，来到尤克特拉希尔的边陲小镇医院调查一则传闻。情报称，医院接收的危症病人纷纷好转出院，而院方却辞退了所有医护，闭门不纳。霁在空荡无人的医院中搜寻，试图在凌乱的撤离现场中找出密室原体作祟的痕迹，却毫无收获。\r\n当霁打算结束调查时，走廊拐角处的一间病房引起了她的注意。在空旷黑暗的医院里，病房门缝中透出的一丝光线非常显眼。霁放轻脚步靠近，尽量不打扰里面可能存在的人或者物。\r\n\r\n病床上躺着人。她身上插满管子，连接的仪器指数在平稳地走着。床头微弱的暖色灯光照清了她的面容，年轻且平和。\r\n哐当——当霁打算靠近观察时，病房角落却传来物品掉落的声音。在医疗隔帘背后还藏着一个人，轮廓暴露在房内的灯光下。显然，这个娇小身影的主人不善躲藏。\r\n霁走到隔帘旁，捡起掉落的东西，那是一份诊疗日志。她粗略看了一眼，上面的字迹不算好看，但十分端正工整。诊疗日志详细地记录着这位植物病人从本月7日起至今的状况，没有好转的迹象。接着，她打量了一下挤在角落里的女孩，她戴着一顶不合称的大号护士帽，将眼神藏在帽子的阴影下。\r\n\r\n“你就是这里的护士——”霁看了一眼诊疗日志的抬头以确认对方的姓名，“阿妮亚？”\r\n年轻的护士惊讶地往后退了一步，却拒绝正面回答问题，“请……请你离开这里……！”\r\n这位名为阿妮亚的年轻护士不断地在做深呼吸，仿佛生命在遭受极大的威胁，尽管霁只是平常地站在她面前。\r\n在霁还没开口提问之前，护士却停下了深呼吸，声音颤抖地一字一句说道：\r\n“快、快走吧……”\r\n“这里不是人该呆的地方......无论是活人还是死人。”"
	},
	{
		2000053,
		202,
		1,
		"蓝色药剂",
		"100053_xiedaiwu_02",
		"外观与夸克制药生产的成长液相似，但表面有明显的人为加工痕迹。没有益处，但也不会有害",
		"阿妮亚是个普通人。她出生在平凡的家庭，循规蹈矩地完成了学业，毕业后进入当地的小医院，成为一名普通的护士。她充当着每个人生活中都会出现的透明人角色，你不会发现她的过人之处，她也不会刻意强调自己的存在感。\r\n\r\n实际上在普通之外，阿妮亚也有自己的特色。在阿妮亚念小学时，母亲为她准备了许多碳烤小饼干，希望她能用此换来友谊，而阿妮亚却只敢在课间悄悄将小饼干放在同学的抽屉里；中学时代，她下课后只会沿着大马路回家，从来不走那条狭窄但便捷的小巷；成为护士是她这辈子做过最大胆的决定，而她用了整整三个月时间才战胜了医院“瘆人”的白色装潢和消毒水气味。最后，“胆小护士阿妮亚”的名号传遍了整个医院。\r\n因此，当阿妮亚最先发现医院的异常时，比起惊恐和焦虑，她选择了忽视。相信一个“灵异事件”对她的心脏来说是极大的负担。\r\n但是当这些灵异事件不再是偶然时，阿妮亚无法继续忽视下去。最开始，是一名护工的手臂长满淤青，接着是护士的骨头断裂，最后连医生也死在手术台旁。与悲剧相伴的，是病人一个接着一个地好转、康复、出院。\r\n生命的奇怪守恒规律带来的恐惧充斥着所有人的内心，而院方在关闭医院前，必须完成病人的转移。与阿妮亚共同值班的好友兼护士长西芙主动替她承担了照顾植物人的责任，之后发生的事情就如眼前所见：她成为了那位幸运儿的替代，永久地失去了意识。\r\n当厄运直接降临在身边，阿妮亚才反应过来自己无法置身事外。她慌张地将这位唯一的朋友藏在了医院最角落的病房：但所有人忙着逃命，根本没人试图寻找她们。\r\n阿妮亚陷入了绝望。她只能最大限度地维持她的体征，记录她的情况，笨拙地弥补自己胆小和懦弱带来的过错。\r\n\r\n在第八天，阿妮亚决定做出改变。深夜，她溜到医院后门向一位携带乌龟宠物的古怪少女购买了一种药剂——据闻这不仅包治百病，甚至能“起死回生”。阿妮亚从未见过这种药品，皱巴巴的蓝色包装上贴着崭新的便签，不像是来自正规渠道。\r\n阿妮亚遵循计量将让西芙服下药剂，这是她的最后方法。在这个普通的夜晚，阿妮亚开始许愿奇迹的降临。奇迹无法打破规则，反而吸引来了外人的到来。\r\n霁的出现在阿妮亚的预料之外。面对这个还算和善的陌生人抛出的一连串问题，她害怕得无法说出完整的话语。当霁拿出阿妮亚从未见过的的特制仪器进行调查和搜寻时，她的紧张却开始缓解：尽管阿妮亚对这个陌生人一无所知，但从霁的神情和动作可以看出，她不怀一丝恶意。\r\n\r\n在一番调查和思考后，霁严肃地向阿妮亚提出了方案：“你想救她的话，还有机会。”\r\n正当阿妮亚以为自己遇上了救世主，却被下一句话吓破了胆。\r\n“还有三分钟就要进入密室时间，但拯救你的朋友不会是愉快的旅行。”\r\n“提前告诉你，这可能会以你的生命为代价。”\r\n但阿妮亚只考虑了三秒钟就答应了。就这样，普通人阿妮亚第一次进入了密室时间。"
	},
	{
		2000053,
		203,
		1,
		"求职简历",
		"100053_xiedaiwu_03",
		"命运之瞳的简历存档，求职者属于非超凡者。一式两份，每份7页，归还时请注意文档完整",
		"密室中的一切对普通人来说都是危险的，如果没有足够强大的意志，就会永远迷失于此。阿妮亚能清楚地认知到她并不是进入了异空间，只不过她所熟悉的地方受到超凡的影响而变得扭曲和陌生，红色异物渗透到每个角落。在亲自见识到密室与超凡的存在时，阿妮亚对未知的恐惧以及心理压力达到了人生的最高峰。\r\n\r\n身为队长，霁更擅长用真实的语言来稳定人心，而非纯粹的口头安慰。\r\n“跟紧我，我会保证你的安全。”\r\n\r\n接下来发生的事情，阿妮亚记得很清楚。霁带着她在这个熟悉又陌生的空间中四处搜索，最后在一张病床上发现了意识清醒的西芙，她的情况比现实世界中更糟糕——病床仿佛拥有着意识，紧紧地用束带绑着它的猎物，当西芙因为挣扎而失去意识时，这张病床甚至通过更强的束缚来使她清醒。面对这种从未见过的情况，阿妮亚只能用力捂住嘴巴来阻止自己喊叫。\r\n相比于阿妮亚的不知所措，有经验的守秘人霁从制服中拿出盒型装置，用特制的工具解除了病床的束缚，再将这个“死去”的罪魁祸首装进一个巨大的白色密封袋中。阿妮亚难以置信地看着她熟练地完成这套流程，仿佛这项技能融入了她的血液中。\r\n随后，阿妮亚在霁的指示下完成了“心锚”的传递。她回想着自己最重要的事物，让这条火焰一样的链带传到自己手腕上。再接着，阿妮亚在霁的引导下，将这条火焰链带传到西芙手上，将她带出密室——只有足够了解对方，才能建立起最牢固的心锚。\r\n\r\n当密室时间结束，一切都恢复了原样。西芙仍然躺在床上，脸上挂着淡淡的微笑。\r\n“这样……就好了吗？”阿妮亚小心翼翼地询问。\r\n“从决心踏入密室时间的那刻起，你就做得比任何人都要好了。”\r\n\r\n在离开之前，霁给阿妮亚递了一张名片，上面的信息不多，只写着姓名和职务。\r\n“天文台？你是天气预报员吗？”霁没有回答，只是让阿妮亚之后遇到类似问题必须联系她。阿妮亚似懂非懂地点着头。\r\n\r\n霁离开了尤克特拉希尔。命运之瞳的后续情报称，医院得到了某财团的资助，引入了安全且先进的设备，人员也悉数更换。原有的医疗器材，被财团以“科研需要”的名义回收。自此，异闻被遗忘，就像从未发生过，霁也再没有听到过关于这个小镇的消息。\r\n\r\n三个月后，命运之瞳收到了一封特殊的简历。在霁队长的一再坚持下，这名候选人被破格录取。几天后，清理部队迎来了新成员阿妮亚，划分到雷雨小队的编制下，跟随霁队长执行任务。"
	},
	{
		2000053,
		204,
		1,
		"心电监测仪",
		"100053_xiedaiwu_04",
		"具备体征检测、辅助诊断等功能的医护专用型监测仪。原本纯白的外壳有些泛黄，但表面没有污渍，一切功能正常",
		"阿妮亚在雷雨小队的日子比以往要刻苦。雷雨小队主要在极端地区执行任务，每一次外勤任务都像一场战役。在结束了与超凡的战斗后，成员们早已精疲力尽，而这时大家总能看到那个穿着厚重衣物的娇小身影在战场穿梭，熟练地为每位伤员清理和包扎。\r\n\r\n在阿妮亚的医疗设备里，最为宝贵的是那台心电监测仪。阿妮亚称，心跳的线条就是救援的信号，即使当信号停止，她要做的事情也不会结束，这也解释了她为何总是擅自为失控死者的遗体做化妆和整理工作的动机。但擅自执行“入殓”工作的行为并不合规。某一次在热带地区执行任务的过程中，虽然回收了引起植物疯长的密室原体，雷雨小队的一名队员却无法幸免，被密室原体所污染。按照流程，被超凡污染的天文台员工必须立刻隔离并▊▊，避免进一步的扩散。尽管队友早已失去了生命体征，阿妮亚依旧按照自己的意愿执行着抢救和清理工作，她必须将队友的遗体完整并干净地带回总部。她仔细地为队友清除生长在伤口上的向日葵和仙人掌，疯长的植物甚至缠绕在她厚重的防护服上，让她的每个行动都变得更为艰难。\r\n但阿妮亚没有离开的打算。当事态变得无法控制时，队友只能强制将阿妮亚拖离现场，而那位牺牲的队友完全被密室原体所吞噬，她唯一的遗物，只有阿妮亚抢救时连接在她身上的心电监测仪。\r\n第二天，阿妮亚被π部门判定为“情绪异常”及“行为异常”，需要进行为其一个月的停职隔离。霁队长和▊▊博士力排众议驳回了这项决定，并打算给阿妮亚放个长假，她却主动申请参与更多行动。眼周的黑眼圈叠加着泛红的泪痕让她看上去疲惫不堪，却没办法掩盖她的决心。\r\n\r\n总而言之，阿妮亚的出色表现的确有目共睹，在霁队长和多名同事的推荐下，她在入职第一年便获得了“年度最佳员工”称号。从来不曾曝光在众人目光下的阿妮亚感受到前所未有的恐慌，她甚至无法上台领奖。最终，霁队长代她领取了奖杯，悄悄放到她的宿舍中。\r\n这种不为证明自己、也不为名利的行为让雷雨小队成员费解。曾有成员询问霁队长，阿妮亚对于救人的执念到底来自哪里？面对这个问题，霁队长总是缄口不言，甚至打发队员自己去问阿妮亚。\r\n但是连阿妮亚本人也没有思考过这个问题，她只是执着于自己的理念：多出一份力，多救一个人。也许对她来说，每次行动挽回的不仅是生命——就如同她拯救了挚友西芙的灵魂，还有霁队长改变了她的人生一般。"
	},
	{
		2000055,
		201,
		1,
		"公正的天平",
		"100055_xiedaiwu_01",
		"无罪者上浮，有罪者下沉。格里高列认为万事万物皆有尺度，皆有善恶，皆有赏罚，她遵从古老的诫律而生",
		"有形之物什尽数称量，无形之罪孽无所遁藏。\r\n早在伊甸之树与星空隐修会之前，天使种就注视着世界上的灾厄与生机，他们相信一切都在因果律法的掌控之下。\r\n格里高列在还没有生出巨大羽翼的时候，就看过了许多卷审判日志，那上面的字就像天平上的一个个小砝码，能衡量出各种已知的恶行，让小小的天使为之叹服。\r\n西格纳斯有一位衰老的天使，他的羽毛是灰白色的，他的脑中装着许多见闻，比记录成册的审判日志更为丰富，据说，他见过“诫律”审判的情形。格里高列找到他的时候，这位老先生正在劝阻一个小偷改换偷盗目标，他想让小偷放弃偷窃一个中年女人的财物，去偷另一个在喝咖啡的伐木工。“如果今天一定要有所收获的话，请你听我的建议。”他不紧不慢地说完，小偷自然没有采纳这个建议，飞快得手了中年女人的钱包，向老先生的方向炫耀了一下后扬长而去。\r\n格里高列不解，但她没有表现出来，她一直少有情绪。不过老天使很快向她解释了起来:“那个女人经常从这里经过，在不远处的面包店里为自己的女儿买上一小块黑松露蛋糕，听说她的女儿患了病，时间不多了，而那个伐木工男人平时的习惯是下班点酒喝，只有在等情人出现的时候才会用咖啡消磨时间。”\r\n“你觉得，小偷对谁下手会获得更重的处罚？”\r\n“在我看来，都有可能。如果论偷盗的数目，黑松露蛋糕的花费比不上和情人寻欢作乐，但如果小女孩活不过今晚，那位母亲的遗憾会大大加重小偷的罪孽，”老天使没等格里高列回答，自顾自说了起来，“如果被偷的是伐木工，他只能选择在接下来的几天喝廉价酒，因醉醺醺的次数超过了工头的忍耐限度而被开除，一家人都要在这个冬天挨饿。”\r\n“这些都是没有发生的假设。”未来的审判大人很严谨。\r\n“你说的没错，只有审判的法度降临的时候，所有因果才会显现。我不是审判者，我只是一个在天平两端犹疑的人。”\r\n老人认出了格里高列，他留下了一架银质天平，并告诉年轻的天使，在裁决之前，摇摆才是天平的常态。\r\n因与果暗中交织，罪与罚相伴相生。\r\n无罪者上浮，有罪者下沉，天平的公允已经铸成。"
	},
