		"小小的硬币在手里泛着光泽。\r\n格里高列站在月台上，地面上刚积了一层薄雪，空气干冷。\r\n她刚刚完成了任务，开往西格纳斯古勒市方向的列车还有七分钟进站。\r\n如果列车准点到达，她可以去和弗洛伊德下一盘棋。棋子按照既定的规则在黑白格中推进，每次任务结束，这种充满秩序感的小游戏可以给格里高列带来必要的放松。\r\n或者，她可以离开月台。刚才追踪任务目标的时候，格里高列路过了一家水晶艺术品商店，虽然只是余光瞥到一瞬间，但橱窗里的墨晶摇铃折射出的光彩让她印象深刻——阳光被黑色的水晶捕获，又在另一个切面上透出白昼的箭矢。\r\n一个精致的分界线，格里高列想。\r\n所以，应该做什么样的决定呢？站在月台的风里，格里高列感觉到困惑的情绪像新长出来的绒羽一样，引起烦躁的痒。作为“审判”，伊甸诫律的执行者，她从不喜欢拖泥带水，如果在决定阶段游移不定的话，行动也不会顺利。冷酷的审判大人名声在外，以至于有的任务目标一旦逃跑失败就立刻放弃了抵抗，毕竟“诫律”做出的判定是不会更改的。但下棋和墨晶摇铃无关是非（至少现在看起来如此），那么，就交给这枚伊甸古银币吧。\r\n银币被抛起，在翻滚中利落地切割光线，银质的浮雕显示出暗色，不远处传来机械传动的声音，风被压出急促的声音。\r\n列车准时进站，格里高列刚刚站着的位置已经没了人影，只有积雪上留下了一个浅浅的圆形印记。"
