		"格里高列看到过许多次白鹤越冬的景象。\r\n在秋天，鹤群会从更冷的地方迁徙到西格纳斯南部，它们成群掠过的时候，会在云层上借力滑行，变成天空中一团更大的白色，白色啸叫着往前飞，经过西格纳斯的密叶林时就会被挡住，于是鹤群很快舍弃了云层，继续前行。\r\n总有例外，格里高列看到那只白鹤的时候，已经是下雪的冬天了。\r\n没有任务的时候，格里高列就呆在伊甸，“审判”不需要负责巡逻安防，但下过雪以后的几天，她通常会主动在附近巡视起来。在没有人的地方，格里高列会短暂的松懈一会儿，露出天使种的外表特征来，她的羽翼根部是白色的，只在羽尖部分保留着黑色。\r\n据伊甸内部文献记载，完整继承血脉后的天使种，在将下一轮成长周期到来时，呈现出新的古代种特征：在完成蜕变后，它们会生长出完全洁白的羽毛以及毛发，不再沾染一丝黑色，成为“护佑吾等太阳的羽翼”和“执行审判惩戒有罪之人的利剑”，也只有在这个时候，天使种才有资格完整的执掌诫律。\r\n格里高列看着自己黑色的羽尖出神。\r\n突然，不远处的密叶林一阵簌簌落落，一只白鹤落了下来。\r\n准确的说，是一只白鹤掉了下来。那是一只很大的白鹤，虚弱地躺在雪地里，只有腹部一起一伏，落叶和羽毛缠在一起。格里高列抬头看，密叶林树梢上挂着一团云，看来这只落单的白鹤也试图和云层借力，不过，少了同伴们一起振翅的风，它失败了。此刻白鹤开始扭动脖子，再抬起翅膀，动作有点吃力，不过看上去没有受伤，它孤零零一个飞到这里，还活着已经是罕见了。格里高列远远站着，直到这只白鹤终于又站了起来，抖落身上的树叶，用它平静的圆鼓鼓的眼睛看向自己，格里高列不好奇为什么这只白鹤直到下雪还没有完成越冬，白鹤也不好奇这个长着翅膀的家伙手里握着的是什么。他们都有自己要做的事情。\r\n当白鹤再次飞上天空的时候，格里高列发现它的翅膀尖尖也是黑色的，在有节奏的扇动中划出对称的线条。\r\n巡视结束，格里高列带回了一支鹤羽，认真地擦干净了上面的雪粒。"
