		"古代种有一些特异的身体素质，比如耐寒，温度的变化对格里高列几乎没有影响。\r\n所以格里高列为什么会有一条小熊围巾呢？\r\n根据伊甸第▉▉▉号事件跟踪记录，西格纳斯东北部的红雾区是最早形成的几个红雾区之一，附近几个镇子时常有超凡事件发生，在距离红雾不足两百公里的▉▉镇，曾发生了镇民连续失踪的事件，这引起了伊甸的注意。\r\n格里高列带领执行队赶到的时候，感受到镇中小教堂方向传来不断增强的力量扰动。进入教堂，执行员们发现，几名举止怪异的镇民正依次进入教堂的告解室，但却没有一个人出来。一名带着小熊围巾的少女喃喃着“我要忏悔”之类的话，也向着告解室走去。格里高列拉住了她。少女转头看到了格里高列的羽翼，突然对着她忏悔道:“请宽恕我的罪孽，这条围巾是我用米娅姐姐遗落的毛线团偷偷织的，我既不敢告诉她，也不敢戴出门…”\r\n这时，也许是告解室没有人继续进入的缘故，超凡力量的扰动变弱了。执行员们迅速做出了反应，准备配合格里高列对抗原体。\r\n“我最心爱的小熊也在围巾上，请您收下它，宽恕我吧。”少女的话音未落，格里高列的“诫律”已经对准了超凡力量的源头，那间诡异的告解室！\r\n……\r\n\r\n事件以格里高列成功收容原体▉▉▉▉▉结束，他们一行人即将离开的时候，那名在超凡力量下幸运生还的少女拦住了格里高列，她完全不记得教堂中的事情，但仍坚持要把自己的围巾送给格里高列，出乎意料的，格里高列收下了它。\r\n“我想审判大人是认为，那名少女能在近距离遭遇超凡的情况下幸存下来，一定会成为伊甸研究的对象，到时候再把小熊围巾还给她就好了。”伊甸某研究员猜想着。\r\n“但我并没有在相关档案里找到和那名少女有关的任何信息。”伊甸某档案员说道。\r\n“难道说，那个少女…”\r\n“嘘，到此为止吧，要是被审判大人知道我泄露了记录文件，‘诫律’是不会放过我的！记住，审判大人从来都没有收藏什么小熊围巾。”"
